{"command": "cd /workspace; python3 - <<'PYEOF'
import os,sys
def q(s):
    # produce a Go string literal
    out=[]
    for ch in s:
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\n': out.append('\\n')
        elif ch=='\t': out.append('\\t')
        elif ch=='\r': out.append('\\r')
        elif ord(ch)<32 or ord(ch)>126: out.append('\\u%04x'%ord(ch))
        else: out.append(ch)
    return '"%s"'%''.join(out)

def read(p):
    return open('captured/'+p, encoding='utf-8', errors='surrogateescape').read()

# verbs
txt=read('usage-verbs.txt')
lines=txt.split('\n')
sep='='*64
verbs={}
cur=None;buf=[]
for ln in lines:
    if ln==sep:
        if cur is not None: verbs[cur]='\n'.join(buf).rstrip('\n')
        cur=None;buf=[]
    elif ln=='' :
        if cur is None: continue
        buf.append(ln)
    else:
        if cur is None:
            cur=ln.strip(); buf=[ln]
        else: buf.append(ln)
if cur is not None: verbs[cur]='\n'.join(buf).rstrip('\n')

# functions
funcs={}
for e in read('usage-functions.txt').split('\n\n'):
    e=e.rstrip('\n')
    if not e.strip(): continue
    m=re.match(r'^(\S+)',e)
    if m: funcs[m.group(1)]=e

# keywords
kws={}
for e in read('usage-keywords.txt').split('\n\n'):
    e=e.rstrip('\n')
    if not e.strip(): continue
    m=re.match(r'^([A-Za-z0-9_]+):',e)
    if m: kws[m.group(1)]=e

# flags
import glob
flags={}
for p in glob.glob('captured/flag*.txt'):
    name=os.path.basename(p)[4:-4]
    flags[name]=read(p).rstrip('\n')

# topics
topics={}
for p in glob.glob('captured/topic-*.txt'):
    name=os.path.basename(p)[6:-4]
    topics[name]=read(p).rstrip('\n')

classes=[l.strip() for l in read('list-function-classes.txt').split('\n') if l.strip()]

def emit(f, m):
    f.write('var %s = map[string]string{\n'%m.__name__)
    for k in sorted(m):
        f.write('\t%s: %s,\n'%(q(k),q(m[k])))
    f.write('}\n\n')

with open('helpdata.go','w') as f:
    f.write('// Code generated from transcribed "mlr help" output. DO NOT EDIT MANUALLY.\n')
    f.write('package main\n\n')
    emit(f,verbs)
    emit(f,funcs)
    emit(f,kws)
    emit(f,flags)
    emit(f,topics)
    f.write('var functionClasses = []string{\n')
    for c in classes: f.write('\t%s,\n'%q(c))
    f.write('}\n')
print(len(verbs),len(funcs),len(kws),len(flags),len(topics))
PYEOF
gofmt -l . 2>&1 | head; wc -c helpdata.go"}

