package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Kind enumerates the Miller value types.
type Kind uint8

const (
	KindNull Kind = iota
	KindBool
	KindInt
	KindFloat
	KindString
	KindArray
	KindMap
)

// Value is a Miller value. Numbers carry their source literal (if any) so
// that pass-through output preserves the original spelling.
type Value struct {
	Kind Kind
	S    string
	I    int64
	F    float64
	Lit  string
	B    bool
	A    []Value
	M    *Map
}

// Map is an insertion-ordered string-keyed map.
type Map struct {
	keys []string
	idx  map[string]int
	vals []Value
}

func NewMap() *Map {
	return &Map{idx: make(map[string]int)}
}

func (m *Map) Len() int { return len(m.keys) }

func (m *Map) Has(k string) bool {
	if m == nil {
		return false
	}
	_, ok := m.idx[k]
	return ok
}

func (m *Map) Get(k string) (Value, bool) {
	if m == nil {
		return Value{Kind: KindNull}, false
	}
	i, ok := m.idx[k]
	if !ok {
		return Value{Kind: KindNull}, false
	}
	return m.vals[i], true
}

func (m *Map) Set(k string, v Value) {
	if m.idx == nil {
		m.idx = make(map[string]int)
	}
	if i, ok := m.idx[k]; ok {
		m.vals[i] = v
		return
	}
	m.idx[k] = len(m.keys)
	m.keys = append(m.keys, k)
	m.vals = append(m.vals, v)
}

func (m *Map) SetAll(o *Map) {
	if o == nil {
		return
	}
	for i, k := range o.keys {
		m.Set(k, o.vals[i])
	}
}

func (m *Map) Unset(k string) bool {
	if m == nil {
		return false
	}
	i, ok := m.idx[k]
	if !ok {
		return false
	}
	delete(m.idx, k)
	m.keys = append(m.keys[:i], m.keys[i+1:]...)
	m.vals = append(m.vals[:i], m.vals[i+1:]...)
	for j := i; j < len(m.keys); j++ {
		m.idx[m.keys[j]] = j
	}
	return true
}

func (m *Map) Keys() []string {
	if m == nil {
		return nil
	}
	return m.keys
}

func (m *Map) Values() []Value {
	if m == nil {
		return nil
	}
	return m.vals
}

func (m *Map) Clone() *Map {
	if m == nil {
		return NewMap()
	}
	n := NewMap()
	n.keys = append(n.keys, m.keys...)
	n.vals = append(n.vals, m.vals...)
	n.idx = make(map[string]int, len(m.idx))
	for k, i := range m.idx {
		n.idx[k] = i
	}
	return n
}

// Constructors

func NullValue() Value      { return Value{Kind: KindNull} }
func BoolValue(b bool) Value { return Value{Kind: KindBool, B: b} }
func IntValue(i int64) Value { return Value{Kind: KindInt, I: i} }
func FloatValue(f float64) Value {
	return Value{Kind: KindFloat, F: f}
}
func StringValue(s string) Value { return Value{Kind: KindString, S: s} }
func ArrayValue(a []Value) Value { return Value{Kind: KindArray, A: a} }
func MapValue(m *Map) Value      { return Value{Kind: KindMap, M: m} }

func (v Value) IsNumber() bool { return v.Kind == KindInt || v.Kind == KindFloat }

// Parse helpers

func parseNumber(s string) (Value, bool) {
	if s == "" {
		return NullValue(), false
	}
	c := s[0]
	if !(c == '-' || c == '+' || (c >= '0' && c <= '9') || c == '.') {
		return NullValue(), false
	}
	if c == '.' {
		// .5 ok; a lone "." is not a number
		if len(s) == 1 || s[1] < '0' || s[1] > '9' {
			return NullValue(), false
		}
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return Value{Kind: KindInt, I: i, Lit: s}, true
	}
	// things like 007, 1_000 are not numbers by default
	if c == '+' || c == '-' {
		rest := s[1:]
		if len(rest) == 0 {
			return NullValue(), false
		}
		if rc := rest[0]; rc == '+' || rc == '-' {
			return NullValue(), false
		}
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return Value{Kind: KindFloat, F: f, Lit: s}, true
	}
	return NullValue(), false
}

// fmtFloat renders a float the way Miller does for computed values.
func fmtFloat(f float64) string {
	if f != f {
		return "NaN"
	}
	if f > 1.797693134862315708145227e308 {
		return "+Inf"
	}
	if f < -1.797693134862315708145227e308 {
		return "-Inf"
	}
	return strconv.FormatFloat(f, 'f', -1, 64)
}

// String renders the value the way Miller does in delimiter-separated output
// formats.
func (v Value) String() string {
	switch v.Kind {
	case KindNull:
		return "null"
	case KindBool:
		if v.B {
			return "true"
		}
		return "false"
	case KindInt:
		if v.Lit != "" {
			return v.Lit
		}
		return strconv.FormatInt(v.I, 10)
	case KindFloat:
		if v.Lit != "" {
			return v.Lit
		}
		return fmtFloat(v.F)
	case KindString:
		return v.S
	case KindArray:
		var b strings.Builder
		b.WriteString("[")
		for i, e := range v.A {
			if i > 0 {
				b.WriteString(", ")
			}
			b.WriteString(e.String())
		}
		b.WriteString("]")
		return b.String()
	case KindMap:
		var b strings.Builder
		b.WriteString("{")
		for i, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			if i > 0 {
				b.WriteString(", ")
			}
			b.WriteString(k)
			b.WriteString(": ")
			b.WriteString(val.String())
		}
		b.WriteString("}")
		return b.String()
	}
	return ""
}

// JSON rendering

func jsonQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			if r < 0x20 {
				fmt.Fprintf(&b, "\\u%04x", r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func jsonFloat(f float64) string {
	if f != f {
		return "NaN"
	}
	if f > 1.797693134862315708145227e308 {
		return "+Inf"
	}
	if f < -1.797693134862315708145227e308 {
		return "-Inf"
	}
	return strconv.FormatFloat(f, 'f', -1, 64)
}

func (v Value) JSON(sb *strings.Builder) {
	switch v.Kind {
	case KindNull:
		sb.WriteString("null")
	case KindBool:
		if v.B {
			sb.WriteString("true")
		} else {
			sb.WriteString("false")
		}
	case KindInt:
		if v.Lit != "" {
			sb.WriteString(v.Lit)
		} else {
			sb.WriteString(strconv.FormatInt(v.I, 10))
		}
	case KindFloat:
		if v.Lit != "" {
			sb.WriteString(v.Lit)
		} else {
			sb.WriteString(jsonFloat(v.F))
		}
	case KindString:
		sb.WriteString(jsonQuote(v.S))
	case KindArray:
		sb.WriteString("[")
		for i, e := range v.A {
			if i > 0 {
				sb.WriteString(", ")
			}
			e.JSON(sb)
		}
		sb.WriteString("]")
	case KindMap:
		sb.WriteString("{")
		for i, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(jsonQuote(k))
			sb.WriteString(": ")
			val.JSON(sb)
		}
		sb.WriteString("}")
	}
}
