func renderRecordJSON(sb *strings.Builder, rec *Record, stack bool, depth int) {
	keys := rec.Keys()
	if !stack {
		sb.WriteString("{")
		for i, k := range keys {
			v, _ := rec.Get(k)
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(jsonQuote(k))
			sb.WriteString(": ")
			v.JSON(sb)
		}
		sb.WriteString("}")
		return
	}
	sb.WriteString("{")
	if len(keys) == 0 {
		sb.WriteString("}")
		return
	}
	sb.WriteString("\n")
	for i, k := range keys {
		v, _ := rec.Get(k)
		indent(sb, depth+1)
		sb.WriteString(jsonQuote(k))
		sb.WriteString(": ")
		if isLeafJSON(v) {
			v.JSON(sb)
			sb.WriteString("\n")
		} else {
			writeJSONNested(sb, v, depth+1)
		}
		if i < len(keys)-1 {
			sb.WriteString(",")
		}
	}
	indent(sb, depth)
	sb.WriteString("}")
}

func indent(sb *strings.Builder, n int) {
	for i := 0; i < n; i++ {
