// Record is an insertion-ordered map of field values.
type Record = Map

type Reader interface {
	Next() (*Record, error)
	Close() error
}

// ---- DKVP / NIDX / CSV / TSV line-oriented readers ----

type lineReader struct {
	r          io.Reader
	opt        *Options
	split      func(string) []string
	makeRecord func(fields []string) *Record
	line       int
	header     []string
	headerSet  bool
