		fields := lr.split(line)
		return lr.makeRecord(fields), nil
	}
}

func isCommentLine(line string, opt *Options) (bool, string) {
	p := opt.CommentsPrefix
	if opt.CommentsMode == CommentsNone {
		return false, ""
	}
	if !strings.HasPrefix(line, p) {
		return false, ""
	}
	return true, strings.TrimPrefix(line, p)
}

func (lr *lineReader) readLine() (string, error) {
	return lr.readLineImpl()
}

func (lr *lineReader) readLineImpl() (string, error) {
	panic("not implemented")
}

func splitOn(fs string, repifs bool, s string) []string {
	if fs == "" {
		return []string{s}
	}
	if repifs {
		return strings.FieldsFunc(s, func(r rune) bool { return strings.ContainsRune(fs, r) })
	}
	return strings.Split(s, fs)
}

// DKVP

type dkvpRecord struct{}

func dkvpMake(opt *Options) func([]string) *Record {
	return func(fields []string) *Record {
		rec := NewMap()
		next := 1
		keyless := 0
		for _, f := range fields {
			var k, v string
			if i := strings.Index(f, opt.IPS); i >= 0 {
				k = f[:i]
				v = f[i+len(opt.IPS):]
			} else {
				v = f
				if opt.IncrKey {
					keyless++
					k = strconv.Itoa(keyless)
				} else {
					k = strconv.Itoa(next)
				}
			}
			if !opt.IncrKey {
				next++
			}
			val := inferValue(v)
			// duplicate keys: later wins but keeps position
			if rec.Has(k) {
				rec.Unset(k)
			}
			rec.Set(k, val)
		}
		return rec
	}
}

// inferValue types a raw text field value.
func inferValue(s string) Value {
	if v, ok := parseNumber(s); ok {
		return v
	}
	return StringValue(s)
}

// nidx

func nidxMake(opt *Options) func([]string) *Record {
	return func(fields []string) *Record {
		rec := NewMap()
		for i, f := range fields {
			rec.Set(strconv.Itoa(i+1), inferValue(f))
		}
		return rec
	}
}

// csv / tsv

func csvMake(opt *Options) (func([]string) *Record, func(*lineReader, []string) error) {
	return nil, nil
}

// ---- writers ----

type Writer interface {
	Write(rec *Record) error
	WriteEnd() error
}

// flatten a value into key/value pairs appended to the given map
func flattenValue(k string, v Value, sep string, out []kv) []kv {
	switch v.Kind {
	case KindMap:
		if v.M.Len() == 0 {
			out = append(out, kv{k, v})
			return out
		}
		for _, kk := range v.M.Keys() {
			val, _ := v.M.Get(kk)
			out = flattenValue(joinKey(k, kk, sep), val, sep, out)
		}
		return out
	case KindArray:
		if len(v.A) == 0 {
			out = append(out, kv{k, v})
			return out
		}
		for i, e := range v.A {
			out = flattenValue(joinKey(k, strconv.Itoa(i+1), sep), e, sep, out)
		}
		return out
	default:
		out = append(out, kv{k, v})
		return out
	}
}

func joinKey(a, b, sep string) string {
	if a == "" {
		return b
	}
	return a + sep + b
}

type kv struct {
	k string
	v Value
}

// dkvpWriter

type dkvpWriter struct {
	opt *Options
	out io.Writer
}

func (w *dkvpWriter) Write(rec *Record) error {
	pairs := []kv{}
	for _, k := range rec.Keys() {
		v, _ := rec.Get(k)
		pairs = flattenValue(k, v, w.opt.FlatSep, pairs)
	}
	var b strings.Builder
	for i, p := range pairs {
		if i > 0 {
			b.WriteString(w.opt.OFS)
		}
		b.WriteString(p.k)
		b.WriteString(w.opt.OPS)
		b.WriteString(p.v.String())
	}
	fmt.Fprintln(w.out, b.String())
	return nil
}

func (w *dkvpWriter) WriteEnd() error { return nil }

type nidxWriter struct {
	opt *Options
	out io.Writer
}

func (w *nidxWriter) Write(rec *Record) error {
	pairs := []kv{}
	for _, k := range rec.Keys() {
		v, _ := rec.Get(k)
		pairs = flattenValue(k, v, w.opt.FlatSep, pairs)
	}
	var b strings.Builder
	for i, p := range pairs {
		if i > 0 {
			b.WriteString(w.opt.OFS)
		}
		b.WriteString(p.v.String())
	}
	fmt.Fprintln(w.out, b.String())
	return nil
}

func (w *nidxWriter) WriteEnd() error { return nil }

// csv/tsv writer

type csvWriter struct {
	opt    *Options
	out    io.Writer
	header []string
	seen   bool
	quoted bool // csv (quote when needed) vs tsv (never quote)
	ho     bool
}

func csvQuote(s string, opt *Options) string {
	if opt.QuoteAll {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	if strings.Contains(s, opt.OFS) || strings.Contains(s, "\n") || strings.Contains(s, "\r") || strings.Contains(s, "\"") {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	return s
}

func (w *csvWriter) Write(rec *Record) error {
	keys := rec.Keys()
	if !w.seen {
		w.seen = true
		if !w.opt.HeaderlessOut {
			w.header = keys
			w.emitHeader()
		}
	} else if w.opt.AutoUnsparsify && !sameKeys(keys, w.header) {
		if !w.opt.HeaderlessOut {
			fmt.Fprintln(w.out)
			w.header = keys
			w.emitHeader()
		}
	}
	var b strings.Builder
	for i, k := range w.header {
		if i > 0 {
			b.WriteString(w.opt.OFS)
		}
		v, ok := rec.Get(k)
		if !ok {
			continue
		}
		var sv string
		if w.quoted {
			sv = csvQuote(v.String(), w.opt)
		} else {
			sv = v.String()
		}
		b.WriteString(sv)
	}
	fmt.Fprintln(w.out, b.String())
	return nil
}

func (w *csvWriter) emitHeader() {
	var b strings.Builder
	for i, k := range w.header {
		if i > 0 {
			b.WriteString(w.opt.OFS)
		}
		if w.quoted {
			b.WriteString(csvQuote(k, w.opt))
		} else {
			b.WriteString(k)
		}
	}
	fmt.Fprintln(w.out, b.String())
}

func sameKeys(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func (w *csvWriter) WriteEnd() error { return nil }

// json writers

type jsonWriter struct {
	opt      *Options
	out      io.Writer
	first    bool
	wrap     bool
	jvstack  bool
}

func (w *jsonWriter) Write(rec *Record) error {
	if w.first && w.wrap {
		fmt.Fprintln(w.out, "[")
	}
	w.first = false
	var sb strings.Builder
	renderRecordJSON(&sb, rec, w.jvstack, 0)
	fmt.Fprint(w.out, sb.String())
	if w.wrap {
		fmt.Fprintln(w.out, ",")
	} else {
		fmt.Fprintln(w.out)
	}
	return nil
}

func (w *jsonWriter) WriteEnd() error {
	if w.wrap {
		fmt.Fprintln(w.out, "]")
	}
	return nil
}

func renderRecordJSON(sb *strings.Builder, rec *Record, stack bool, depth int) {
	keys := rec.Keys()
	if !stack {
		sb.WriteString("{")
		for i, k := range keys {
			v, _ := rec.Get(k)
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(jsonQuote(k))
			sb.WriteString(": ")
			v.JSON(sb)
		}
		sb.WriteString("}")
		return
	}
	sb.WriteString("{")
	if len(keys) == 0 {
		sb.WriteString("}")
		return
	}
	sb.WriteString("\n")
	for i, k := range keys {
		v, _ := rec.Get(k)
		indent(sb, depth+1)
		sb.WriteString(jsonQuote(k))
		sb.WriteString(": ")
		if isLeafJSON(v) {
			v.JSON(sb)
			sb.WriteString("\n")
		} else {
			writeJSONNested(sb, v, depth+1)
		}
		if i < len(keys)-1 {
			sb.WriteString(",")
		}
	}
	indent(sb, depth)
	sb.WriteString("}")
}

func indent(sb *strings.Builder, n int) {
	for i := 0; i < n; i++ {
		sb.WriteString("  ")
	}
}

func isLeafJSON(v Value) bool {
	switch v.Kind {
	case KindMap:
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			if !isLeafJSON(val) {
				return false
			}
		}
		return true
	case KindArray:
		for _, e := range v.A {
			if !isLeafJSON(e) {
				return false
			}
		}
		return true
	}
	return true
}

func writeJSONNested(sb *strings.Builder, v Value, depth int) {
	switch v.Kind {
	case KindMap:
		if v.M.Len() == 0 {
			sb.WriteString("{}\n")
			return
		}
		sb.WriteString("{\n")
		keys := v.M.Keys()
		for i, k := range keys {
			val, _ := v.M.Get(k)
			indent(sb, depth+1)
			sb.WriteString(jsonQuote(k))
			sb.WriteString(": ")
			if isLeafJSON(val) {
				val.JSON(sb)
				sb.WriteString("\n")
			} else {
				writeJSONNested(sb, val, depth+1)
			}
			if i < len(keys)-1 {
				sb.WriteString(",")
			}
		}
		indent(sb, depth)
		sb.WriteString("}\n")
	case KindArray:
		if len(v.A) == 0 {
			sb.WriteString("[]\n")
			return
		}
		sb.WriteString("[\n")
		for i, e := range v.A {
			indent(sb, depth+1)
			if isLeafJSON(e) {
				e.JSON(sb)
				sb.WriteString("\n")
			} else {
				writeJSONNested(sb, e, depth+1)
			}
			if i < len(v.A)-1 {
				sb.WriteString(",")
			}
		}
		indent(sb, depth)
		sb.WriteString("]\n")
	}
}

// JSON reader

type jsonReader struct {
	data    []byte
	pos     int
	jsonl   bool
	opt     *Options
	inArray bool
	started bool
}

func (jr *jsonReader) Next() (*Record, error) {
	for {
		jr.skipWS()
		if jr.pos >= len(jr.data) {
			return nil, io.EOF
		}
		if !jr.jsonl && !jr.started {
			jr.started = true
			if jr.data[jr.pos] == '[' {
				jr.pos++
				jr.inArray = true
			}
		}
		if !jr.jsonl && jr.inArray {
			jr.skipWS()
			if jr.pos < len(jr.data) && (jr.data[jr.pos] == ']' || jr.data[jr.pos] == ',') {
				jr.pos++
				continue
			}
		}
		if jr.jsonl {
			jr.skipWS()
		}
		v, err := parseJSON(jr)
		if err != nil {
			return nil, err
		}
		rec, ok := recordFromJSON(v)
		if !ok {
			return nil, fmt.Errorf("mlr: JSON input: expected map, found %s", v.String())
		}
		return rec, nil
	}
}

func (jr *jsonReader) skipWS() {
	for jr.pos < len(jr.data) {
		c := jr.data[jr.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			jr.pos++
			continue
		}
		break
	}
}

func parseJSON(jr *jsonReader) (Value, error) {
	jr.skipWS()
	if jr.pos >= len(jr.data) {
		return NullValue(), io.EOF
	}
	c := jr.data[jr.pos]
	switch {
	case c == '{':
		jr.pos++
		m := NewMap()
		for {
			jr.skipWS()
			if jr.pos >= len(jr.data) {
				return NullValue(), fmt.Errorf("mlr: JSON parse error")
			}
			if jr.data[jr.pos] == '}' {
				jr.pos++
				break
			}
			if jr.data[jr.pos] == ',' {
				jr.pos++
				continue
			}
			kv, err := parseJSONString(jr)
			if err != nil {
				return NullValue(), err
			}
			jr.skipWS()
			if jr.pos >= len(jr.data) || jr.data[jr.pos] != ':' {
				return NullValue(), fmt.Errorf("mlr: JSON parse error: expected colon")
			}
			jr.pos++
			v, err := parseJSON(jr)
			if err != nil {
				return NullValue(), err
			}
			m.Set(kv, v)
		}
		return MapValue(m), nil
	case c == '[':
		jr.pos++
		arr := []Value{}
		for {
			jr.skipWS()
			if jr.pos >= len(jr.data) {
				return NullValue(), fmt.Errorf("mlr: JSON parse error")
			}
			if jr.data[jr.pos] == ']' {
				jr.pos++
				break
			}
			if jr.data[jr.pos] == ',' {
				jr.pos++
				continue
			}
			v, err := parseJSON(jr)
			if err != nil {
				return NullValue(), err
			}
			arr = append(arr, v)
		}
		return Value{Kind: KindArray, A: arr}, nil
	case c == '"':
		s, err := parseJSONString(jr)
		return StringValue(s), err
	case c == 't':
		if bytes.HasPrefix(jr.data[jr.pos:], []byte("true")) {
			jr.pos += 4
			return BoolValue(true), nil
		}
	case c == 'f':
		if bytes.HasPrefix(jr.data[jr.pos:], []byte("false")) {
			jr.pos += 5
			return BoolValue(false), nil
		}
	case c == 'n':
		if bytes.HasPrefix(jr.data[jr.pos:], []byte("null")) {
			jr.pos += 4
			return NullValue(), nil
		}
	}
	// number
	start := jr.pos
	for jr.pos < len(jr.data) {
		ch := jr.data[jr.pos]
		if (ch >= '0' && ch <= '9') || ch == '-' || ch == '+' || ch == '.' || ch == 'e' || ch == 'E' {
			jr.pos++
			continue
		}
		break
	}
	s := string(jr.data[start:jr.pos])
	if s == "" {
		return NullValue(), fmt.Errorf("mlr: JSON parse error at offset %d", start)
	}
	if v, ok := parseNumber(s); ok {
		return v, nil
	}
	return StringValue(s), nil
}

func parseJSONString(jr *jsonReader) (string, error) {
	jr.skipWS()
	if jr.pos >= len(jr.data) || jr.data[jr.pos] != '"' {
		return "", fmt.Errorf("mlr: JSON parse error: expected string")
	}
	jr.pos++
	var b strings.Builder
	for jr.pos < len(jr.data) {
		c := jr.data[jr.pos]
		jr.pos++
		if c == '"' {
			return b.String(), nil
		}
		if c == '\\' {
			if jr.pos >= len(jr.data) {
				break
			}
			e := jr.data[jr.pos]
			jr.pos++
			switch e {
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			case '/':
				b.WriteByte('/')
			case 'b':
				b.WriteByte('\b')
			case 'f':
				b.WriteByte('\f')
			case 'n':
				b.WriteByte('\n')
			case 'r':
				b.WriteByte('\r')
			case 't':
				b.WriteByte('\t')
			case 'u':
				if jr.pos+4 <= len(jr.data) {
					h := string(jr.data[jr.pos : jr.pos+4])
					if n, err := strconv.ParseUint(h, 16, 32); err == nil {
						b.WriteRune(runeFromInt(int(n)))
						jr.pos += 4
					}
				}
			}
			continue
		}
		b.WriteByte(c)
	}
	return b.String(), fmt.Errorf("mlr: JSON parse error: unterminated string")
}

func runeFromInt(n int) rune { return rune(n) }

func recordFromJSON(v Value) (*Record, bool) {
	if v.Kind != KindMap {
		return nil, false
	}
	return v.M, true
}

// readers registry

type fileReader struct {
	opt  *Options
	r    io.Reader
	line []byte
	done bool
}

func NewLineReader(opt *Options, r io.Reader) *fileReader {
	return &fileReader{opt: opt, r: r}
}

func (fr *fileReader) Next() (*Record, error) {
	for {
		if fr.done {
			return nil, io.EOF
		}
		line, err := readLineBytes(fr)
		if err != nil && err != io.EOF {
			return nil, err
		}
		if err == io.EOF && fr.line == nil {
			return nil, io.EOF
		}
		if err == io.EOF {
			fr.done = true
			s := string(fr.line)
			fr.line = nil
			if s == "" {
				return nil, io.EOF
			}
			return fr.makeRecord(s), nil
		}
		s := string(fr.line)
		fr.line = nil
		if fr.opt.CommentsMode != CommentsNone {
			if ok, c := isCommentLine(s, fr.opt); ok {
				if fr.opt.CommentsMode == CommentsPass {
					fmt.Println(fr.opt.CommentsPrefix + c)
				}
				continue
			}
		}
		return fr.makeRecord(s), nil
	}
}

func readLineBytes(fr *fileReader) (string, error) {
	var b strings.Builder
	buf := make([]byte, 1)
	for {
		n, err := fr.r.Read(buf)
		if n > 0 {
			if buf[0] == '\n' {
				return b.String(), nil
			}
			b.WriteByte(buf[0])
		}
		if err == io.EOF {
			if b.Len() == 0 {
				return "", io.EOF
			}
			return b.String(), nil
		}
		if err != nil {
			return "", err
		}
	}
}

func (fr *fileReader) makeRecord(line string) *Record {
	switch fr.opt.IFormat {
	case FormatDKVP:
		return dkvpMake(fr.opt)(splitOn(fr.opt.IFS, false, line))
	case FormatNIDX:
		return nidxMake(fr.opt)(splitOn(fr.opt.IFS, fr.opt.RepIfs, line))
	case FormatCSV, FormatTSV:
		return fr.csvRecord(line)
	case FormatPPrint:
		return nidxMake(fr.opt)(splitOn(fr.opt.IFS, false, line))
	}
	return NewMap()
}

func (fr *fileReader) csvRecord(line string) *Record {
	fields := splitOn(fr.opt.IFS, false, line)
	if !fr.opt.ImplicitCSVHeader {
		if !fr.hasHeader {
			fr.hasHeader = true
			fr.header = fields
			return nilSkip
		}
		rec := NewMap()
		for i, h := range fr.header {
			if i < len(fields) {
				rec.Set(h, inferValue(fields[i]))
			} else if fr.opt.AllowRagged {
				rec.Set(h, StringValue(""))
			} else {
				return nilRagged
			}
		}
		for i := len(fr.header); i < len(fields); i++ {
			if fr.opt.AllowRagged {
				rec.Set(strconv.Itoa(i+1), inferValue(fields[i]))
			}
		}
		return rec
	}
	rec := NewMap()
	for i, f := range fields {
		rec.Set(strconv.Itoa(i+1), inferValue(f))
	}
	return rec
}

var nilSkip = NewMap()
var nilRagged = NewMap()

func (fr *fileReader) Close() error {
	if c, ok := fr.r.(io.Closer); ok {
		return c.Close()
	}
	return nil
}

func SortStrings(a []string) { sort.Strings(a) }

