	FromFiles  []string
	FileList   string

	NoAutoFlatten   bool
	NoAutoUnflatten bool

	HashRecords bool

	// internal
	Explicit map[string]bool
}

func NewOptions() *Options {
	o := &Options{
		IFormat:      FormatDKVP,
		OFormat:      FormatDKVP,
		IFS:          PlainSep(","),
		OFS:          PlainSep(","),
		IPS:          PlainSep("="),
		OPS:          PlainSep("="),
		IRS:          PlainSep("\n"),
		ORS:          PlainSep("\n"),
		NestedFS:     ";",
		NestedPS:     ":",
		FlatSep:      ".",
		GenFieldName: "i",
		GenStart:     1,
		GenStep:      1,
		GenStop:      100,
		JvStack:      true,
		JListWrap:    true,
		YArray:       true,
		AutoUnsparsify: true,
		HashRecords:    true,
		Explicit:    make(map[string]bool),
	}
	return o
}

func (o *Options) SetExplicit(name string) { o.Explicit[name] = true }

func (o *Options) IsExplicit(name string) bool { return o.Explicit[name] }

func ApplySeparator(o *Options, which string, v string, re bool) {
	s := Separator{Text: v, IsRe: re}
	if v == "auto" {
		s.Auto = true
	}
	switch which {
	case "fs":
		o.IFS = s
		o.OFS = s
	case "ifs":
		o.IFS = s
	case "ofs":
		o.OFS = s
	case "ps":
		o.IPS = s
		o.OPS = s
	case "ips":
		o.IPS = s
	case "ops":
		o.OPS = s
	case "rs":
		o.IRS = s
		o.ORS = s
	case "irs":
		o.IRS = s
	case "ors":
		o.ORS = s
	}
}

// resolveSeparatorAliases maps things like "space", "tab", "comma" to strings.
var sepAliases = map[string]string{
	"ascii_esc": "\x1b", "ascii_etx": "\x03", "ascii_fs": "\x1c", "ascii_gs": "\x1d",
	"ascii_null": "\x00", "ascii_rs": "\x1e", "ascii_soh": "\x01", "ascii_stx": "\x02",
	"ascii_us": "\x1f", "asv_fs": "\x1f", "asv_rs": "\x1e",
	"colon": ":", "comma": ",", "cr": "\r", "crcr": "\r\r", "crlf": "\r\n",
	"crlfcrlf": "\r\n\r\n", "equals": "=", "lf": "\n", "lflf": "\n\n",
	"newline": "\n", "pipe": "|", "semicolon": ";", "slash": "/", "space": " ",
	"tab": "\t", "usv_fs": "\xe2\x90\x9f", "usv_rs": "\xe2\x90\x9e",
	"spaces": "( )+", "tabs": "(	)+", "whitespace": "([ 	])+",
}

func ResolveSep(s string) (string, bool) {
	if v, ok := sepAliases[s]; ok {
		return v, true
	}
	return s, false
}

// separatorRegexAliases are regex-flavored aliases
var sepRegexAliases = map[string]string{
	"spaces": "( )+", "tabs": "(	)+", "whitespace": "([ 	])+",
}

func IsRegexAlias(s string) bool {
	_, ok := sepRegexAliases[s]
	return ok
}

// formatDefaults sets the default separators for a format, unless the user has
// explicitly overridden them.
func formatDefaults(o *Options, f Format, side string) {
	explicit := func(n string) bool {
		if side == "in" {
			return o.IsExplicit(n)
		}
		return o.IsExplicit(n)
	}
	switch f {
	case FormatDKVP:
		if !explicit("ifs") && !explicit("fs") {
			o.IFS = PlainSep(",")
		}
		if !explicit("ops") && !explicit("ps") {
			o.OPS = PlainSep("=")
		}
	case FormatNIDX:
		if !explicit("ifs") && !explicit("fs") {
			o.IFS = PlainSep(" ")
		}
	case FormatCSV, FormatCSVLite:
		if !explicit("ifs") && !explicit("fs") {
			o.IFS = PlainSep(",")
		}
	case FormatTSV, FormatTSVLite:
		if !explicit("ifs") && !explicit("fs") {
			o.IFS = PlainSep("\t")
		}
	case FormatPPrint:
		if !explicit("ofs") && !explicit("fs") {
			o.OFS = PlainSep(" ")
		}
	case FormatXTAB:
		if !explicit("ops") && !explicit("ps") {
			o.OPS = PlainSep(" ")
		}
		if !explicit("ifs") && !explicit("fs") {
			o.IFS = Separator{Auto: true}
		}
		if !explicit("irs") && !explicit("rs") {
			o.IRS = Separator{Auto: true}
		}
	}
}

func SetFormat(o *Options, which string, name string) error {
	f, ok := FormatByName(name)
	if !ok {
		return fmt.Errorf("mlr: unrecognized I/O format \"%s\".", name)
	}
	switch which {
	case "both":
		o.IFormat = f
		o.OFormat = f
		formatDefaults(o, f, "both")
	case "in":
		o.IFormat = f
		formatDefaults(o, f, "in")
	case "out":
		o.OFormat = f
		formatDefaults(o, f, "out")
	}
	return nil
}

var formatNames = map[string]Format{
	"csv": FormatCSV, "csvlite": FormatCSVLite, "tsv": FormatTSV, "tsvlite": FormatTSVLite,
	"dkvp": FormatDKVP, "nidx": FormatNIDX, "json": FormatJSON, "jsonl": FormatJSONL,
	"xtab": FormatXTAB, "pprint": FormatPPrint, "markdown": FormatMarkdown, "md": FormatMarkdown,
	"dcf": FormatDCF, "asv": FormatASV, "asvlite": FormatASV, "usv": FormatUSV,
	"usvlite": FormatUSV, "yaml": FormatYAML,
}

func FormatByName(name string) (Format, bool) {
	f, ok := formatNames[name]
	return f, ok
}

// SetInFormat sets the input format with the same default-separator logic.
func SetInFormat(o *Options, f Format) {
	o.IFormat = f
