{"command": "cd /workspace; cat > recordio.go <<'GOEOF'
package main

import (
	"bufio"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// Record is an insertion-ordered map of field values.
type Record = Map

// Reader produces records from a stream.
type Reader interface {
	Next() (*Record, error)
	Close() error
}

// ---- shared line-oriented reader ----

type lineReader struct {
	opt    *Options
	src    *bufio.Reader
	header []string
	hasHdr bool
	eof    bool
}

func newLineReader(opt *Options, r io.Reader) *lineReader {
	return &lineReader{opt: opt, src: bufio.NewReaderSize(r, 1<<16)}
}

func (lr *lineReader) Next() (*Record, error) {
	for {
		if lr.eof {
			return nil, io.EOF
		}
		line, err := lr.src.ReadString('\n')
		if err != nil {
			if err == io.EOF {
				lr.eof = true
				if line == "" {
					return nil, io.EOF
				}
			} else {
				return nil, err
			}
		}
		line = strings.TrimSuffix(line, "\n")
		line = strings.TrimSuffix(line, "\r")
		if lr.opt.CommentsMode != CommentsNone {
			if strings.HasPrefix(line, lr.opt.CommentsPrefix) {
				if lr.opt.CommentsMode == CommentsPass {
					fmt.Println(lr.opt.CommentsPrefix + strings.TrimPrefix(line, lr.opt.CommentsPrefix))
				}
				continue
			}
		}
		switch lr.opt.IFormat {
		case FormatDKVP:
			return dkvpRecord(lr.opt, splitLine(line, lr.opt.IFS, lr.opt.IFSRegex, false)), nil
		case FormatNIDX:
			return nidxRecord(splitLine(line, lr.opt.IFS, lr.opt.IFSRegex, lr.opt.RepIfs)), nil
		case FormatPPrint:
			return nidxRecord(splitLine(line, lr.opt.IFS, lr.opt.IFSRegex, false)), nil
		case FormatCSV, FormatTSV, FormatCSVLite, FormatTSVLite:
			return lr.csvRecord(splitLine(line, lr.opt.IFS, "", false)), nil
		default:
			return NewMap(), nil
		}
	}
}

func (lr *lineReader) Close() error { return nil }

func splitLine(line, fs, fsRe string, repifs bool) []string {
	if fsRe != "" {
		return regexpSplit(line, fsRe)
	}
	if fs == "" {
		return []string{line}
	}
	if repifs {
		return strings.FieldsFunc(line, func(r rune) bool { return strings.ContainsRune(fs, r) })
	}
	return strings.Split(line, fs)
}

func dkvpRecord(opt *Options, fields []string) *Record {
	rec := NewMap()
	next := 1
	keyless := 0
	for _, f := range fields {
		var k, v string
		if i := strings.Index(f, opt.IPS); i >= 0 {
			k = f[:i]
			v = f[i+len(opt.IPS):]
		} else {
			v = f
			if opt.IncrKey {
				keyless++
				k = strconv.Itoa(keyless)
			} else {
				k = strconv.Itoa(next)
			}
		}
		next++
		val := inferValue(v, opt)
		if rec.Has(k) {
			rec.Unset(k)
		}
		rec.Set(k, val)
	}
	return rec
}

func nidxRecord(fields []string) *Record {
	rec := NewMap()
	for i, f := range fields {
		rec.Set(strconv.Itoa(i+1), inferValue(f, nil))
	}
	return rec
}

func inferValue(s string, opt *Options) Value {
	if opt != nil && opt.InferNone {
		return StringValue(s)
	}
	if opt != nil && opt.InferOctal {
		if len(s) > 1 && (s[0] == '0') && allDigits(s[1:]) {
			if i, err := strconv.ParseInt(s, 8, 64); err == nil {
				return Value{Kind: KindInt, I: i, Lit: s}
			}
		}
	}
	if opt != nil && opt.InferIntAsFloat {
		if v, ok := parseNumber(s); ok {
			if v.Kind == KindInt {
				return Value{Kind: KindFloat, F: float64(v.I), Lit: s}
			}
			return v
		}
	}
	if v, ok := parseNumber(s); ok {
		return v
	}
	return StringValue(s)
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func (lr *lineReader) csvRecord(fields []string) *Record {
	implicit := lr.opt.ImplicitCSVHeader
	if !implicit {
		if !lr.hasHdr {
			lr.hasHdr = true
			lr.header = fields
			return &Record{}
		}
	}
	rec := NewMap()
	if implicit {
		for i, f := range fields {
			rec.Set(strconv.Itoa(i+1), inferValue(f, lr.opt))
		}
		return rec
	}
	for i, h := range lr.header {
		if i < len(fields) {
			rec.Set(h, inferValue(fields[i], lr.opt))
		} else if lr.opt.AllowRagged {
			rec.Set(h, StringValue(""))
		} else {
			return nil
		}
	}
	for i := len(lr.header); i < len(fields); i++ {
		if lr.opt.AllowRagged {
			rec.Set(strconv.Itoa(i+1), inferValue(fields[i], lr.opt))
		}
	}
	return rec
}

// ---- JSON reader ----

type jsonReader struct {
	opt    *Options
	data   []byte
	pos    int
	jsonl  bool
	started bool
	inArr  bool
}

func newJSONReader(opt *Options, data []byte, jsonl bool) *jsonReader {
	return &jsonReader{opt: opt, data: data, jsonl: jsonl}
}

func (jr *jsonReader) Next() (*Record, error) {
	for {
		jr.skipWS()
		if jr.pos >= len(jr.data) {
			return nil, io.EOF
		}
		if !jr.started {
			jr.started = true
			if !jr.jsonl && jr.data[jr.pos] == '[' {
				jr.pos++
				jr.inArr = true
			}
		}
		jr.skipWS()
		if jr.pos >= len(jr.data) {
			return nil, io.EOF
		}
		if jr.inArr {
			c := jr.data[jr.pos]
			if c == ']' {
				jr.pos++
				continue
			}
			if c == ',' {
				jr.pos++
				continue
			}
		}
		v, err := parseJSONValue(jr)
		if err != nil {
			return nil, err
		}
		if v.Kind != KindMap {
			continue
		}
		return v.M, nil
	}
}

func (jr *jsonReader) Close() error { return nil }

func (jr *jsonReader) skipWS() {
	for jr.pos < len(jr.data) {
		c := jr.data[jr.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			jr.pos++
			continue
		}
		break
	}
}

func parseJSONValue(jr *jsonReader) (Value, error) {
	jr.skipWS()
	if jr.pos >= len(jr.data) {
		return NullValue(), io.EOF
	}
	c := jr.data[jr.pos]
	switch c {
	case '{':
		jr.pos++
		m := NewMap()
		for {
			jr.skipWS()
			if jr.pos >= len(jr.data) {
				return NullValue(), fmt.Errorf("mlr: JSON parse error")
			}
			if jr.data[jr.pos] == '}' {
				jr.pos++
				break
			}
			if jr.data[jr.pos] == ',' {
				jr.pos++
				continue
			}
			k, err := parseJSONString(jr)
			if err != nil {
				return NullValue(), err
			}
			jr.skipWS()
			if jr.pos >= len(jr.data) || jr.data[jr.pos] != ':' {
				return NullValue(), fmt.Errorf("mlr: JSON parse error: expected colon")
			}
			jr.pos++
			v, err := parseJSONValue(jr)
			if err != nil {
				return NullValue(), err
			}
			m.Set(k, v)
		}
		return MapValue(m), nil
	case '[':
		jr.pos++
		arr := []Value{}
		for {
			jr.skipWS()
			if jr.pos >= len(jr.data) {
				return NullValue(), fmt.Errorf("mlr: JSON parse error")
			}
			if jr.data[jr.pos] == ']' {
				jr.pos++
				break
			}
			if jr.data[jr.pos] == ',' {
				jr.pos++
				continue
			}
			v, err := parseJSONValue(jr)
			if err != nil {
				return NullValue(), err
			}
			arr = append(arr, v)
		}
		return Value{Kind: KindArray, A: arr}, nil
	case '"':
		s, err := parseJSONString(jr)
		return StringValue(s), err
	case 't':
		if strings.HasPrefix(string(jr.data[jr.pos:]), "true") {
			jr.pos += 4
			return BoolValue(true), nil
		}
	case 'f':
		if strings.HasPrefix(string(jr.data[jr.pos:]), "false") {
			jr.pos += 5
			return BoolValue(false), nil
		}
	case 'n':
		if strings.HasPrefix(string(jr.data[jr.pos:]), "null") {
			jr.pos += 4
			return NullValue(), nil
		}
	}
	start := jr.pos
	for jr.pos < len(jr.data) {
		ch := jr.data[jr.pos]
		if (ch >= '0' && ch <= '9') || ch == '-' || ch == '+' || ch == '.' || ch == 'e' || ch == 'E' {
			jr.pos++
			continue
		}
		break
	}
	s := string(jr.data[start:jr.pos])
	if s == "" {
		return NullValue(), fmt.Errorf("mlr: JSON parse error at offset %d", start)
	}
	if v, ok := parseNumber(s); ok {
		return v, nil
	}
	return StringValue(s), nil
}

func parseJSONString(jr *jsonReader) (string, error) {
	jr.skipWS()
	if jr.pos >= len(jr.data) || jr.data[jr.pos] != '"' {
		return "", fmt.Errorf("mlr: JSON parse error: expected string")
	}
	jr.pos++
	var b strings.Builder
	for jr.pos < len(jr.data) {
		c := jr.data[jr.pos]
		jr.pos++
		if c == '"' {
			return b.String(), nil
		}
		if c == '\\' {
			if jr.pos >= len(jr.data) {
				break
			}
			e := jr.data[jr.pos]
			jr.pos++
			switch e {
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			case '/':
				b.WriteByte('/')
			case 'b':
				b.WriteByte('\b')
			case 'f':
				b.WriteByte('\f')
			case 'n':
				b.WriteByte('\n')
			case 'r':
				b.WriteByte('\r')
			case 't':
				b.WriteByte('\t')
			case 'u':
				if jr.pos+4 <= len(jr.data) {
					h := string(jr.data[jr.pos : jr.pos+4])
					if n, err := strconv.ParseUint(h, 16, 32); err == nil {
						if n >= 0xD800 && n < 0xDC00 && jr.pos+6 <= len(jr.data) &&
							jr.data[jr.pos] == '\\' && jr.data[jr.pos+1] == 'u' {
							h2 := string(jr.data[jr.pos+2 : jr.pos+6])
							if n2, err2 := strconv.ParseUint(h2, 16, 32); err2 == nil &&
								n2 >= 0xDC00 && n2 < 0xE000 {
								b.WriteRune(runeFromSurrogate(int(n), int(n2)))
								jr.pos += 6
								continue
							}
						}
						b.WriteRune(runeFromCode(int(n)))
						jr.pos += 4
					}
				}
			}
			continue
		}
		b.WriteByte(c)
	}
	return b.String(), fmt.Errorf("mlr: JSON parse error: unterminated string")
}

func runeFromCode(n int) rune { return rune(n) }

func runeFromSurrogate(hi, lo int) rune {
	return rune(0x10000 + ((hi-0xD800)<<10)|(lo-0xDC00))
}

// ---- writers ----

type Writer interface {
	Write(rec *Record) error
	WriteEnd() error
}

type kv struct {
	k string
	v Value
}

func joinKey(a, b, sep string) string {
	if a == "" {
		return b
	}
	return a + sep + b
}

// flattenRecord turns a record's possibly nested values into a flat list.
func flattenRecord(rec *Record, sep string, noFlatten bool) []kv {
	out := []kv{}
	if noFlatten {
		for _, k := range rec.Keys() {
			v, _ := rec.Get(k)
			out = append(out, kv{k, v})
		}
		return out
	}
	for _, k := range rec.Keys() {
		v, _ := rec.Get(k)
		out = flattenValue(k, v, sep, out)
	}
	return out
}

func flattenValue(k string, v Value, sep string, out []kv) []kv {
	switch v.Kind {
	case KindMap:
		if v.M.Len() == 0 {
			out = append(out, kv{k, v})
			return out
		}
		for _, kk := range v.M.Keys() {
			val, _ := v.M.Get(kk)
			out = flattenValue(joinKey(k, kk, sep), val, sep, out)
		}
		return out
	case KindArray:
		if len(v.A) == 0 {
			out = append(out, kv{k, v})
			return out
		}
		for i, e := range v.A {
			out = flattenValue(joinKey(k, strconv.Itoa(i+1), sep), e, sep, out)
		}
		return out
	default:
		out = append(out, kv{k, v})
		return out
	}
}

// DKVP / NIDX writers

type dkvpWriter struct {
	opt  *Options
	out  io.Writer
	nidx bool
}

func (w *dkvpWriter) Write(rec *Record) error {
	pairs := flattenRecord(rec, w.opt.FlatSep, false)
	var b strings.Builder
	for i, p := range pairs {
		if i > 0 {
			b.WriteString(w.opt.OFS)
		}
		if !w.nidx {
			b.WriteString(p.k)
			b.WriteString(w.opt.OPS)
		}
		b.WriteString(p.v.String())
	}
	b.WriteByte('\n')
	_, err := io.WriteString(w.out, b.String())
	return err
}

func (w *dkvpWriter) WriteEnd() error { return nil }

// CSV / TSV writers

type csvWriter struct {
	opt    *Options
	out    io.Writer
	header []string
	seen   bool
	quote  bool
}

func csvQuote(s string, opt *Options) string {
	if opt.QuoteAll {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	if strings.Contains(s, opt.OFS) || strings.Contains(s, "\n") || strings.Contains(s, "\r") || strings.Contains(s, "\"") {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	return s
}

func (w *csvWriter) Write(rec *Record) error {
	keys := rec.Keys()
	if !w.seen {
		w.seen = true
		w.header = keys
		if !w.opt.HeaderlessOut {
			w.emitRow(keys, true)
		}
	} else if w.opt.AutoUnsparsify && !sameKeys(keys, w.header) {
		if !w.opt.HeaderlessOut {
			io.WriteString(w.out, "\n")
			w.header = keys
			w.emitRow(keys, true)
		}
	}
	var vals []kv
	if w.opt.AutoUnsparsify {
		for _, k := range w.header {
			v, ok := rec.Get(k)
			if ok {
				vals = append(vals, kv{k, v})
			}
		}
	} else {
		vals = flattenRecord(rec, w.opt.FlatSep, false)
	}
	var b strings.Builder
	for i, p := range vals {
		if i > 0 {
			b.WriteString(w.opt.OFS)
		}
		if w.quote {
			b.WriteString(csvQuote(p.v.String(), w.opt))
		} else {
			b.WriteString(p.v.String())
		}
	}
	b.WriteByte('\n')
	_, err := io.WriteString(w.out, b.String())
	return err
}

func (w *csvWriter) emitRow(keys []string, isHeader bool) {
	var b strings.Builder
	for i, k := range keys {
		if i > 0 {
			b.WriteString(w.opt.OFS)
		}
		if w.quote {
			b.WriteString(csvQuote(k, w.opt))
		} else {
			b.WriteString(k)
		}
	}
	b.WriteByte('\n')
	io.WriteString(w.out, b.String())
}

func sameKeys(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func (w *csvWriter) WriteEnd() error { return nil }

// JSON writers

type jsonWriter struct {
	opt     *Options
	out     io.Writer
	first   bool
	wrap    bool
	jvstack bool
}

func (w *jsonWriter) Write(rec *Record) error {
	if w.first && w.wrap {
		io.WriteString(w.out, "[\n")
	}
	w.first = false
	var sb strings.Builder
	renderRecordJSON(&sb, rec, w.jvstack, 0)
	io.WriteString(w.out, sb.String())
	if w.wrap {
		io.WriteString(w.out, ",\n")
	} else {
		io.WriteString(w.out, "\n")
	}
	return nil
}

func (w *jsonWriter) WriteEnd() error {
	if w.wrap {
		io.WriteString(w.out, "]\n")
	}
	return nil
}

func indentStr(n int) string { return strings.Repeat("  ", n) }

func renderRecordJSON(sb *strings.Builder, rec *Record, stack bool, depth int) {
	keys := rec.Keys()
	if !stack {
		sb.WriteString("{")
		for i, k := range keys {
			v, _ := rec.Get(k)
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(jsonQuote(k))
			sb.WriteString(": ")
			v.JSON(sb)
		}
		sb.WriteString("}")
		return
	}
	sb.WriteString("{")
	if len(keys) == 0 {
		sb.WriteString("}")
		return
	}
	sb.WriteString("\n")
	for i, k := range keys {
		v, _ := rec.Get(k)
		sb.WriteString(indentStr(depth + 1))
		sb.WriteString(jsonQuote(k))
		sb.WriteString(": ")
		if isLeafJSON(v) {
			v.JSON(sb)
			sb.WriteString("\n")
		} else {
			writeJSONNested(sb, v, depth+1)
		}
		if i < len(keys)-1 {
			sb.WriteString(",")
		}
	}
	sb.WriteString(indentStr(depth))
	sb.WriteString("}")
}

func isLeafJSON(v Value) bool {
	switch v.Kind {
	case KindMap:
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			if !isLeafJSON(val) {
				return false
			}
		}
		return true
	case KindArray:
		for _, e := range v.A {
			if !isLeafJSON(e) {
				return false
			}
		}
		return true
	}
	return true
}

func writeJSONNested(sb *strings.Builder, v Value, depth int) {
	switch v.Kind {
	case KindMap:
		if v.M.Len() == 0 {
			sb.WriteString("{}\n")
			return
		}
		sb.WriteString("{\n")
		keys := v.M.Keys()
		for i, k := range keys {
			val, _ := v.M.Get(k)
			sb.WriteString(indentStr(depth + 1))
			sb.WriteString(jsonQuote(k))
			sb.WriteString(": ")
			if isLeafJSON(val) {
				val.JSON(sb)
				sb.WriteString("\n")
			} else {
				writeJSONNested(sb, val, depth+1)
			}
			if i < len(keys)-1 {
				sb.WriteString(",")
			}
		}
		sb.WriteString(indentStr(depth))
		sb.WriteString("}\n")
	case KindArray:
		if len(v.A) == 0 {
			sb.WriteString("[]\n")
			return
		}
		sb.WriteString("[\n")
		for i, e := range v.A {
			sb.WriteString(indentStr(depth + 1))
			if isLeafJSON(e) {
				e.JSON(sb)
				sb.WriteString("\n")
			} else {
				writeJSONNested(sb, e, depth+1)
			}
			if i < len(v.A)-1 {
				sb.WriteString(",")
			}
		}
		sb.WriteString(indentStr(depth))
		sb.WriteString("]\n")
	}
}

// XTAB writer

type xtabWriter struct {
	opt  *Options
	out  io.Writer
	ps   string
	first bool
	widths map[string]int
}

func (w *xtabWriter) Write(rec *Record) error {
	if !w.first {
		io.WriteString(w.out, "\n")
	}
	w.first = false
	pairs := flattenRecord(rec, w.opt.FlatSep, false)
	for _, p := range pairs {
		io.WriteString(w.out, p.k)
		io.WriteString(w.out, w.opt.OPS)
		io.WriteString(w.out, p.v.String())
		io.WriteString(w.out, "\n")
	}
	return nil
}

func (w *xtabWriter) WriteEnd() error { return nil }

// factory

func NewReader(opt *Options, r io.Reader) Reader {
	switch opt.IFormat {
	case FormatJSON:
		data, err := io.ReadAll(r)
		if err != nil {
			return nil
		}
		return newJSONReader(opt, data, false)
	case FormatJSONL:
		return newJSONReader(opt, mustReadAll(r), true)
	}
	return newLineReader(opt, r)
}

func mustReadAll(r io.Reader) []byte {
	data, err := io.ReadAll(r)
	if err != nil {
		return []byte{}
	}
	return data
}

func NewWriter(opt *Options, out io.Writer) Writer {
	switch opt.OFormat {
	case FormatNIDX:
		return &dkvpWriter{opt: opt, out: out, nidx: true}
	case FormatCSV, FormatCSVLite:
		return &csvWriter{opt: opt, out: out, quote: opt.OFormat == FormatCSV}
	case FormatTSV, FormatTSVLite:
		return &csvWriter{opt: opt, out: out, quote: false}
	case FormatJSON:
		return &jsonWriter{opt: opt, out: out, wrap: opt.JListWrap, jvstack: opt.JvStack, first: true}
	case FormatJSONL:
		return &jsonWriter{opt: opt, out: out, wrap: false, jvstack: opt.JvStack, first: true}
	case FormatXTAB:
		return &xtabWriter{opt: opt, out: out}
	}
	return &dkvpWriter{opt: opt, out: out}
}
