package main

import (
	"regexp"
	"strings"
)

// compileRegex compiles a Miller-style regex: possibly wrapped in double
// quotes, possibly with a trailing "i" for case-insensitivity.
func compileRegex(s string) (*regexp.Regexp, error) {
	body := s
	caseInsensitive := false
	if strings.HasPrefix(body, "\"") && strings.HasSuffix(body, "\"") && len(body) >= 2 {
		body = body[1 : len(body)-1]
	}
	if strings.HasSuffix(body, "i") && !strings.HasSuffix(body, "\\i") {
		// only treat as flag if preceded by a quote-wrapped regex
		if strings.HasPrefix(s, "\"") {
			body = body[:len(body)-1]
			caseInsensitive = true
		}
	}
	if caseInsensitive {
		return regexp.Compile("(?i)" + body)
	}
	return regexp.Compile(body)
}

// regexCaseInsensitive reports whether the regex literal carries an "i" flag.
func regexCaseInsensitive(s string) bool {
	if strings.HasPrefix(s, "\"") && strings.HasSuffix(s, "\"i") && len(s) > 3 {
		return true
	}
	return false
}

// regexBody strips Miller's regex decorations.
func regexBody(s string) string {
	body := s
	if strings.HasPrefix(body, "\"") && strings.HasSuffix(body, "\"") && len(body) >= 2 {
		body = body[1 : len(body)-1]
	} else if strings.HasSuffix(body, "i") && strings.HasPrefix(body, "\"") {
		body = body[1 : len(body)-2]
	}
	return body
}

func regexInsensitive(s string) bool {
	if strings.HasPrefix(s, "\"") && strings.HasSuffix(s, "i") && len(s) > 3 {
		return true
	}
	return false
}

func regexCompileSpec(s string, forceInsensitive bool) (*regexp.Regexp, error) {
	body := regexBody(s)
	ci := forceInsensitive || regexInsensitive(s)
	if ci {
		return regexp.Compile("(?i)" + body)
	}
	return regexp.Compile(body)
}
GOEOF
