{"command": "cd /workspace; cat > main.go <<'GOEOF'
package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

const usageText = `Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}

If zero file names are provided, standard input is read, e.g.
  mlr --csv sort -f shape example.csv

Output of one verb may be chained as input to another using "then", e.g.
  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv

Please see 'mlr help topics' for more information.
Please also see https://miller.readthedocs.io
`

func main() {
	os.Exit(realMain(os.Args[1:]))
}

func realMain(args []string) int {
	opt := NewOptions()
	var verbs []VerbSpec
	var cur *VerbSpec
	seenFile := false
	i := 0
	for i < len(args) {
		a := args[i]
		i++
		if a == "then" {
			if cur != nil {
				verbs = append(verbs, *cur)
			}
			cur = nil
			seenFile = false
			continue
		}
		if strings.HasPrefix(a, "-") && !seenFile {
			if cur == nil {
				consumed, err := ApplyGlobalFlag(opt, a, args, &i)
				_ = consumed
				if err != nil {
					fmt.Fprintln(os.Stderr, err.Error())
					if strings.Contains(err.Error(), "not recognized") {
						fmt.Fprintln(os.Stderr, "Please run \"mlr --help\" for usage information.")
					}
					return 1
				}
				if opt.HelpRequested {
					fmt.Print(opt.HelpText)
					return 0
				}
				continue
			}
			// verb flag
			name := a
			if !VerbHasFlag(cur.name, name) {
				if cur.done {
					// after positional arg: file name
				} else {
					fmt.Fprintf(os.Stderr, "mlr: mlr %s: option \"%s\" not recognized\n", cur.name, name)
					return 1
				}
			}
			consumed := VerbApplyFlag(cur, name, args, &i)
			if cur.helpRequested {
				fmt.Print(verbHelp[cur.name])
				return 0
			}
			_ = consumed
			continue
		}
		if cur == nil {
			if a == "help" {
				return handleHelp(args[i:])
			}
			if _, ok := verbHelp[a]; !ok {
				fmt.Fprintf(os.Stderr, "mlr: verb \"%s\" not found. Please use \"mlr -l\" for a list.\n", a)
				return 1
			}
			cur = &VerbSpec{name: a}
			continue
		}
		// positional
		if cur.done {
			cur.files = append(cur.files, a)
			seenFile = true
			continue
		}
		if verbHasMainArg(cur.name) && !cur.hasMain {
			cur.main = a
			cur.hasMain = true
			continue
		}
		cur.files = append(cur.files, a)
		seenFile = true
		cur.done = true
	}
	if cur != nil {
		verbs = append(verbs, *cur)
	}
	if len(verbs) == 0 {
		fmt.Fprint(os.Stderr, "mlr: no verb supplied.\n"+usageText)
		return 0
	}
	if len(verbs) == 1 && verbs[0].name == "help" {
		return handleHelp(verbs[0].args)
	}
	if verbs[0].name == "help" {
		return handleHelp(verbs[0].args)
	}
	for _, v := range verbs {
		if v.name == "help" {
			return handleHelp(v.args)
		}
	}
	return runChain(opt, verbs)
}

// handleHelp implements 'mlr help ...'.
func handleHelp(rest []string) int {
	if len(rest) == 0 {
		fmt.Print(topicHelp["topics"] + "\n")
		return 0
	}
	t := rest[0]
	if strings.HasPrefix(t, "-") {
		if txt, ok := flagHelp[t]; ok {
			fmt.Println(t + ":")
			fmt.Println(stripColon(txt, t))
			return 0
		}
	}
	if txt, ok := flagHelp[t]; ok {
		fmt.Println(strings.TrimSuffix(t, ":"))
		fmt.Println(stripColon(txt, t))
		return 0
	}
	if txt, ok := topicHelp[t]; ok {
		fmt.Println(txt)
		return 0
	}
	if txt, ok := verbHelp[t]; ok {
		fmt.Println(txt)
		return 0
	}
	if txt, ok := functionHelp[t]; ok {
		fmt.Println(txt)
		return 0
	}
	if txt, ok := keywordHelp[t]; ok {
		fmt.Println(txt)
		return 0
	}
	fmt.Fprintf(os.Stderr, "No help found for \"%s\". Please try 'mlr help find %s' for approximate match.\n", t, t)
	fmt.Fprintf(os.Stderr, "See also 'mlr help topics'.\n")
	return 1
}

func stripColon(txt, name string) string {
	if strings.HasPrefix(txt, name+":") {
		return strings.TrimPrefix(txt, name+":")
	}
	return txt
}

// runChain reads input records and pushes them through the verb chain.
func runChain(opt *Options, verbs []VerbSpec) int {
	vs, err := BuildVerbs(opt, verbs)
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return 1
	}
	defer func() {
		for _, v := range vs {
			v.Close()
		}
	}()
	out := NewWriter(opt, os.Stdout)
	ctx := NewCtx(opt)
	var files []string
	files = append(files, opt.FromFiles...)
	files = append(files, verbs[len(verbs)-1].files...)
	if opt.FileList != "" {
		data, err := os.ReadFile(opt.FileList)
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr: open %s: no such file or directory\n", opt.FileList)
			return 1
		}
		for _, ln := range strings.Split(string(data), "\n") {
			if ln != "" {
				files = append(files, ln)
			}
		}
	}
	if len(files) == 0 && !opt.Igen {
		files = []string{"-"}
	}
	if opt.Igen {
		files = nil
	}
	if len(files) == 0 {
		files = []string{"-"}
	}
	recs := 0
	for _, fn := range files {
		var rd Reader
		if fn == "-" {
			rd = NewReader(opt, os.Stdin)
		} else {
			f, err := os.Open(fn)
			if err != nil {
				fmt.Fprintf(os.Stderr, "mlr: open %s: no such file or directory\n", fn)
				return 1
			}
			rd = NewReader(opt, f)
		}
		if opt.Igen {
			rd = NewSeqReader(opt)
		}
		ctx.Filenum++
		ctx.Filename = fn
		ctx.FNR = 0
		for {
			rec, err := rd.Next()
			if err != nil {
				if err != io.EOF {
					fmt.Fprintln(os.Stderr, err.Error())
					return 1
				}
				break
			}
			recs++
			if rec.Len() == 0 && rec != nil {
				// empty record: skip for csv header lines
				if opt.IFormat == FormatCSV || opt.IFormat == FormatCSVLite ||
					opt.IFormat == FormatTSV || opt.IFormat == FormatTSVLite {
					continue
				}
			}
			ctx.NR++
			ctx.FNR++
			err = pushRecord(vs, rec, ctx, out)
			if err != nil {
				fmt.Fprintln(os.Stderr, err.Error())
				return 1
			}
		}
		rd.Close()
	}
	for _, v := range vs {
		rs, err := v.End(ctx)
		if err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			return 1
		}
		for _, r := range rs {
			err = pushRecords(vs, r, ctx, out)
			if err != nil {
				fmt.Fprintln(os.Stderr, err.Error())
				return 1
			}
		}
	}
	out.WriteEnd()
	return 0
}

func pushRecord(vs []Verb, rec *Record, ctx *Ctx, out Writer) error {
	return pushRecords(vs, rec, ctx, out)
}

func pushRecords(vs []Verb, rec *Record, ctx *Ctx, out Writer) error {
	current := []*Record{rec}
	for _, v := range vs {
		var next []*Record
		for _, r := range current {
			rs, err := v.Process(r, ctx)
			if err != nil {
				return err
			}
			next = append(next, rs...)
		}
		current = next
		if len(current) == 0 {
			break
		}
	}
	for _, r := range current {
		if err := out.Write(r); err != nil {
			return err
		}
		if optFlush(ctx.opt) {
			if f, ok := ctx.outFlusher.(interface{ Flush() error }); ok {
				f.Flush()
			}
		}
	}
	return nil
}

func optFlush(o *Options) bool { return o.Flush }

type Ctx struct {
	opt      *Options
	NR       int64
	FNR      int64
	Filenum  int64
	Filename string
	outFlusher interface{}
}

func NewCtx(opt *Options) *Ctx { return &Ctx{opt: opt} }

var _ = io.EOF
var _ = strings.Split
GOEOF
gofmt -w main.go; echo ok"}

