Output of one verb may be chained as input to another using "then", e.g.
  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv

Please see 'mlr help topics' for more information.
Please also see https://miller.readthedocs.io
`

func main() {
	os.Exit(realMain(os.Args[1:]))
}

func realMain(args []string) int {
	opt := NewOptions()
	var verbs []VerbSpec
	var cur *VerbSpec
	seenFile := false
	i := 0
	for i < len(args) {
		a := args[i]
		i++
		if a == "then" {
			if cur != nil {
				verbs = append(verbs, *cur)
			}
			cur = nil
			seenFile = false
			continue
		}
		if strings.HasPrefix(a, "-") && !seenFile {
			if cur == nil {
				consumed, err := ApplyGlobalFlag(opt, a, args, &i)
				_ = consumed
				if err != nil {
					fmt.Fprintln(os.Stderr, err.Error())
					if strings.Contains(err.Error(), "not recognized") {
						fmt.Fprintln(os.Stderr, "Please run \"mlr --help\" for usage information.")
					}
					return 1
				}
				if opt.HelpRequested {
					fmt.Print(opt.HelpText)
					return 0
				}
				continue
			}
			// verb flag
			name := a
			if !VerbHasFlag(cur.name, name) {
				if cur.done {
					// after positional arg: file name
				} else {
					fmt.Fprintf(os.Stderr, "mlr: mlr %s: option \"%s\" not recognized\n", cur.name, name)
					return 1
				}
			}
			consumed := VerbApplyFlag(cur, name, args, &i)
			if cur.helpRequested {
				fmt.Print(verbHelp[cur.name])
				return 0
			}
			_ = consumed
			continue
		}
		if cur == nil {
			if a == "help" {
				return handleHelp(args[i:])
			}
			if _, ok := verbHelp[a]; !ok {
