// VerbSpec is the raw command-line form of one verb invocation.
type VerbSpec struct {
	name          string
	args          []string
	main          string
	hasMain       bool
	files         []string
	done          bool
	helpRequested bool
}

// Verb is one stage of a Miller processing chain.
type Verb interface {
	Process(rec *Record, ctx *Ctx) ([]*Record, error)
	End(ctx *Ctx) ([]*Record, error)
	Close() error
}

type nullVerb struct{}

func (n *nullVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) { return []*Record{rec}, nil }
func (n *nullVerb) End(ctx *Ctx) ([]*Record, error)                  { return nil, nil }
func (n *nullVerb) Close() error                                     { return nil }

// verbFlags gives, per verb, the map of verb-level flags to their arity.
var verbFlags map[string]map[string]int

func VerbHasFlag(verb, flag string) bool {
	fl, ok := verbFlags[verb]
	if !ok {
		return false
	}
	_, ok = fl[flag]
	return ok
}

func verbHasMainArg(verb string) bool {
	switch verb {
	case "put", "filter", "grep", "label", "group-by", "sec2gmt", "sec2gmtdate",
		"rename", "tee", "split":
		return true
	}
	return false
}

// parsed holds the result of verb flag parsing.
type parsed struct {
	B    map[string]bool
	S    map[string]string
	I    map[string]int
	rest []string
}

func parseVerbFlags(verb string, args []string) (*parsed, error) {
	res := &parsed{B: map[string]bool{}, S: map[string]string{}, I: map[string]int{}}
	fl := verbFlags[verb]
	i := 0
	for i < len(args) {
		a := args[i]
		i++
		if strings.HasPrefix(a, "-") {
			arity, ok := fl[a]
			if !ok {
				return nil, fmt.Errorf("mlr: mlr %s: option \"%s\" not recognized", verb, a)
			}
			if a == "-h" || a == "--help" {
				res.B["-h"] = true
				continue
			}
			if arity == 0 {
				res.B[a] = true
				continue
			}
			if i >= len(args) {
				return nil, fmt.Errorf("mlr: mlr %s: option \"%s\" requires an argument", verb, a)
			}
			res.S[a] = args[i]
			i++
			continue
		}
		res.rest = append(res.rest, a)
	}
	return res, nil
}

func (p *parsed) help() bool { return p.B["-h"] }

func fieldList(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}

func atoi(s string, def int) int {
	if n, err := strconv.Atoi(strings.TrimSpace(s)); err == nil {
		return n
	}
	return def
}

func atof(s string, def float64) float64 {
	if f, err := strconv.ParseFloat(strings.TrimSpace(s), 64); err == nil {
		return f
	}
	return def
}
