	add("-K", 0, func(o *Options, arg string) error { o.HelpText = topicHelp["usage-keywords"] + "\n"; o.HelpRequested = true; return nil })
	add("--help", 0, func(o *Options, arg string) error { o.HelpText = usageText; o.HelpRequested = true; return nil })
	add("-h", 0, func(o *Options, arg string) error { o.HelpText = usageText; o.HelpRequested = true; return nil })
	add("--version", 0, func(o *Options, arg string) error { o.HelpText = "mlr 6.16.0\n"; o.HelpRequested = true; return nil })
	add("--usage-separator-options", 0, func(o *Options, arg string) error {
		o.HelpText = topicHelp["separator-flags"] + "\n"
		o.HelpRequested = true
		return nil
	})
	globalFlags = gf
}

func colorCodesText() string {
	var b strings.Builder
	b.WriteString("Available color codes:\n")
	for i := 0; i < 256; i++ {
		b.WriteString(colorCode(i))
		b.WriteString(fmt.Sprintf("%3d", i))
		b.WriteString("\033[0m ")
		if (i+1)%32 == 0 && i != 255 {
			b.WriteString("\n")
		}
	}
	b.WriteString("\n")
	return b.String()
}

func colorCode(i int) string {
	if i < 8 {
		return fmt.Sprintf("\033[0;3%dm", i)
	}
	if i < 16 {
		return fmt.Sprintf("\033[1;3%dm", i-8)
	}
	return fmt.Sprintf("\033[1;38;5;%dm", i)
}

func colorNamesText() string {
	var b strings.Builder
	b.WriteString("Available color names:\n")
	for _, n := range []string{"bold", "underline"} {
		code := "\033[1m"
		if n == "underline" {
			code = "\033[4m"
		}
		b.WriteString(code + n + "\033[0m\n")
	}
	return b.String()
}

func listVerbsText() string {
	var b strings.Builder
	for _, v := range verbNameList {
		b.WriteString(v + "\n")
	}
	return b.String()
}

func listFunctionsText() string {
	var b strings.Builder
	for _, f := range functionNameList {
		b.WriteString(f + "\n")
	}
	return b.String()
}

func listKeywordsText() string {
	var b strings.Builder
	for _, f := range keywordNameList {
		b.WriteString(f + "\n")
	}
	return b.String()
}

// ApplyGlobalFlag handles one global command-line flag.
func ApplyGlobalFlag(o *Options, name string, args []string, i *int) (int, error) {
	if globalFlags == nil {
		buildGlobalFlags()
	}
	act, ok := globalFlags[name]
	if !ok {
		return 0, fmt.Errorf("mlr: option \"%s\" not recognized.", name)
	}
	var arg string
	if act.arity > 0 {
		if *i >= len(args) {
			return 0, fmt.Errorf("mlr: option \"%s\" requires an argument.", name)
		}
		arg = args[*i]
		*i++
	}
	if act.run != nil {
		if err := act.run(o, arg); err != nil {
			return 1, err
		}
	}
	return act.arity, nil
}
