// ---------- having-fields ----------

type havingFieldsVerb struct {
	atLeast  []string
	atMost   []string
	whichAre []string
	allMatch string
	anyMatch string
	noneMatch string
}

func newHavingFieldsVerb(p *parsed) *havingFieldsVerb {
	return &havingFieldsVerb{
		atLeast: fieldList(p.S["--at-least"]), atMost: fieldList(p.S["--at-most"]),
		whichAre: fieldList(p.S["--which-are"]), allMatch: p.S["--all-matching"],
		anyMatch: p.S["--any-matching"], noneMatch: p.S["--none-matching"],
	}
}

func (v *havingFieldsVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	ok := true
	if len(v.atLeast) > 0 {
		for _, f := range v.atLeast {
			if !rec.Has(f) {
				ok = false
			}
		}
	}
	if len(v.atMost) > 0 {
		for _, k := range rec.Keys() {
			found := false
			for _, f := range v.atMost {
				if k == f {
					found = true
					break
			}
			}
			if !found {
				ok = false
			}
		}
	}
	if len(v.whichAre) > 0 {
		if len(rec.Keys()) != len(v.whichAre) {
			ok = false
		} else {
			for _, k := range rec.Keys() {
				found := false
				for _, f := range v.whichAre {
					if k == f {
						found = true
						break
					}
				}
				if !found {
					ok = false
				}
			}
		}
	}
	if v.allMatch != "" {
		re, err := regexCompileSpec(v.allMatch, false)
		if err == nil {
			for _, k := range rec.Keys() {
				if !re.MatchString(k) {
					ok = false
				}
			}
		}
	}
	if v.anyMatch != "" {
		re, err := regexCompileSpec(v.anyMatch, false)
		if err == nil {
			found := false
			for _, k := range rec.Keys() {
				if re.MatchString(k) {
					found = true
					break
				}
			}
			if !found {
				ok = false
			}
		}
	}
	if v.noneMatch != "" {
		re, err := regexCompileSpec(v.noneMatch, false)
		if err == nil {
			for _, k := range rec.Keys() {
				if re.MatchString(k) {
					ok = false
					break
				}
			}
		}
	}
	if !ok {
		return nil, nil
	}
	return []*Record{rec}, nil
}

func (v *havingFieldsVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *havingFieldsVerb) Close() error                    { return nil }

