func (v *skipTrivialVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if rec.Len() == 0 {
		return nil, nil
	}
	allEmpty := true
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		if val.String() != "" {
			allEmpty = false
			break
		}
	}
	if allEmpty {
