// ---------- regularize / sort-within-records ----------

type regularizeVerb struct{}

func (v *regularizeVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	keys := append([]string{}, rec.Keys()...)
	sort.Strings(keys)
	out := NewMap()
	for _, k := range keys {
		val, _ := rec.Get(k)
		out.Set(k, val)
	}
	return []*Record{out}, nil
}

func (v *regularizeVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *regularizeVerb) Close() error                    { return nil }

type sortWithinRecordsVerb struct{ recursive bool }

func (v *sortWithinRecordsVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := sortValueKeys(rec, v.recursive)
	if out.Kind == KindMap {
		return []*Record{out.M}, nil
	}
	r := NewMap()
	r.Set("1", out)
	return []*Record{r}, nil
}

func sortValueKeys(v Value, recursive bool) Value {
	switch v.Kind {
	case KindMap:
		keys := append([]string{}, v.M.Keys()...)
		sort.Strings(keys)
		m := NewMap()
		for _, k := range keys {
			val, _ := v.M.Get(k)
			if recursive {
				val = sortValueKeys(val, true)
			}
			m.Set(k, val)
		}
		return MapValue(m)
	case KindArray:
		a := []Value{}
		for _, e := range v.A {
			if recursive {
				a = append(a, sortValueKeys(e, true))
			} else {
				a = append(a, e)
			}
		}
		return Value{Kind: KindArray, A: a}
	}
	return v
}

func (v *sortWithinRecordsVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *sortWithinRecordsVerb) Close() error                    { return nil }

// ---------- sec2gmt / sec2gmtdate ----------

type sec2gmtVerb struct {
	fields []string
	nd     int
	millis bool
	micros bool
	nanos  bool
}

func newSec2GMTVerb(p *parsed, main string) *sec2gmtVerb {
	fields := fieldList(main)
	nd := 0
	for i := 1; i <= 9; i++ {
		if p.B["-"+strconv.Itoa(i)] {
			nd = i
		}
	}
	return &sec2gmtVerb{fields: fields, nd: nd, millis: p.B["--millis"], micros: p.B["--micros"], nanos: p.B["--nanos"]}
}

func (v *sec2gmtVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	for _, f := range v.fields {
		val, ok := rec.Get(f)
		if !ok || !val.IsNumber() {
			continue
		}
		secs := toFloat(val)
		if v.millis {
			secs /= 1000.0
		} else if v.micros {
			secs /= 1e6
		} else if v.nanos {
			secs /= 1e9
		}
		out.Set(f, StringValue(formatGMT(secs, v.nd)))
	}
	return []*Record{out}, nil
}

func formatGMT(secs float64, nd int) string {
	whole := math.Floor(secs)
	frac := secs - whole
	t := time.Unix(int64(whole), 0).UTC()
	base := t.Format("2006-01-02T15:04:05")
	if nd <= 0 {
		return base + "Z"
	}
	return base + fmt.Sprintf(".%0*d", nd, int(math.Round(frac*math.Pow10(float64(nd))))) + "Z"
}

func (v *sec2gmtVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *sec2gmtVerb) Close() error                    { return nil }

type sec2gmtdateVerb struct{ fields []string }

func newSec2GMTDateVerb(p *parsed, main string) *sec2gmtdateVerb {
	fields := fieldList(main)
	if len(fields) == 0 {
		fields = fieldList(p.S["-f"])
	}
	return &sec2gmtdateVerb{fields: fields}
}

func (v *sec2gmtdateVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	for _, f := range v.fields {
		val, ok := rec.Get(f)
		if !ok || !val.IsNumber() {
			continue
		}
		secs := toFloat(val)
		t := time.Unix(int64(math.Floor(secs)), 0).UTC()
		out.Set(f, StringValue(t.Format("2006-01-02")))
	}
	return []*Record{out}, nil
}

func (v *sec2gmtdateVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *sec2gmtdateVerb) Close() error                    { return nil }

// ---------- seqgen ----------

type seqgenVerb struct {
	name  string
	start float64
	step  float64
	stop  float64
	ints  bool
}

func newSeqgenVerb(p *parsed, o *Options) *seqgenVerb {
	name := p.S["-f"]
	if name == "" {
		name = o.GenFieldName
	}
	start := o.GenStart
	step := o.GenStep
	stop := o.GenStop
	if p.S["--start"] != "" {
		start = atof(p.S["--start"], start)
	}
	if p.S["--step"] != "" {
		step = atof(p.S["--step"], step)
	}
	if p.S["--stop"] != "" {
		stop = atof(p.S["--stop"], stop)
	}
	ints := isIntText(p.S["--start"]) && isIntText(p.S["--step"]) && isIntText(p.S["--stop"])
	return &seqgenVerb{name: name, start: start, step: step, stop: stop, ints: ints}
}

func isIntText(s string) bool {
	if s == "" {
		return true
	}
	if _, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64); err == nil {
		return true
	}
	return false
}

func (v *seqgenVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *seqgenVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	if v.step == 0 && v.start != v.stop {
		return out, nil
	}
	if v.ints {
		s := int64(v.start)
		st := int64(v.step)
		e := int64(v.stop)
		if st > 0 {
			for x := s; x <= e; x += st {
				r := NewMap()
				r.Set(v.name, IntValue(x))
				out = append(out, r)
			}
		} else if st < 0 {
			for x := s; x >= e; x += st {
				r := NewMap()
				r.Set(v.name, IntValue(x))
				out = append(out, r)
			}
		} else {
			r := NewMap()
			r.Set(v.name, IntValue(s))
			out = append(out, r)
		}
		return out, nil
	}
	if v.step > 0 {
		for x := v.start; x <= v.stop+1e-9; x += v.step {
			r := NewMap()
			r.Set(v.name, FloatValue(x))
			out = append(out, r)
		}
	} else {
		for x := v.start; x >= v.stop-1e-9; x += v.step {
			r := NewMap()
			r.Set(v.name, FloatValue(x))
			out = append(out, r)
		}
	}
	return out, nil
}

func (v *seqgenVerb) Close() error { return nil }

