package main

import (
	"fmt"
	"math"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

// ---------- helpers ----------

func matchFieldNames(names []string, useRegex bool, rec *Record) []string {
	out := []string{}
	for _, k := range rec.Keys() {
		for _, n := range names {
			if useRegex {
				re, err := regexCompileSpec(n, false)
				if err == nil && re.MatchString(k) {
					out = append(out, k)
					break
				}
			} else if k == n {
				out = append(out, k)
				break
			}
		}
	}
	return out
}

func fieldNameMatches(k, n string, useRegex bool) bool {
	if useRegex {
		re, err := regexCompileSpec(n, false)
		if err != nil {
			return false
		}
		return re.MatchString(k)
	}
	return k == n
}

func numLess(a, b Value) (int, bool) {
	if !a.IsNumber() || !b.IsNumber() {
		return 0, false
	}
	x, y := numAsFloat(a), numAsFloat(b)
	if x < y {
		return -1, true
	}
	if x > y {
		return 1, true
	}
	return 0, true
}

func numAsFloat(v Value) float64 {
	if v.Kind == KindInt {
		return float64(v.I)
	}
	return v.F
}

func toFloat(v Value) float64 {
	switch v.Kind {
	case KindInt:
		return float64(v.I)
	case KindFloat:
		return v.F
	case KindBool:
		if v.B {
			return 1
		}
		return 0
	}
	return math.NaN()
}

func toInt(v Value) int64 {
	switch v.Kind {
	case KindInt:
		return v.I
	case KindFloat:
		return int64(v.F)
	}
	return 0
}

// ---------- cat ----------

type catVerb struct {
	n           bool
	nname       string
	groups      []string
	filename    bool
	filenum     bool
	counts      map[string]int64
}

func newCatVerb(p *parsed) *catVerb {
	v := &catVerb{counts: map[string]int64{}}
	if p.S["-N"] != "" {
		v.nname = p.S["-N"]
	} else if p.B["-n"] {
		v.nname = "n"
	}
	v.groups = fieldList(p.S["-g"])
	v.filename = p.B["--filename"]
	v.filenum = p.B["--filenum"]
	return v
}

func (v *catVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	nrec := NewMap()
	if v.nname != "" {
		key := ""
		for _, g := range v.groups {
			val, _ := rec.Get(g)
			key += val.String() + "\x00"
		}
		v.counts[key]++
		nrec.Set(v.nname, IntValue(v.counts[key]))
	}
	if v.filenum {
		nrec.Set("filenum", IntValue(ctx.Filenum))
	}
	if v.filename {
		nrec.Set("filename", StringValue(ctx.Filename))
	}
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		nrec.Set(k, val)
	}
	return []*Record{nrec}, nil
}

func (v *catVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *catVerb) Close() error                    { return nil }

// ---------- cut ----------

type cutVerb struct {
	fields   []string
	order    bool
	exclude  bool
	useRegex bool
}

func newCutVerb(p *parsed) *cutVerb {
	return &cutVerb{fields: fieldList(p.S["-f"]), order: p.B["-o"], exclude: p.B["-x"], useRegex: p.B["-r"]}
}

func (v *cutVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if len(v.fields) == 0 {
		return nil, fmt.Errorf("mlr: mlr cut: -f field names required")
	}
	out := NewMap()
	if v.exclude {
		for _, k := range rec.Keys() {
			keep := true
			for _, f := range v.fields {
				if fieldNameMatches(k, f, v.useRegex) {
					keep = false
					break
				}
			}
			if keep {
				val, _ := rec.Get(k)
				out.Set(k, val)
			}
		}
		return []*Record{out}, nil
	}
	if v.order {
		for _, f := range v.fields {
			for _, k := range rec.Keys() {
				if fieldNameMatches(k, f, v.useRegex) {
					val, _ := rec.Get(k)
					out.Set(k, val)
					break
				}
			}
		}
		return []*Record{out}, nil
	}
	for _, k := range rec.Keys() {
		for _, f := range v.fields {
			if fieldNameMatches(k, f, v.useRegex) {
				val, _ := rec.Get(k)
				out.Set(k, val)
				break
			}
		}
	}
	return []*Record{out}, nil
}

func (v *cutVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *cutVerb) Close() error                    { return nil }

// ---------- label ----------

type labelVerb struct{ names []string }

func newLabelVerb(p *parsed, main string) *labelVerb {
	names := fieldList(main)
	if len(names) == 0 {
		names = fieldList(p.S["-f"])
	}
	return &labelVerb{names: names}
}

func (v *labelVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	keys := rec.Keys()
	for i, k := range keys {
		val, _ := rec.Get(k)
		name := k
		if i < len(v.names) {
			name = v.names[i]
		}
		out.Set(name, val)
	}
	return []*Record{out}, nil
}

func (v *labelVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *labelVerb) Close() error                    { return nil }

// ---------- tac ----------

type tacVerb struct{ buf []*Record }

func (v *tacVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	v.buf = append(v.buf, rec)
	return nil, nil
}

func (v *tacVerb) End(ctx *Ctx) ([]*Record, error) {
	out := make([]*Record, 0, len(v.buf))
	for i := len(v.buf) - 1; i >= 0; i-- {
		out = append(out, v.buf[i])
	}
	return out, nil
}

func (v *tacVerb) Close() error { return nil }

// ---------- head / tail ----------

type headVerb struct {
	n      int
	groups []string
	counts map[string]int64
	buf    []*Record
	all    []*Record
	seen   map[string]bool
}

func newHeadVerb(p *parsed) *headVerb {
	v := &headVerb{n: atoi(p.S["-n"], 10), groups: fieldList(p.S["-g"]),
		counts: map[string]int64{}, seen: map[string]bool{}}
	return v
}

func (v *headVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if len(v.groups) == 0 {
		if v.n > 0 && len(v.buf) < v.n {
			v.buf = append(v.buf, rec)
			return []*Record{rec}, nil
		}
		return nil, nil
	}
	key := groupKey(rec, v.groups)
	v.counts[key]++
	if v.counts[key] <= int64(v.n) {
		return []*Record{rec}, nil
	}
	return nil, nil
}

func (v *headVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *headVerb) Close() error                    { return nil }

func groupKey(rec *Record, groups []string) string {
	var b strings.Builder
	for _, g := range groups {
		val, _ := rec.Get(g)
		b.WriteString(val.String())
		b.WriteByte(0)
	}
	return b.String()
}

type tailVerb struct {
	n      int
	groups []string
	bufs   map[string][]*Record
	all    []*Record
}

func newTailVerb(p *parsed) *tailVerb {
	return &tailVerb{n: atoi(p.S["-n"], 10), groups: fieldList(p.S["-g"]), bufs: map[string][]*Record{}}
}

func (v *tailVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if len(v.groups) == 0 {
		v.bufs[""] = append(v.bufs[""], rec)
		return nil, nil
	}
	key := groupKey(rec, v.groups)
	v.bufs[key] = append(v.bufs[key], rec)
	return nil, nil
}

func (v *tailVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	for _, key := range v.bufKeys() {
		b := v.bufs[key]
		start := 0
		if len(b) > v.n {
			start = len(b) - v.n
		}
		out = append(out, b[start:]...)
	}
	return out, nil
}

func (v *tailVerb) bufKeys() []string {
	ks := make([]string, 0, len(v.bufs))
	for k := range v.bufs {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

func (v *tailVerb) Close() error { return nil }

// ---------- count ----------

type countVerb struct {
	groups []string
	o      string
	n      bool
	counts map[string]int64
}

func newCountVerb(p *parsed) *countVerb {
	return &countVerb{groups: fieldList(p.S["-g"]), o: p.S["-o"], n: p.B["-n"], counts: map[string]int64{}}
}

func (v *countVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	key := groupKey(rec, v.groups)
	v.counts[key]++
	return nil, nil
}

func (v *countVerb) End(ctx *Ctx) ([]*Record, error) {
	total := int64(0)
	for _, c := range v.counts {
		total += c
	}
	out := []*Record{}
	if len(v.groups) == 0 {
		r := NewMap()
		name := v.o
		if name == "" {
			name = "count"
		}
		r.Set(name, IntValue(total))
		out = append(out, r)
		return out, nil
	}
	if v.n {
		r := NewMap()
		name := v.o
		if name == "" {
			name = "count"
		}
		r.Set(name, IntValue(int64(len(v.counts))))
		out = append(out, r)
		return out, nil
	}
	for _, key := range groupKeyOrder(v.counts) {
		r := NewMap()
		parts := splitGroupKey(key, v.groups)
		for i, g := range v.groups {
			r.Set(g, StringValue(parts[i]))
		}
		name := v.o
		if name == "" {
			name = "count"
		}
		r.Set(name, IntValue(v.counts[key]))
		out = append(out, r)
	}
	return out, nil
}

func groupKeyOrder(m map[string]int64) []string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

func splitGroupKey(key string, groups []string) []string {
	parts := strings.Split(key, "\x00")
	for len(parts) < len(groups) {
		parts = append(parts, "")
	}
	return parts[:len(groups)]
}

func (v *countVerb) Close() error { return nil }

// ---------- count-distinct / uniq ----------

type distinctVerb struct {
	fields   []string
	exclude  []string
	unlashed bool
	n        bool
	o        string
	counts   bool
	all      bool
	groups   []string
}

func newDistinctVerb(p *parsed, groups []string) *distinctVerb {
	return &distinctVerb{
		fields: fieldList(p.S["-f"]), exclude: fieldList(p.S["-x"]),
		unlashed: p.B["-u"], n: p.B["-n"], o: p.S["-o"], counts: p.B["-c"], all: p.B["-a"], groups: groups,
	}
}

func (v *distinctVerb) keysFor(rec *Record) ([]string, map[string]Value) {
	if len(v.exclude) > 0 {
		ks := []string{}
		vals := map[string]Value{}
		for _, k := range rec.Keys() {
			skip := false
			for _, x := range v.exclude {
				if k == x {
					skip = true
					break
				}
			}
			if skip {
				continue
			}
			ks = append(ks, k)
			val, _ := rec.Get(k)
			vals[k] = val
		}
		return ks, vals
	}
	if len(v.fields) > 0 {
		ks := []string{}
		vals := map[string]Value{}
		for _, f := range v.fields {
			val, ok := rec.Get(f)
			if !ok {
				val = NullValue()
			}
			ks = append(ks, f)
			vals[f] = val
		}
		return ks, vals
	}
	ks := []string{}
	vals := map[string]Value{}
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		ks = append(ks, k)
		vals[k] = val
	}
	return ks, vals
}

// count-distinct

type countDistinctVerb struct {
	distinctVerb
	counts map[string]int64
	seen   []*Record
	vals   map[string][]Value
}

func newCountDistinctVerb(p *parsed) *countDistinctVerb {
	return &countDistinctVerb{distinctVerb: *newDistinctVerb(p, nil), counts: map[string]int64{},
		vals: map[string][]Value{}}
}

func (v *countDistinctVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if v.all {
		keys, _ := v.keysFor(rec)
		var b strings.Builder
		for _, k := range keys {
			val, _ := rec.Get(k)
			b.WriteString(val.String())
			b.WriteByte(0)
		}
		key := b.String()
		if _, ok := v.counts[key]; !ok {
			v.seen = append(v.seen, rec.Clone())
		}
		v.counts[key]++
		return nil, nil
	}
	if v.unlashed {
		for _, f := range v.fields {
			val, _ := rec.Get(f)
			k := val.String()
			v.counts[k]++
		}
		return nil, nil
	}
	keys, vals := v.keysFor(rec)
	var b strings.Builder
	list := []Value{}
	for _, k := range keys {
		val := vals[k]
		b.WriteString(val.String())
		b.WriteByte(0)
		list = append(list, val)
	}
	key := b.String()
	if _, ok := v.counts[key]; !ok {
		v.vals[key] = list
		v.counts[key] = 0
	}
	v.counts[key]++
	return nil, nil
}

func (v *countDistinctVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	if v.all {
		total := int64(0)
		for _, c := range v.counts {
			total += c
		}
		if v.n {
			r := NewMap()
			name := v.o
			if name == "" {
				name = "count"
			}
			r.Set(name, IntValue(int64(len(v.counts))))
			return []*Record{r}, nil
		}
		for _, rec := range v.seen {
			r := rec.Clone()
			name := v.o
			if name == "" {
				name = "count"
			}
			var c int64
			var b strings.Builder
			for _, k := range rec.Keys() {
				val, _ := rec.Get(k)
				b.WriteString(val.String())
				b.WriteByte(0)
			}
			c = v.counts[b.String()]
			r.Set(name, IntValue(c))
			out = append(out, r)
		}
		return out, nil
	}
	if v.n {
		r := NewMap()
		name := v.o
		if name == "" {
			name = "count"
		}
		r.Set(name, IntValue(int64(len(v.counts))))
		return []*Record{r}, nil
	}
	for _, key := range sortedIntKeys(v.counts) {
		r := NewMap()
		list := v.vals[key]
		if v.unlashed {
			r.Set("value", list[0])
		} else if len(v.fields) > 0 {
			for i, f := range v.fields {
				if i < len(list) {
					r.Set(f, list[i])
				}
			}
		} else if len(v.exclude) > 0 {
			for i, e := range list {
				_ = e
				_ = i
			}
		}
		if v.counts {
			name := v.o
			if name == "" {
				name = "count"
			}
			r.Set(name, IntValue(v.counts[key]))
		}
		out = append(out, r)
	}
	return out, nil
}

func sortedIntKeys(m map[string]int64) []string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

func (v *countDistinctVerb) Close() error { return nil }

// uniq

type uniqVerb struct {
	distinctVerb
	counts  map[string]int64
	vals    map[string][]Value
	keys    []string
	groups  []string
	recSeen map[string]*Record
	recKeys []string
}

func newUniqVerb(p *parsed) *uniqVerb {
	return &uniqVerb{distinctVerb: *newDistinctVerb(p, fieldList(p.S["-g"])),
		counts: map[string]int64{}, vals: map[string][]Value{}, recSeen: map[string]*Record{}}
}

func (v *uniqVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if v.all {
		var b strings.Builder
		for _, k := range rec.Keys() {
			val, _ := rec.Get(k)
			b.WriteString(val.String())
			b.WriteByte(0)
		}
		key := b.String()
		if _, ok := v.counts[key]; !ok {
			v.recSeen[key] = rec.Clone()
			v.recKeys = append(v.recKeys, key)
		}
		v.counts[key]++
		return nil, nil
	}
	fields := v.groups
	if len(fields) == 0 {
		fields = v.fields
	}
	var list []Value
	var b strings.Builder
	if len(v.exclude) > 0 {
		for _, k := range rec.Keys() {
			skip := false
			for _, x := range v.exclude {
				if k == x {
					skip = true
					break
				}
			}
			if skip {
				continue
			}
			val, _ := rec.Get(k)
			b.WriteString(val.String())
			b.WriteByte(0)
			list = append(list, val)
		}
		key := b.String()
		if _, ok := v.counts[key]; !ok {
			v.vals[key] = list
			v.keys = append(v.keys, key)
		}
		v.counts[key]++
		return nil, nil
	}
	for _, f := range fields {
		val, ok := rec.Get(f)
		if !ok {
			val = NullValue()
		}
		b.WriteString(val.String())
		b.WriteByte(0)
		list = append(list, val)
	}
	key := b.String()
	if _, ok := v.counts[key]; !ok {
		v.vals[key] = list
		v.keys = append(v.keys, key)
	}
	v.counts[key]++
	return nil, nil
}

func (v *uniqVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	if v.all {
		if v.n {
			r := NewMap()
			name := v.o
			if name == "" {
				name = "count"
			}
			r.Set(name, IntValue(int64(len(v.recKeys))))
			return []*Record{r}, nil
		}
		for _, key := range v.recKeys {
			r := v.recSeen[key].Clone()
			if v.counts {
				name := v.o
				if name == "" {
					name = "count"
				}
				r.Set(name, IntValue(v.counts[key]))
			}
			out = append(out, r)
		}
		return out, nil
	}
	if v.n {
		r := NewMap()
		name := v.o
		if name == "" {
			name = "count"
		}
		r.Set(name, IntValue(int64(len(v.keys))))
		return []*Record{r}, nil
	}
	for _, key := range v.keys {
		r := NewMap()
		list := v.vals[key]
		fields := v.groups
		if len(fields) == 0 {
			fields = v.fields
		}
		if len(v.exclude) > 0 {
			for i, e := range list {
				_ = e
				_ = i
			}
		} else {
			for i, f := range fields {
				if i < len(list) {
					r.Set(f, list[i])
				}
			}
		}
		if v.counts {
			name := v.o
			if name == "" {
				name = "count"
			}
			r.Set(name, IntValue(v.counts[key]))
		}
		out = append(out, r)
	}
	return out, nil
}

func (v *uniqVerb) Close() error { return nil }

// count-similar

type countSimilarVerb struct {
	groups []string
	o      string
	counts map[string]int64
	buf    []*Record
}

func newCountSimilarVerb(p *parsed) *countSimilarVerb {
	return &countSimilarVerb{groups: fieldList(p.S["-g"]), o: p.S["-o"], counts: map[string]int64{}}
}

func (v *countSimilarVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	key := groupKey(rec, v.groups)
	v.counts[key]++
	v.buf = append(v.buf, rec)
	return nil, nil
}

func (v *countSimilarVerb) End(ctx *Ctx) ([]*Record, error) {
