		name = "count"
	}
	for _, rec := range v.buf {
		key := groupKey(rec, v.groups)
		r := rec.Clone()
		r.Set(name, IntValue(v.counts[key]))
		out = append(out, r)
	}
	return out, nil
}

func (v *countSimilarVerb) Close() error { return nil }

// ---------- group-by / group-like ----------

type groupByVerb struct {
	groups []string
	bufs   map[string][]*Record
