{"command": "cd /workspace; cat > verbs2.go <<'GOEOF'
package main

import (
	"fmt"
	"math"
	"sort"
	"strings"
)

// ---------- sort ----------

type sortKey struct {
	field string
	kind  string // f r c cr n nr t tr
}

type sortVerb struct {
	keys   []sortKey
	moved  bool
	buf    []*Record
}

func newSortVerb(p *parsed) (*sortVerb, error) {
	v := &sortVerb{}
	return v, nil
}

// parseSortArgs walks the raw verb args in order, collecting sort keys.
func newSortVerbFromArgs(spec *VerbSpec) (*sortVerb, error) {
	v := &sortVerb{}
	fl := verbFlags["sort"]
	args := spec.args
	i := 0
	for i < len(args) {
		a := args[i]
		i++
		if strings.HasPrefix(a, "-") {
			if a == "-h" || a == "--help" {
				return nil, fmt.Errorf("__help__")
			}
			if _, ok := fl[a]; !ok {
				return nil, fmt.Errorf("mlr: mlr sort: option \"%s\" not recognized", a)
			}
			if a == "-b" {
				v.moved = true
				continue
			}
			if i >= len(args) {
				return nil, fmt.Errorf("mlr: mlr sort: option \"%s\" requires an argument", a)
			}
			names := strings.Split(args[i], ",")
			i++
			var kind string
			switch a {
			case "-f":
				kind = "f"
			case "-r":
				kind = "r"
			case "-c":
				kind = "c"
			case "-cr":
				kind = "cr"
			case "-n", "-nf":
				kind = "n"
			case "-nr":
				kind = "nr"
			case "-t":
				kind = "t"
			case "-tr", "-rt":
				kind = "tr"
			default:
				kind = "f"
			}
			for _, n := range names {
				v.keys = append(v.keys, sortKey{field: n, kind: kind})
			}
			continue
		}
	}
	return v, nil
}

func naturalLess(a, b string) bool {
	return compareNatural(a, b) < 0
}

func compareNatural(a, b string) int {
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		ca, cb := a[i], b[j]
		if isDigit(ca) && isDigit(cb) {
			x, y := i, j
			for x < len(a) && isDigit(a[x]) {
				x++
			}
			for y < len(b) && isDigit(b[y]) {
				y++
			}
			na, _ := parseFloatSafe(a[i:x])
			nb, _ := parseFloatSafe(b[j:y])
			if na < nb {
				return -1
			}
			if na > nb {
				return 1
			}
			if x-i != y-j {
				if x-i < y-j {
					return -1
				}
				return 1
			}
			i, j = x, y
			continue
		}
		if ca != cb {
			if ca < cb {
				return -1
			}
			return 1
		}
		i++
		j++
	}
	if i < len(a) {
		return 1
	}
	if j < len(b) {
		return -1
	}
	return 0
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func parseFloatSafe(s string) (float64, bool) {
	var f float64
	_, err := fmt.Sscanf(s, "%f", &f)
	return f, err == nil
}

func sortCompare(a, b *Record, keys []sortKey) (int, bool) {
	for _, k := range keys {
		va, oka := a.Get(k.field)
		vb, okb := b.Get(k.field)
		if !oka && !okb {
			continue
		}
		if !oka {
			// a missing: goes to end for ascending, first for descending
			return 1, true
		}
		if !okb {
			return -1, true
		}
		switch k.kind {
		case "f":
			if c := strings.Compare(va.String(), vb.String()); c != 0 {
				return c, false
			}
		case "r":
			if c := strings.Compare(va.String(), vb.String()); c != 0 {
				return -c, false
			}
		case "c":
			if c := strings.Compare(strings.ToLower(va.String()), strings.ToLower(vb.String())); c != 0 {
				return c, false
			}
		case "cr":
			if c := strings.Compare(strings.ToLower(va.String()), strings.ToLower(vb.String())); c != 0 {
				return -c, false
			}
		case "n":
			na, aok := numericVal(va)
			nb, bok := numericVal(vb)
			if !aok && !bok {
				continue
			}
			if !aok {
				return 1, true
			}
			if !bok {
				return -1, true
			}
			if na < nb {
				return -1, false
			}
			if na > nb {
				return 1, false
			}
		case "nr":
			na, aok := numericVal(va)
			nb, bok := numericVal(vb)
			if !aok && !bok {
				continue
			}
			if !aok {
				return -1, true
			}
			if !bok {
				return 1, true
			}
			if na < nb {
				return 1, false
			}
			if na > nb {
				return -1, false
			}
		case "t":
			if c := compareNatural(va.String(), vb.String()); c != 0 {
				return c, false
			}
		case "tr":
			if c := compareNatural(va.String(), vb.String()); c != 0 {
				return -c, false
			}
		}
	}
	return 0, false
}

func numericVal(v Value) (float64, bool) {
	if v.IsNumber() {
		return toFloat(v), true
	}
	return 0, false
}

func (v *sortVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	v.buf = append(v.buf, rec)
	return nil, nil
}

func (v *sortVerb) End(ctx *Ctx) ([]*Record, error) {
	out := append([]*Record{}, v.buf...)
	sort.SliceStable(out, func(i, j int) bool {
		c, _ := sortCompare(out[i], out[j], v.keys)
		return c < 0
	})
	if v.moved {
		res := []*Record{}
		for _, rec := range out {
			nr := NewMap()
			for _, k := range v.keys {
				val, ok := rec.Get(k.field)
				if ok {
					nr.Set(k.field, val)
				}
			}
			for _, k := range rec.Keys() {
				if _, ok := nr.Get(k); ok {
					continue
				}
				val, _ := rec.Get(k)
				nr.Set(k, val)
			}
			res = append(res, nr)
		}
		return res, nil
	}
	return out, nil
}

func (v *sortVerb) Close() error { return nil }

// ---------- stats1 ----------

type statsSpec struct {
	name    string
	nd      float64
	numeric bool
}

type stats1Verb struct {
	valueFields []string
	valRegex    string
	valRegexNeg string
	groupFields []string
	groupRegex  string
	groupRegexNeg string
	specs       []statsSpec
	interpolated bool
	iterative   bool
	// state
	acc      map[string]*stats1Acc
	groupKeys []string
	fieldNames []string
	fieldSeen map[string]bool
	groupSeen map[string]bool
}

type stats1Acc struct {
	counts    map[string]int64
	n         int
	nullCount int
	distinct  map[string]int64
	sum       float64
	sum2      float64
	sum3      float64
	sum4      float64
	values    []float64
	strvals   []string
}

func newStats1Acc() *stats1Acc {
	return &stats1Acc{counts: map[string]int64{}, distinct: map[string]int64{}}
}

func parseStats1Specs(list string) ([]statsSpec, error) {
	specs := []statsSpec{}
	if list == "" {
		return nil, fmt.Errorf("mlr: mlr stats1: -a accumulator names required")
	}
	for _, name := range strings.Split(list, ",") {
		switch name {
		case "count", "null_count", "distinct_count", "mode", "antimode", "sum", "mean",
			"mad", "var", "stddev", "meaneb", "skewness", "kurtosis", "min", "max",
			"minlen", "maxlen", "p0", "p100":
			specs = append(specs, statsSpec{name: name, numeric: name != "count" &&
				name != "null_count" && name != "distinct_count" && name != "mode" &&
				name != "antimode" && name != "minlen" && name != "maxlen"})
		case "median":
			specs = append(specs, statsSpec{name: "p50", numeric: true})
		default:
			if strings.HasPrefix(name, "p") {
				rest := strings.TrimPrefix(name, "p")
				var nd float64
				if _, err := fmt.Sscanf(rest, "%f", &nd); err == nil {
					specs = append(specs, statsSpec{name: name, nd: nd, numeric: true})
					continue
				}
			}
			return nil, fmt.Errorf("mlr: mlr stats1: unrecognizable accumulator name \"%s\"", name)
		}
	}
	return specs, nil
}

func newStats1Verb(p *parsed) (*stats1Verb, error) {
	specs, err := parseStats1Specs(p.S["-a"])
	if err != nil {
		return nil, err
	}
	return &stats1Verb{
		valueFields: fieldList(p.S["-f"]), valRegex: p.S["--fr"], valRegexNeg: p.S["--fx"],
		groupFields: fieldList(p.S["-g"]), groupRegex: p.S["--gr"], groupRegexNeg: p.S["--gx"],
		specs: specs, interpolated: p.B["-i"], iterative: p.B["-s"],
		acc: map[string]*stats1Acc{}, fieldSeen: map[string]bool{}, groupSeen: map[string]bool{},
	}, nil
}

func (v *stats1Verb) fieldsFor(rec *Record) []string {
	out := []string{}
	for _, k := range rec.Keys() {
		if len(v.valueFields) > 0 {
			found := false
			for _, f := range v.valueFields {
				if f == k {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		} else if v.valRegex != "" {
			re, err := regexCompileSpec(v.valRegex, false)
			if err != nil || !re.MatchString(k) {
				continue
			}
			if v.valRegexNeg != "" {
				re2, err2 := regexCompileSpec(v.valRegexNeg, false)
				if err2 == nil && re2.MatchString(k) {
					continue
				}
			}
		} else {
			continue
		}
		out = append(out, k)
	}
	return out
}

func (v *stats1Verb) groupsFor(rec *Record) []string {
	out := []string{}
	for _, k := range rec.Keys() {
		if len(v.groupFields) > 0 {
			found := false
			for _, f := range v.groupFields {
				if f == k {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		} else if v.groupRegex != "" {
			re, err := regexCompileSpec(v.groupRegex, false)
			if err != nil || !re.MatchString(k) {
				continue
			}
		} else {
			continue
		}
		out = append(out, k)
	}
	return out
}

func (v *stats1Verb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	groups := v.groupsFor(rec)
	gkey := groupKey(rec, groups)
	gvals := map[string]Value{}
	for _, g := range groups {
		val, _ := rec.Get(g)
		gvals[g] = val
	}
	if _, ok := v.groupSeen[gkey]; !ok {
		v.groupSeen[gkey] = true
		v.groupKeys = append(v.groupKeys, gkey)
	}
	fields := v.fieldsFor(rec)
	for _, f := range fields {
		val, _ := rec.Get(f)
		key := gkey + "\x01" + f
		acc, ok := v.acc[key]
		if !ok {
			acc = newStats1Acc()
			v.acc[key] = acc
		}
		if _, ok := v.fieldSeen[f]; !ok {
			v.fieldSeen[f] = true
			v.fieldNames = append(v.fieldNames, f)
		}
		acc.counts[val.String()]++
		if val.Kind == KindString && val.S == "" || val.Kind == KindNull {
			acc.nullCount++
		}
		if val.IsNumber() {
			x := toFloat(val)
			acc.sum += x
			acc.sum2 += x * x
			acc.sum3 += x * x * x
			acc.sum4 += x * x * x * x
			acc.values = append(acc.values, x)
		}
		if len(acc.strvals) < 1000 {
			acc.strvals = append(acc.strvals, val.String())
		}
		acc.n++
		if !v.iterative {
			acc.values = append([]float64{}, acc.values...)
		}
	}
	if v.iterative {
		return v.emitRecords(), nil
	}
	return nil, nil
}

func (v *stats1Verb) emitRecords() []*Record {
	out := []*Record{}
	for _, gkey := range v.groupKeys {
		for _, f := range v.fieldNames {
			key := gkey + "\x01" + f
			acc, ok := v.acc[key]
			if !ok {
				continue
			}
			r := NewMap()
			parts := strings.Split(gkey, "\x00")
			groups := v.groupsFor(nil)
			_ = groups
			for i, g := range v.groupFields {
				if i < len(parts) {
					r.Set(g, StringValue(parts[i]))
				}
			}
			for _, spec := range v.specs {
				name := f + "_" + spec.name
				r.Set(name, stats1Value(spec, acc, v.interpolated))
			}
			out = append(out, r)
		}
	}
	return out
}

func stats1Value(spec statsSpec, acc *stats1Acc, interpolated bool) Value {
	switch spec.name {
	case "count":
		return IntValue(int64(acc.n))
	case "null_count":
		return IntValue(int64(acc.nullCount))
	case "distinct_count":
		return IntValue(int64(len(acc.distinct)))
	case "mode":
		best := ""
		bestc := int64(-1)
		for _, s := range acc.strvals {
			if c := acc.counts[s]; c > bestc {
				bestc = c
				best = s
			}
		}
		return StringValue(best)
	case "antimode":
		best := ""
		bestc := int64(-1)
		for _, s := range acc.strvals {
			if c := acc.counts[s]; bestc < 0 || c < bestc {
				bestc = c
				best = s
			}
		}
		return StringValue(best)
	case "sum":
		return FloatValue(acc.sum)
	case "mean":
		if acc.n == 0 {
			return StringValue("")
		}
		return FloatValue(acc.sum / float64(acc.n))
	case "var":
		if acc.n == 0 {
			return StringValue("")
		}
		m := acc.sum / float64(acc.n)
		return FloatValue(acc.sum2/float64(acc.n) - m*m)
	case "stddev":
		if acc.n == 0 {
			return StringValue("")
		}
		m := acc.sum / float64(acc.n)
		return FloatValue(math.Sqrt(acc.sum2/float64(acc.n) - m*m))
	case "mad":
		if acc.n == 0 {
			return StringValue("")
		}
		m := acc.sum / float64(acc.n)
		sum := 0.0
		for _, x := range acc.values {
			sum += math.Abs(x - m)
		}
		return FloatValue(sum / float64(acc.n))
	case "meaneb":
		if acc.n == 0 {
			return StringValue("")
		}
		m := acc.sum / float64(acc.n)
		vv := acc.sum2/float64(acc.n) - m*m
		return FloatValue(math.Sqrt(vv/float64(acc.n)) * 1.96)
	case "skewness":
		if acc.n == 0 {
			return StringValue("")
		}
		m := acc.sum / float64(acc.n)
		vv := acc.sum2/float64(acc.n) - m*m
		if vv == 0 {
			return FloatValue(0)
		}
		sd := math.Sqrt(vv)
		return FloatValue((acc.sum3/float64(acc.n) - 3*m*vv - m*m*m) / (sd * sd * sd))
	case "kurtosis":
		if acc.n == 0 {
			return StringValue("")
		}
		m := acc.sum / float64(acc.n)
		vv := acc.sum2/float64(acc.n) - m*m
		if vv == 0 {
			return FloatValue(0)
		}
		sd := math.Sqrt(vv)
		return FloatValue((acc.sum4/float64(acc.n) - 4*m*acc.sum3/float64(acc.n) + 6*m*m*vv + m*m*m*m) / (sd * sd * sd * sd))
	case "min":
		if len(acc.values) == 0 {
			return StringValue("")
		}
		best := acc.values[0]
		for _, x := range acc.values {
			if x < best {
				best = x
			}
		}
		return FloatValue(best)
	case "max":
		if len(acc.values) == 0 {
			return StringValue("")
		}
		best := acc.values[0]
		for _, x := range acc.values {
			if x > best {
				best = x
			}
		}
		return FloatValue(best)
	case "minlen":
		best := 0
		first := true
		for _, s := range acc.strvals {
			if first || len(s) < best {
				best = len(s)
				first = false
			}
		}
		return IntValue(int64(best))
	case "maxlen":
		best := 0
		for _, s := range acc.strvals {
			if len(s) > best {
				best = len(s)
			}
		}
		return IntValue(int64(best))
	}
	if strings.HasPrefix(spec.name, "p") {
		var nd float64
		fmt.Sscanf(strings.TrimPrefix(spec.name, "p"), "%f", &nd)
		return percentileValue(acc.values, nd, interpolated)
	}
	return StringValue("")
}

func percentileValue(values []float64, nd float64, interpolated bool) Value {
	if len(values) == 0 {
		return StringValue("")
	}
	vals := append([]float64{}, values...)
	sort.Float64s(vals)
	if interpolated {
		idx := nd / 100.0 * float64(len(vals)-1)
		lo := math.Floor(idx)
		hi := math.Ceil(idx)
		if lo == hi {
			return FloatValue(vals[int(lo)])
		}
		frac := idx - lo
		return FloatValue(vals[int(lo)] + frac*(vals[int(hi)]-vals[int(lo)]))
	}
	idx := int(math.Ceil(nd / 100.0 * float64(len(vals))))
	if idx < 1 {
		idx = 1
	}
	if idx > len(vals) {
		idx = len(vals)
	}
	return FloatValue(vals[idx-1])
}

func (v *stats1Verb) End(ctx *Ctx) ([]*Record, error) {
	if v.iterative {
		return nil, nil
	}
	return v.emitRecords(), nil
}

func (v *stats1Verb) Close() error { return nil }

var _ = io.Discard
GOEOF
