func (w *pprintWriter) Write(rec *Record) error {
	w.buf = append(w.buf, rec)
	return nil
}

func (w *pprintWriter) WriteEnd() error {
	if len(w.buf) == 0 {
		return nil
	}
	widths := map[string]int{}
	order := []string{}
	seen := map[string]bool{}
	for _, rec := range w.buf {
		for _, k := range rec.Keys() {
			val, _ := rec.Get(k)
			l := len(k)
			if lv := len(val.String()); lv > l {
				l = lv
			}
			if !seen[k] {
				seen[k] = true
				order = append(order, k)
			}
			if l > widths[k] {
				widths[k] = l
			}
		}
	}
	if w.barred {
		io.WriteString(w.out, w.border(widths, order, w.opt.OFS))
	}
	io.WriteString(w.out, w.renderRow(NewHeaderRecord(order), widths, order))
	if w.barred {
		io.WriteString(w.out, w.border(widths, order, w.opt.OFS))
	}
	for _, rec := range w.buf {
		io.WriteString(w.out, w.renderRow(rec, widths, order))
	}
	if w.barred {
		io.WriteString(w.out, w.border(widths, order, w.opt.OFS))
	}
	return nil
}

func NewHeaderRecord(keys []string) *Record {
	r := NewMap()
	for _, k := range keys {
		r.Set(k, StringValue(k))
	}
	return r
}

func (w *pprintWriter) renderRow(rec *Record, widths map[string]int, order []string) string {
	var b strings.Builder
	for i, k := range order {
		val, ok := rec.Get(k)
		if !ok {
			continue
		}
		if i > 0 {
			b.WriteString(w.opt.OFS)
		}
		s := val.String()
		pad := widths[k] - len(s)
		if w.right {
			b.WriteString(strings.Repeat(w.opt.OFS, pad))
			b.WriteString(s)
		} else {
			b.WriteString(s)
			if i < len(order)-1 {
				b.WriteString(strings.Repeat(w.opt.OFS, pad))
			}
		}
	}
	b.WriteString("\n")
	return b.String()
}

func (w *pprintWriter) border(widths map[string]int, order []string, ofs string) string {
	var b strings.Builder
	for i, k := range order {
		if i > 0 {
			b.WriteString(ofs)
		}
		b.WriteString(strings.Repeat(ofs, widths[k]))
	}
	b.WriteString("\n")
	return b.String()
}

