func (w *xtabWriter2) Write(rec *Record) error {
	w.buf = append(w.buf, rec)
	return nil
}

func (w *xtabWriter2) WriteEnd() error {
	maxw := 0
	for _, rec := range w.buf {
		for _, k := range rec.Keys() {
			if len(k) > maxw {
				maxw = len(k)
			}
		}
	}
	for _, rec := range w.buf {
		if w.started {
			io.WriteString(w.out, "\n")
		}
		w.started = true
		for _, k := range rec.Keys() {
			val, _ := rec.Get(k)
			s := val.String()
			if w.right {
				io.WriteString(w.out, strings.Repeat(" ", maxw-len(k))+k)
			} else {
				io.WriteString(w.out, k+strings.Repeat(" ", maxw-len(k)))
			}
			io.WriteString(w.out, w.opt.OPS)
			io.WriteString(w.out, s)
			io.WriteString(w.out, "\n")
		}
	}
	return nil
}

