}

func (w *markdownWriter) Write(rec *Record) error {
	w.buf = append(w.buf, rec)
	return nil
}

func (w *markdownWriter) WriteEnd() error {
	if len(w.buf) == 0 {
		return nil
	}
	widths := map[string]int{}
	order := []string{}
	seen := map[string]bool{}
	for _, rec := range w.buf {
		for _, k := range rec.Keys() {
			val, _ := rec.Get(k)
			l := len(k)
			if lv := len(val.String()); lv > l {
				l = lv
			}
			if len(k) < 3 {
				l = 3
			}
			if !seen[k] {
				seen[k] = true
				order = append(order, k)
			}
			if l > widths[k] {
				widths[k] = l
			}
		}
	}
	var b strings.Builder
	for _, pass := range []string{"header", "sep", "data"} {
		for i, k := range order {
			if pass == "header" {
				s := k
				b.WriteString("| " + s + strings.Repeat(" ", widths[k]-len(s)) + " ")
			} else if pass == "sep" {
				b.WriteString("| " + strings.Repeat("-", widths[k]) + " ")
			} else {
				rec := w.buf[len(w.buf)-1]
				val, ok := rec.Get(k)
				if ok {
					s := val.String()
					b.WriteString("| " + s + strings.Repeat(" ", widths[k]-len(s)) + " ")
				} else {
					b.WriteString("| " + strings.Repeat(" ", widths[k]) + " ")
				}
			}
			_ = i
		}
		b.WriteString("|\n")
		if pass == "header" {
			for _, rec := range w.buf {
				var row strings.Builder
				for _, k := range order {
					val, ok := rec.Get(k)
					if ok {
						s := val.String()
						row.WriteString("| " + s + strings.Repeat(" ", widths[k]-len(s)) + " ")
					} else {
						row.WriteString("| " + strings.Repeat(" ", widths[k]) + " ")
					}
				}
				b.WriteString(row.String() + "|\n")
			}
		}
	}
	io.WriteString(w.out, b.String())
	return nil
}

