// ---------- YAML writer ----------

type yamlWriter struct {
	opt     *Options
	out     io.Writer
	started bool
}

var yamlSpecialKeys = map[string]bool{
	"y": true, "Y": true, "n": true, "N": true, "yes": true, "Yes": true, "YES": true,
	"no": true, "No": true, "NO": true, "true": true, "True": true, "TRUE": true,
	"false": true, "False": true, "FALSE": true, "on": true, "On": true, "ON": true,
	"off": true, "Off": true, "OFF": true, "null": true, "Null": true, "NULL": true, "~": true,
}

func yamlScalar(s string) string {
	if s == "" {
		return "\"\""
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		return s
	}
	if s == "true" || s == "false" || s == "null" || s == "y" || s == "n" ||
		s == "yes" || s == "no" || s == "on" || s == "off" {
		return "\"" + s + "\""
	}
	if strings.ContainsAny(s, "\n\t\"'") {
		return "\"" + strings.ReplaceAll(strings.ReplaceAll(s, "\\", "\\\\"), "\"", "\\\"") + "\""
	}
	return s
}

func (w *yamlWriter) Write(rec *Record) error {
	if !w.opt.YArray {
		if w.started {
			io.WriteString(w.out, "---\n")
		}
		w.started = true
		w.emit(rec, "")
		return nil
	}
	if !w.started {
		io.WriteString(w.out, "- ")
		w.started = true
		w.emit(rec, "")
		return nil
	}
	io.WriteString(w.out, "- ")
	w.emit(rec, "")
	return nil
}

func (w *yamlWriter) emit(rec *Record, prefix string) {
	for i, k := range rec.Keys() {
		val, _ := rec.Get(k)
		name := k
		if yamlSpecialKeys[name] || isNumericKey(name) {
			name = "\"" + name + "\""
		}
		if i > 0 || prefix == "" {
			if prefix == "" && i > 0 {
				io.WriteString(w.out, "  ")
			}
		}
		io.WriteString(w.out, prefix+name+": "+yamlScalar(val.String())+"\n")
	}
}

func isNumericKey(s string) bool {
	if s == "" {
		return false
	}
	_, err := strconv.ParseFloat(s, 64)
	return err == nil
}

func (w *yamlWriter) WriteEnd() error { return nil }

