// ---------- whole-file readers ----------

type blockReader struct {
	recs []*Record
	idx  int
}

func (r *blockReader) Next() (*Record, error) {
	if r.idx >= len(r.recs) {
		return nil, io.EOF
	}
	rec := r.recs[r.idx]
	r.idx++
	return rec, nil
}

func (r *blockReader) Close() error { return nil }

func splitBlocks(data string) []string {
	blocks := []string{}
	cur := []string{}
	for _, ln := range strings.Split(data, "\\n") {
		if strings.TrimSpace(ln) == "" {
			if len(cur) > 0 {
				blocks = append(blocks, strings.Join(cur, "\\n"))
				cur = []string{}
			}
			continue
		}
		cur = append(cur, ln)
	}
	if len(cur) > 0 {
		blocks = append(blocks, strings.Join(cur, "\\n"))
	}
	return blocks
}

// xtab

type xtabReader struct {
	opt   *Options
	block *blockReader
}

func newXTABReader(opt *Options) *xtabReader { return &xtabReader{opt: opt} }

func (r *xtabReader) Next() (*Record, error) {
	for {
		if r.block == nil {
			return nil, io.EOF
		}
		rec, err := r.block.Next()
		if err != nil {
			return nil, err
		}
		return rec, nil
	}
}

func (r *xtabReader) Close() error { return nil }

