			cur = NewMap()
			continue
		}
		if strings.HasPrefix(t, "- ") {
			if cur != nil {
				recs = append(recs, cur)
			}
			cur = NewMap()
			t = strings.TrimPrefix(t, "- ")
		}
		if cur == nil {
			continue
		}
		if i := strings.Index(t, ": "); i >= 0 {
