		} else if i := strings.Index(t, ":"); i >= 0 {
			k := strings.Trim(t[:i], "\\"")
			cur.Set(k, inferValue(strings.TrimSpace(t[i+1:]), opt))
		}
	}
	if cur != nil {
		recs = append(recs, cur)
	}
	return recs
}

