{"command": "cd /workspace; cat > dsl.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
	"unicode"
)

// ---------- lexer ----------

type tokKind int

const (
	tEOF tokKind = iota
	tIdent
	tInt
	tFloat
	tString
	tRegex
	tPunct
	tNL
	tSigil
	tNum
	tBool
	tNull
	tInf
	tNaN
)

type token struct {
	kind tokKind
	s    string
	i    int64
	f    float64
	re   bool
	line int
	col  int
	text string
}

type lexer struct {
	src  string
	pos  int
	line int
	col  int
	toks []token
}

func newLexer(src string) *lexer {
	return &lexer{src: src, line: 1, col: 1}
}

func (lx *lexer) peekc(off int) byte {
	if lx.pos+off >= len(lx.src) {
		return 0
	}
	return lx.src[lx.pos+off]
}

func (lx *lexer) adv() byte {
	c := lx.src[lx.pos]
	lx.pos++
	if c == '\n' {
		lx.line++
		lx.col = 1
	} else {
		lx.col++
	}
	return c
}

func (lx *lexer) tokenize() ([]token, error) {
	toks := []token{}
	for lx.pos < len(lx.src) {
		c := lx.peekc(0)
		if c == ' ' || c == '\t' || c == '\r' {
			lx.adv()
			continue
		}
		if c == '\n' {
			start := lx.pos
			lx.adv()
			toks = append(toks, token{kind: tNL, line: lx.line, text: lx.src[start:lx.pos-1]})
			continue
		}
		if c == '#' {
			for lx.pos < len(lx.src) && lx.peekc(0) != '\n' {
				lx.adv()
			}
			continue
		}
		startLine, startCol := lx.line, lx.col
		if c == '"' {
			s, err := lx.lexString()
			if err != nil {
				return nil, err
			}
			toks = append(toks, token{kind: tString, s: s, line: startLine, col: startCol, text: s})
			continue
		}
		if c == '$' || c == '@' {
			lx.adv()
			sigil := string(lx.src[lx.pos-1])
			// count [ or { sequences
			for lx.peekc(0) == '[' && lx.peekc(1) == '[' {
				lx.adv()
				lx.adv()
				sigil += "[["
			}
			if lx.peekc(0) == '[' {
				lx.adv()
				sigil += "["
			}
			if lx.peekc(0) == '{' {
				lx.adv()
				sigil += "{"
			}
			if lx.peekc(0) == '*' {
				lx.adv()
				toks = append(toks, token{kind: tSigil, s: sigil + "*", line: startLine, col: startCol})
				continue
			}
			// name
			var b strings.Builder
			for lx.pos < len(lx.src) {
				ch := lx.peekc(0)
				if ch == '_' || ch == '.' || unicode.IsLetter(rune(ch)) || (ch >= '0' && ch <= '9') || ch >= 0x80 {
					b.WriteByte(lx.adv())
					continue
				}
				break
			}
			name := b.String()
			// closing brace/brackets
			for lx.peekc(0) == '}' {
				lx.adv()
				sigil = strings.Replace(sigil, "{", "}", 1)
			}
			toks = append(toks, token{kind: tSigil, s: sigil, text: name, line: startLine, col: startCol})
			continue
		}
		if c >= '0' && c <= '9' || (c == '.' && lx.peekc(1) >= '0' && lx.peekc(1) <= '9') {
			tok := lx.lexNumber()
			tok.line, tok.col = startLine, startCol
			toks = append(toks, tok)
			continue
		}
		if isIdentStart(c) {
			var b strings.Builder
			for lx.pos < len(lx.src) {
				ch := lx.peekc(0)
				if isIdentStart(ch) || (ch >= '0' && ch <= '9') {
					b.WriteByte(lx.adv())
					continue
				}
				break
			}
			word := b.String()
			k := tIdent
			switch word {
			case "true", "false":
				k = tBool
			case "null":
				k = tNull
			case "inf":
				k = tInf
			case "nan":
				k = tNaN
			}
			toks = append(toks, token{kind: k, s: word, line: startLine, col: startCol, text: word})
			continue
		}
		// operators / punctuation
		op := lx.lexOp()
		if op == "" {
			return nil, fmt.Errorf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%s\" at line %d column %d.", string(c), lx.line, lx.col)
		}
		toks = append(toks, token{kind: tPunct, s: op, line: startLine, col: startCol})
	}
	toks = append(toks, token{kind: tEOF, line: lx.line, col: lx.col})
	return toks, nil
}

func rune(c byte) rune { return rune(c) }

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}

func (lx *lexer) lexString() (string, error) {
	var b strings.Builder
	lx.adv() // opening quote
	for lx.pos < len(lx.src) {
		c := lx.adv()
		if c == '"' {
			return b.String(), nil
		}
		if c == '\\' {
			if lx.pos >= len(lx.src) {
				break
			}
			e := lx.adv()
			switch e {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			case 'x':
				if lx.pos+2 <= len(lx.src) {
					if n, err := strconv.ParseUint(lx.src[lx.pos:lx.pos+2], 16, 32); err == nil {
						b.WriteByte(byte(n))
						lx.pos += 2
						continue
					}
				}
				b.WriteByte('x')
			default:
				if e >= '0' && e <= '9' {
					// capture group reference \1..\9
					b.WriteByte('\\')
					b.WriteByte(e)
					continue
				}
				b.WriteByte(e)
			}
			continue
		}
		b.WriteByte(c)
	}
	return "", fmt.Errorf("mlr: unterminated string literal")
}

func (lx *lexer) lexNumber() token {
	start := lx.pos
	isFloat := false
	for lx.pos < len(lx.src) {
		c := lx.peekc(0)
		if c >= '0' && c <= '9' {
			lx.adv()
			continue
		}
		if c == '.' {
			// avoid consuming concat dot followed by non-digit
			if lx.peekc(1) >= '0' && lx.peekc(1) <= '9' {
				isFloat = true
				lx.adv()
				continue
			}
			break
		}
		if c == 'e' || c == 'E' {
			nxt := lx.peekc(1)
			if (nxt >= '0' && nxt <= '9') || ((nxt == '+' || nxt == '-') && lx.peekc(2) >= '0' && lx.peekc(2) <= '9') {
				isFloat = true
				lx.adv()
				if lx.peekc(0) == '+' || lx.peekc(0) == '-' {
					lx.adv()
				}
				continue
			}
			break
		}
		break
	}
	s := lx.src[start:lx.pos]
	if isFloat {
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			f = 0
		}
		return token{kind: tFloat, s: s, f: f, text: s}
	}
	i, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		f, _ := strconv.ParseFloat(s, 64)
		return token{kind: tFloat, s: s, f: f, text: s}
	}
	return token{kind: tInt, s: s, i: i, text: s}
}

var dslOps = []string{
	"**", ">>>", "<<", ">>", "===", "<=>", "!~", "=~", "!=", "==", "<=", ">=", "&&", "||", "^^",
	".//", "./", ".*", ".+", ".-", "???", "??", "//", "++", "--", "+=", "-=", "*=", "/=",
	"+", "-", "*", "/", "%", "^", "&", "|", "~", "!", "<", ">", "=", ";", "(", ")", "{", "}",
	",", ".", "[", "]", ":", "?", "\x01", "\x02",
}

func (lx *lexer) lexOp() string {
	for _, op := range dslOps {
		if strings.HasPrefix(lx.src[lx.pos:], op) {
			for range op {
				lx.adv()
			}
			return op
		}
	}
	return ""
}

var _ = os.Stdout
var _ = unicode.IsLetter
GOEOF
gofmt -w dsl.go; go build ./... 2>&1|head -3"}

