			tok := lx.lexNumber()
			tok.line, tok.col = startLine, startCol
			toks = append(toks, tok)
			continue
		}
		if isIdentStart(c) {
			var b strings.Builder
			for lx.pos < len(lx.src) {
				ch := lx.peekc(0)
				if isIdentStart(ch) || (ch >= '0' && ch <= '9') {
					b.WriteByte(lx.adv())
					continue
				}
				break
			}
			word := b.String()
			k := tIdent
			switch word {
			case "true", "false":
				k = tBool
			case "null":
				k = tNull
			case "inf":
				k = tInf
			case "nan":
