		toks = append(toks, token{kind: tPunct, s: op, line: startLine, col: startCol})
	}
	toks = append(toks, token{kind: tEOF, line: lx.line, col: lx.col})
	return toks, nil
}

func rune(c byte) rune { return rune(c) }

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}

func (lx *lexer) lexString() (string, error) {
	var b strings.Builder
	lx.adv() // opening quote
	for lx.pos < len(lx.src) {
		c := lx.adv()
		if c == '"' {
			return b.String(), nil
		}
		if c == '\\' {
			if lx.pos >= len(lx.src) {
				break
			}
			e := lx.adv()
			switch e {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			case 'x':
				if lx.pos+2 <= len(lx.src) {
					if n, err := strconv.ParseUint(lx.src[lx.pos:lx.pos+2], 16, 32); err == nil {
						b.WriteByte(byte(n))
						lx.pos += 2
						continue
					}
				}
				b.WriteByte('x')
			default:
				if e >= '0' && e <= '9' {
					// capture group reference \1..\9
					b.WriteByte('\\')
					b.WriteByte(e)
					continue
				}
				b.WriteByte(e)
			}
			continue
		}
		b.WriteByte(c)
	}
	return "", fmt.Errorf("mlr: unterminated string literal")
}

func (lx *lexer) lexNumber() token {
	start := lx.pos
	isFloat := false
	for lx.pos < len(lx.src) {
		c := lx.peekc(0)
		if c >= '0' && c <= '9' {
			lx.adv()
			continue
		}
		if c == '.' {
			// avoid consuming concat dot followed by non-digit
			if lx.peekc(1) >= '0' && lx.peekc(1) <= '9' {
				isFloat = true
				lx.adv()
				continue
			}
			break
		}
		if c == 'e' || c == 'E' {
			nxt := lx.peekc(1)
			if (nxt >= '0' && nxt <= '9') || ((nxt == '+' || nxt == '-') && lx.peekc(2) >= '0' && lx.peekc(2) <= '9') {
				isFloat = true
				lx.adv()
				if lx.peekc(0) == '+' || lx.peekc(0) == '-' {
					lx.adv()
				}
				continue
			}
			break
		}
		break
	}
	s := lx.src[start:lx.pos]
	if isFloat {
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			f = 0
		}
		return token{kind: tFloat, s: s, f: f, text: s}
	}
	i, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		f, _ := strconv.ParseFloat(s, 64)
		return token{kind: tFloat, s: s, f: f, text: s}
	}
	return token{kind: tInt, s: s, i: i, text: s}
}

var dslOps = []string{
	"**", ">>>", "<<", ">>", "===", "<=>", "!~", "=~", "!=", "==", "<=", ">=", "&&", "||", "^^",
	".//", "./", ".*", ".+", ".-", "???", "??", "//", "++", "--", "+=", "-=", "*=", "/=",
	"+", "-", "*", "/", "%", "^", "&", "|", "~", "!", "<", ">", "=", ";", "(", ")", "{", "}",
	",", ".", "[", "]", ":", "?", "\x01", "\x02",
}

func (lx *lexer) lexOp() string {
	for _, op := range dslOps {
		if strings.HasPrefix(lx.src[lx.pos:], op) {
			for range op {
				lx.adv()
			}
			return op
		}
	}
	return ""
}

