cd /workspace; cat > dsl_parse.go <<'GOEOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Node is a DSL AST node.
type Node struct {
	Kind   string
	Str    string
	I      int64
	F      float64
	Re     bool
	Left   *Node
	Right  *Node
	Third  *Node
	List   []*Node
	Body   []*Node
	Sigil  string
	Line   int
	Col    int
	Name   string
}

// Parser

type parser struct {
	toks  []token
	pos   int
	funcc *parser
}

func newParser(src string) (*parser, error) {
	lx := newLexer(src)
	toks, err := lx.tokenize()
	if err != nil {
		return nil, err
	}
	return &parser{toks: toks}, nil
}

func (p *parser) cur() token  { return p.toks[p.pos] }
func (p *parser) next() token {
	t := p.toks[p.pos]
	if p.pos < len(p.toks)-1 {
		p.pos++
	}
	return t
}

func (p *parser) atNL() bool { return p.cur().kind == tNL }

// skipNL skips newline tokens
func (p *parser) skipNL() {
	for p.cur().kind == tNL {
		p.next()
	}
}

func (p *parser) at(kind tokKind, s string) bool {
	t := p.cur()
	return t.kind == kind && (s == "" || t.s == s)
}

func (p *parser) atPunct(s string) bool { return p.at(tPunct, s) }

func (p *parser) accept(kind tokKind, s string) bool {
	if p.at(kind, s) {
		p.next()
		return true
	}
	return false
}

func (p *parser) expect(kind tokKind, s string) error {
	if !p.accept(kind, s) {
		return p.errToken()
	}
	return nil
}

func (p *parser) errToken() error {
	t := p.cur()
	return fmt.Errorf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%s\" at line %d column %d.\nExpected one of:\n  { ( field_name $[ braced_field_name $[[ $[[[ full_srec oosvar_name @[ braced_oosvar_name\n  full_oosvar all non_sigil_name float int + - .+ .- ! ~ string_literal regex_case_insensitive\n  int_literal float_literal boolean_literal null_literal inf_literal nan_literal\n  const_M_PI const_M_E panic [ ctx_IPS ctx_IFS ctx_IRS ctx_OPS ctx_OFS ctx_ORS\n  ctx_FLATSEP ctx_NF ctx_NR ctx_FNR ctx_FILENAME ctx_FILENUM env func",
		t.text, t.line, t.col)
}

// parseProgram parses a sequence of statements.
func parseProgram(src string) ([]*Node, error) {
	p, err := newParser(src)
	if err != nil {
		return nil, err
	}
	return p.parseStmts(true)
}

func (p *parser) parseStmts(top bool) ([]*Node, error) {
	stmts := []*Node{}
	p.skipNL()
	for {
		p.skipNL()
		if p.cur().kind == tEOF {
			break
		}
		if !top && p.atPunct("}") {
			break
		}
		st, err := p.parseStmt()
		if err != nil {
			return nil, err
		}
		if st != nil {
			stmts = append(stmts, st)
		}
		p.skipNL()
		if p.atPunct(";") {
			p.next()
			continue
		}
		if p.cur().kind == tNL {
			continue
		}
		if p.cur().kind == tEOF || (!top && p.atPunct("}")) {
			break
		}
		if top {
			break
		}
	}
	return stmts, nil
}

func (p *parser) parseBlock() ([]*Node, error) {
	if err := p.expect(tPunct, "{"); err != nil {
		return nil, err
	}
	body, err := p.parseStmts(false)
	if err != nil {
		return nil, err
	}
	if err := p.expect(tPunct, "}"); err != nil {
		return nil, err
	}
	return body, nil
}

func (p *parser) parseStmt() (*Node, error) {
	t := p.cur()
	switch {
	case t.kind == tIdent:
		switch t.s {
		case "if":
			return p.parseIf()
		case "for":
			return p.parseFor()
		case "while":
			p.next()
			if err := p.expect(tPunct, "("); err != nil {
				return nil, err
			}
			cond, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expect(tPunct, ")"); err != nil {
				return nil, err
			}
			body, err := p.parseBlock()
			if err != nil {
				return nil, err
			}
			return &Node{Kind: "while", Left: cond, Body: body, Line: t.line}, nil
		case "do":
			p.next()
			body, err := p.parseBlock()
			if err != nil {
				return nil, err
			}
			if err := p.expectIdent("while"); err != nil {
				return nil, err
			}
			if err := p.expect(tPunct, "("); err != nil {
				return nil, err
			}
			cond, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expect(tPunct, ")"); err != nil {
				return nil, err
			}
			return &Node{Kind: "dowhile", Left: cond, Body: body, Line: t.line}, nil
		case "break":
			p.next()
			return &Node{Kind: "break"}, nil
		case "continue":
			p.next()
			return &Node{Kind: "continue"}, nil
		case "return":
			p.next()
			var e *Node
			if !p.atNL() && !p.atPunct(";") && !p.atPunct("}") && p.cur().kind != tEOF {
				var err error
				e, err = p.parseExpr()
				if err != nil {
					return nil, err
				}
			}
			return &Node{Kind: "return", Left: e}, nil
		case "var", "int", "float", "bool", "boolean", "num", "number", "str", "string", "map":
			return p.parseVarDecl()
		case "func", "funct":
			return p.parseFuncDef()
		case "subr":
			return p.parseSubrDef()
		case "call":
			p.next()
			name := p.cur().s
			if p.cur().kind != tIdent {
				return nil, p.errToken()
			}
			p.next()
			args, err := p.parseArgList()
			if err != nil {
				return nil, err
			}
			return &Node{Kind: "call", Name: name, List: args, Line: t.line}, nil
		case "begin":
			p.next()
			body, err := p.parseBlock()
			if err != nil {
				return nil, err
			}
			return &Node{Kind: "begin", Body: body}, nil
		case "end":
			p.next()
			body, err := p.parseBlock()
			if err != nil {
				return nil, err
			}
			return &Node{Kind: "end", Body: body}, nil
		case "emit", "emitf", "emitp":
			return p.parseEmit(t.s)
		case "emit1":
			p.next()
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			redir := p.parseRedirect()
			return &Node{Kind: "emit1", Left: e, Third: redir}, nil
		case "print", "printn", "eprint", "eprintn":
			p.next()
			args := []*Node{}
			for !p.atNL() && !p.atPunct(";") && !p.atPunct("}") && !p.atPunct(">") && !p.atPunct(">>") && p.cur().kind != tEOF {
				e, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				args = append(args, e)
				if !p.accept(tPunct, ",") {
					break
				}
			}
			redir := p.parseRedirect()
			return &Node{Kind: t.s, List: args, Third: redir, Line: t.line}, nil
		case "dump", "edump":
			p.next()
			var e *Node
			if !p.atNL() && !p.atPunct(";") && !p.atPunct("}") && p.cur().kind != tEOF {
				var err error
				e, err = p.parseExpr()
				if err != nil {
					return nil, err
				}
			}
			redir := p.parseRedirect()
			return &Node{Kind: t.s, Left: e, Third: redir}, nil
		case "tee":
			p.next()
			args := []*Node{}
			for !p.atNL() && !p.atPunct(";") && !p.atPunct("}") && p.cur().kind != tEOF {
				e, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				args = append(args, e)
				if !p.accept(tPunct, ",") {
					break
				}
			}
			redir := p.parseRedirect()
			return &Node{Kind: "tee", List: args, Third: redir}, nil
		case "env":
			// ENV["X"]
			p.next()
			return &Node{Kind: "env"}, nil
		case "panic":
			p.next()
			args, err := p.parseArgList()
			if err != nil {
				return nil, err
			}
			return &Node{Kind: "panic", List: args}, nil
		case "stdout":
			p.next()
			return &Node{Kind: "stdout"}, nil
		case "stderr":
			p.next()
			return &Node{Kind: "stderr"}, nil
		case "all":
			p.next()
			return &Node{Kind: "all"}, nil
		case "true", "false", "null", "inf", "nan":
			return p.parseExpr()
		}
		// assignment or expression statement
		return p.parseExprOrAssign()
	case t.kind == tSigil:
		return p.parseExprOrAssign()
	case t.kind == tPunct:
		if t.s == "{" {
			// bare block
			body, err := p.parseBlock()
			if err != nil {
				return nil, err
			}
			return &Node{Kind: "blockstmt", Body: body}, nil
		}
		return p.parseExprOrAssign()
	}
	return p.parseExprOrAssign()
}

func (p *parser) expectIdent(s string) error {
	if p.cur().kind == tIdent && p.cur().s == s {
		p.next()
		return nil
	}
	return p.errToken()
}

func (p *parser) parseIf() (*Node, error) {
	t := p.next() // if
	if err := p.expect(tPunct, "("); err != nil {
		return nil, err
	}
	cond, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if err := p.expect(tPunct, ")"); err != nil {
		return nil, err
	}
	body, err := p.parseBlock()
	if err != nil {
		return nil, err
	}
	node := &Node{Kind: "if", Left: cond, Body: body, Line: t.line}
	p.skipNL()
	if p.cur().kind == tIdent && p.cur().s == "elif" {
		p.next()
		if err := p.expect(tPunct, "("); err != nil {
			return nil, err
		}
		cond2, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expect(tPunct, ")"); err != nil {
			return nil, err
		}
		body2, err := p.parseBlock()
		if err != nil {
			return nil, err
		}
		elifNode := &Node{Kind: "if", Left: cond2, Body: body2}
		p.skipNL()
		if p.cur().kind == tIdent && p.cur().s == "else" {
			p.next()
			eb, err := p.parseBlock()
			if err != nil {
				return nil, err
			}
			elifNode.Right = &Node{Kind: "blockstmt", Body: eb}
		}
		node.Right = elifNode
		return node, nil
	}
	if p.cur().kind == tIdent && p.cur().s == "else" {
		p.next()
		eb, err := p.parseBlock()
		if err != nil {
			return nil, err
		}
		node.Right = &Node{Kind: "blockstmt", Body: eb}
	}
	return node, nil
}

func (p *parser) parseFor() (*Node, error) {
	t := p.next()
	if err := p.expect(tPunct, "("); err != nil {
		return nil, err
	}
	// for (k, v in map) or for (e in arr) or for (init; cond; step)
	save := p.pos
	name1 := ""
	if p.cur().kind == tIdent {
		name1 = p.next().s
		if p.accept(tPunct, ",") && p.cur().kind == tIdent {
			name2 := p.next().s
			if p.cur().kind == tIdent && p.cur().s == "in" {
				p.next()
				container, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				if err := p.expect(tPunct, ")"); err != nil {
					return nil, err
				}
				body, err := p.parseBlock()
				if err != nil {
					return nil, err
				}
				return &Node{Kind: "forkv", Str: name1, Name: name2, Left: container, Body: body, Line: t.line}, nil
			}
		}
		if p.cur().kind == tIdent && p.cur().s == "in" {
			p.next()
			container, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expect(tPunct, ")"); err != nil {
				return nil, err
			}
			body, err := p.parseBlock()
			if err != nil {
				return nil, err
			}
			return &Node{Kind: "forin", Str: name1, Left: container, Body: body, Line: t.line}, nil
		}
	}
	p.pos = save
	init, err := p.parseStmt()
	if err != nil {
		return nil, err
	}
	if err := p.expect(tPunct, ";"); err != nil {
		return nil, err
	}
	cond, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if err := p.expect(tPunct, ";"); err != nil {
		return nil, err
	}
	step, err := p.parseStmt()
	if err != nil {
		return nil, err
	}
	if err := p.expect(tPunct, ")"); err != nil {
		return nil, err
	}
	body, err := p.parseBlock()
	if err != nil {
		return nil, err
	}
	return &Node{Kind: "forc", List: []*Node{init, cond, step}, Body: body, Line: t.line}, nil
}

func (p *parser) parseVarDecl() (*Node, error) {
	kw := p.next().s
	typ := ""
	if kw != "var" {
		typ = kw
		if p.cur().kind == tIdent {
			// could be "var int x" or "int x"
			if p.cur().s == "int" || p.cur().s == "float" || p.cur().s == "bool" ||
				p.cur().s == "boolean" || p.cur().s == "num" || p.cur().s == "number" ||
				p.cur().s == "str" || p.cur().s == "string" || p.cur().s == "map" {
				typ = p.next().s
			}
		}
	}
	if p.cur().kind != tIdent {
		return nil, p.errToken()
	}
	name := p.next().s
	var init *Node
	if p.accept(tPunct, "=") {
		var err error
		init, err = p.parseExpr()
		if err != nil {
			return nil, err
		}
	}
	return &Node{Kind: "vardecl", Str: typ, Name: name, Left: init}, nil
}

func (p *parser) parseFuncDef() (*Node, error) {
	t := p.next()
	if p.cur().kind != tIdent {
		return nil, p.errToken()
	}
	name := p.next().s
	params, err := p.parseArgList()
	if err != nil {
		return nil, err
	}
	body, err := p.parseBlock()
	if err != nil {
		return nil, err
	}
	return &Node{Kind: "funcdef", Name: name, List: params, Body: body, Line: t.line}, nil
}

func (p *parser) parseSubrDef() (*Node, error) {
	t := p.next()
	if p.cur().kind != tIdent {
		return nil, p.errToken()
	}
	name := p.next().s
	params, err := p.parseArgList()
	if err != nil {
		return nil, err
	}
	body, err := p.parseBlock()
	if err != nil {
		return nil, err
	}
	return &Node{Kind: "subrdef", Name: name, List: params, Body: body, Line: t.line}, nil
}

func (p *parser) parseArgList() ([]*Node, error) {
	if err := p.expect(tPunct, "("); err != nil {
		return nil, err
	}
	args := []*Node{}
	for !p.atPunct(")") {
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		args = append(args, e)
		if !p.accept(tPunct, ",") {
			break
		}
	}
	if err := p.expect(tPunct, ")"); err != nil {
		return nil, err
	}
	return args, nil
}

func (p *parser) parseRedirect() *Node {
	if p.atPunct(">") || p.atPunct(">>") {
		op := p.next().s
		e, err := p.parseExpr()
		if err != nil {
			return nil
		}
		return &Node{Kind: "redirect", Str: op, Left: e}
	}
	return nil
}

func (p *parser) parseEmit(kind string) (*Node, error) {
	t := p.next()
	args := []*Node{}
	for !p.atNL() && !p.atPunct(";") && !p.atPunct("}") && !p.atPunct(">") && !p.atPunct(">>") && p.cur().kind != tEOF {
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		args = append(args, e)
		if !p.accept(tPunct, ",") {
			break
		}
	}
	redir := p.parseRedirect()
	return &Node{Kind: kind, List: args, Third: redir, Line: t.line}, nil
}

// parseExprOrAssign parses either an assignment or an expression statement.
func (p *parser) parseExprOrAssign() (*Node, error) {
	lhs, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	t := p.cur()
	switch t.s {
	case "=", "+=", "-=", "*=", "/=", "//=", "^=", ".=", "%=", "**=", "<<=", ">>=":
		p.next()
		rhs, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		return &Node{Kind: "assign", Str: t.s, Left: lhs, Right: rhs, Line: t.line}, nil
	}
	return &Node{Kind: "exprstmt", Left: lhs, Line: t.line}, nil
}

// Expressions

func (p *parser) parseExpr() (*Node, error) {
	return p.parseCoalesce()
}

func (p *parser) parseCoalesce() (*Node, error) {
	left, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	for p.atPunct("??") || p.atPunct("???") {
		op := p.next().s
		right, err := p.parseOr()
		if err != nil {
			return nil, err
		}
		left = &Node{Kind: "binop", Str: op, Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) parseOr() (*Node, error) {
	left, err := p.parseXor()
	if err != nil {
		return nil, err
	}
	for p.atPunct("||") {
		p.next()
		right, err := p.parseXor()
		if err != nil {
			return nil, err
		}
		left = &Node{Kind: "binop", Str: "||", Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) parseXor() (*Node, error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.atPunct("^^") {
		p.next()
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		left = &Node{Kind: "binop", Str: "^^", Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) parseAnd() (*Node, error) {
	left, err := p.parseCompare()
	if err != nil {
		return nil, err
	}
	for p.atPunct("&&") {
		p.next()
		right, err := p.parseCompare()
		if err != nil {
			return nil, err
		}
		left = &Node{Kind: "binop", Str: "&&", Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) parseCompare() (*Node, error) {
	left, err := p.parseConcat()
	if err != nil {
		return nil, err
	}
	for {
		t := p.cur()
		if t.kind != tPunct {
			break
		}
		switch t.s {
		case "==", "!=", "=~", "!~", "!~=", "!~", "<=", ">=", "<", ">", "<=>":
			op := t.s
			if t.s == "!~" || t.s == "!~=" {
				op = "!=~"
			}
			p.next()
			right, err := p.parseConcat()
			if err != nil {
				return nil, err
			}
			left = &Node{Kind: "binop", Str: op, Left: left, Right: right}
			continue
		}
		break
	}
	return left, nil
}

func (p *parser) parseConcat() (*Node, error) {
	left, err := p.parseAdditive()
	if err != nil {
		return nil, err
	}
	for p.atPunct(".") && !(p.peekIsDigit()) {
		p.next()
		right, err := p.parseAdditive()
		if err != nil {
			return nil, err
		}
		left = &Node{Kind: "binop", Str: ".", Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) peekIsDigit() bool {
	i := p.pos + 1
	if i < len(p.toks) && p.toks[i].kind == tFloat {
		return true
	}
	return false
}

func (p *parser) parseAdditive() (*Node, error) {
	left, err := p.parseMultiplicative()
	if err != nil {
		return nil, err
	}
	for p.atPunct("+") || p.atPunct("-") || p.atPunct(".+") || p.atPunct(".-") {
		op := p.next().s
		right, err := p.parseMultiplicative()
		if err != nil {
			return nil, err
		}
		left = &Node{Kind: "binop", Str: op, Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) parseMultiplicative() (*Node, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for p.atPunct("*") || p.atPunct("/") || p.atPunct("//") || p.atPunct("%") ||
		p.atPunct(".*") || p.atPunct("./") || p.atPunct(".//") {
		op := p.next().s
		right, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		left = &Node{Kind: "binop", Str: op, Left: left, Right: right}
	}
	return left, nil
}

func (p *parser) parseUnary() (*Node, error) {
	t := p.cur()
	if t.kind == tPunct && (t.s == "-" || t.s == "+" || t.s == "!" || t.s == "~") {
		p.next()
		operand, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &Node{Kind: "unop", Str: t.s, Left: operand}, nil
	}
	return p.parsePower()
}

func (p *parser) parsePower() (*Node, error) {
	left, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	if p.atPunct("**") {
		p.next()
		right, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &Node{Kind: "binop", Str: "**", Left: left, Right: right}, nil
	}
	return left, nil
}

func (p *parser) parsePostfix() (*Node, error) {
	left, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for {
		if p.atPunct("[") {
			p.next()
			idx, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expect(tPunct, "]"); err != nil {
				return nil, err
			}
			left = &Node{Kind: "index", Left: left, Right: idx}
			continue
		}
		if p.atPunct("(") && left.Kind == "ident" {
			args, err := p.parseArgList()
			if err != nil {
				return nil, err
			}
			left = &Node{Kind: "call", Name: left.Str, List: args}
			continue
		}
		break
	}
	return left, nil
}

var constNames = map[string]string{
	"M_PI": "M_PI", "M_E": "M_E",
}

func (p *parser) parsePrimary() (*Node, error) {
	t := p.cur()
	switch t.kind {
	case tInt:
		p.next()
		return &Node{Kind: "int", I: t.i, Str: t.text}, nil
	case tFloat:
		p.next()
		return &Node{Kind: "float", F: t.f, Str: t.text}, nil
	case tString:
		p.next()
		return &Node{Kind: "str", Str: t.s}, nil
	case tRegex:
		p.next()
		return &Node{Kind: "str", Str: t.s}, nil
	case tBool:
		p.next()
		return &Node{Kind: "bool", Str: t.s}, nil
	case tNull:
		p.next()
		return &Node{Kind: "null"}, nil
	case tInf:
		p.next()
		return &Node{Kind: "inf", Str: t.s}, nil
	case tNaN:
		p.next()
		return &Node{Kind: "nan"}, nil
	case tSigil:
		return p.parseSigil()
	case tPunct:
		switch t.s {
		case "(":
			p.next()
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expect(tPunct, ")"); err != nil {
				return nil, err
			}
			return e, nil
		case "[":
			p.next()
			items := []*Node{}
			for !p.atPunct("]") {
				e, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				items = append(items, e)
				if !p.accept(tPunct, ",") {
					break
				}
			}
			if err := p.expect(tPunct, "]"); err != nil {
				return nil, err
			}
			return &Node{Kind: "arraylit", List: items}, nil
		case "{":
			p.next()
			items := []*Node{}
			for !p.atPunct("}") {
				e, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				items = append(items, e)
				if !p.accept(tPunct, ",") {
					break
				}
			}
			if err := p.expect(tPunct, "}"); err != nil {
				return nil, err
			}
			return &Node{Kind: "maplit", List: items}, nil
		}
	case tIdent:
		name := t.s
		switch name {
		case "M_PI", "M_E":
			p.next()
			return &Node{Kind: "const", Str: name}, nil
		case "panic":
			p.next()
			args, err := p.parseArgList()
			if err != nil {
				return nil, err
			}
			return &Node{Kind: "panic", List: args}, nil
		case "ENV":
			p.next()
			idx, err := p.parsePostfixIndex()
			if err != nil {
				return nil, err
			}
			return &Node{Kind: "env", Left: idx}, nil
		case "stdout":
			p.next()
			return &Node{Kind: "stdout"}, nil
		case "stderr":
			p.next()
			return &Node{Kind: "stderr"}, nil
		case "all":
			p.next()
			return &Node{Kind: "all"}, nil
		case "env":
			p.next()
			return &Node{Kind: "envcall"}, nil
		case "func":
			p.next()
			return p.parseFuncDef()
		case "IPS", "IFS", "IRS", "OPS", "OFS", "ORS", "FLATSEP", "NF", "NR", "FNR",
			"FILENAME", "FILENUM":
			p.next()
			return &Node{Kind: "ctx", Str: name}, nil
		}
		if isBuiltinFunc(name) {
			p.next()
			args, err := p.parseArgList()
			if err != nil {
				return nil, err
			}
			return &Node{Kind: "call", Name: name, List: args}, nil
		}
		p.next()
		return &Node{Kind: "ident", Str: name}, nil
	}
	return nil, p.errToken()
}

func (p *parser) parsePostfixIndex() (*Node, error) {
	if p.atPunct("[") {
		p.next()
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expect(tPunct, "]"); err != nil {
			return nil, err
		}
		return e, nil
	}
	return nil, nil
}

// parseSigil handles $name, $*, $[expr], $[[expr]], $[[[expr]]], @{...}, @*
func (p *parser) parseSigil() (*Node, error) {
	t := p.next()
	sigil := t.s
	name := t.text
	switch sigil {
	case "$", "$*", "@", "@*":
		if name == "*" {
			kind := "srec"
			if sigil[0] == '@' {
				kind = "oosvar"
			}
			return &Node{Kind: kind}, nil
		}
		kind := "field"
		if sigil[0] == '@' {
			kind = "oos"
		}
		if len(sigil) > 1 && sigil[1] == '{' {
			kind += "-braced"
		}
		n := &Node{Kind: kind, Str: name, Name: name, Sigil: sigil}
		// trailing [expr]
		for p.atPunct("[") {
			p.next()
			idx, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expect(tPunct, "]"); err != nil {
				return nil, err
			}
			n = &Node{Kind: "index", Left: n, Right: idx}
		}
		return n, nil
	case "$[", "$[[", "$[[[":
		idx, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expect(tPunct, "]"); err != nil {
			return nil, err
		}
		kind := "fieldidx"
		switch sigil {
		case "$[":
			kind = "fieldidx"
		case "$ [[":
			kind = "fieldnameidx"
		}
		if sigil == "$[[" {
			kind = "fieldnameidx"
		}
		if sigil == "$[[[" {
			kind = "fieldpairidx"
		}
		return &Node{Kind: kind, Left: idx}, nil
	case "@[", "@[[", "@[[[":
		idx, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expect(tPunct, "]"); err != nil {
			return nil, err
		}
		kind := "oosidx"
		if sigil == "@[[" {
			kind = "oosnameidx"
		}
		if sigil == "@[[[" {
			kind = "oospairidx"
		}
		return &Node{Kind: kind, Left: idx}, nil
	}
	return nil, p.errToken()
}

