// ---------- runtime ----------

type RT struct {
	ctx        *Ctx
	rec        *Record
	oos        *Map
	locals     []map[string]Value
	captures   []string
	funcs      map[string]*Node
	subrs      map[string]*Node
	emitOut    []*Record
	lastValue  Value
	filterVal  Value
	hasFilter  bool
	brk        bool
	cont       bool
	ret        bool
	retVal     Value
	warnings   []string
	errExit    bool
	dslOpts    *DSLOpts
}

type DSLOpts struct {
	quiet     bool
	invert    bool
	warn      bool
}

func NewRT(ctx *Ctx, o *DSLOpts) *RT {
	return &RT{ctx: ctx, rec: NewMap(), oos: NewMap(), locals: []map[string]Value{{}},
		funcs: map[string]*Node{}, subrs: map[string]*Node{}, dslOpts: o}
}

func (rt *RT) pushScope() { rt.locals = append(rt.locals, map[string]Value{}) }
func (rt *RT) popScope() {
	if len(rt.locals) > 1 {
		rt.locals = rt.locals[:len(rt.locals)-1]
	}
}

func (rt *RT) lookupLocal(name string) (Value, bool) {
	for i := len(rt.locals) - 1; i >= 0; i-- {
		if v, ok := rt.locals[i][name]; ok {
			return v, true
		}
	}
	return NullValue(), false
}

func (rt *RT) setLocal(name string, v Value) {
	for i := len(rt.locals) - 1; i >= 0; i-- {
		if _, ok := rt.locals[i][name]; ok {
			rt.locals[i][name] = v
			return
		}
	}
	rt.locals[len(rt.locals)-1][name] = v
}

func errorValue() Value  { return Value{Kind: KindError} }
func absentValue() Value { return Value{Kind: KindAbsent} }

func isError(v Value) bool { return v.Kind == KindError }
func isAbsent(v Value) bool { return v.Kind == KindAbsent }

// numResult converts a numeric result to int when both operands were ints.
func (rt *RT) arith(op string, a, b Value) Value {
	if isError(a) || isError(b) || isAbsent(a) || isAbsent(b) {
		return errorValue()
	}
	if op == "." {
		return StringValue(strVal(a) + strVal(b))
	}
	if !a.IsNumber() || !b.IsNumber() {
		return errorValue()
	}
	ai, aInt := a.Kind == KindInt
	bi, bInt := b.Kind == KindInt
	switch op {
	case "+", ".+":
		if ai && bi {
			s := a.I + b.I
			if op == "+" && (s < a.I) != (b.I < 0) && (s < b.I) != (a.I < 0) {
				return FloatValue(float64(a.I) + float64(b.I))
			}
			return IntValue(s)
		}
		return FloatValue(toFloat(a) + toFloat(b))
	case "-", ".-":
		if ai && bi {
			return IntValue(a.I - b.I)
		}
		return FloatValue(toFloat(a) - toFloat(b))
	case "*", ".*":
		if ai && bi {
			if op == "*" {
				if a.I != 0 && b.I != 0 {
					p := a.I * b.I
					if p/b.I != a.I {
						return FloatValue(float64(a.I) * float64(b.I))
					}
					return IntValue(p)
				}
				return IntValue(0)
			}
			return IntValue(a.I * b.I)
		}
		return FloatValue(toFloat(a) * toFloat(b))
	case "/", "./":
		if ai && bi {
			if b.I == 0 {
				return errorValue()
			}
			if a.I%b.I == 0 {
				return IntValue(a.I / b.I)
			}
			return FloatValue(float64(a.I) / float64(b.I))
		}
		bf := toFloat(b)
		if bf == 0 {
			return errorValue()
		}
		return FloatValue(toFloat(a) / bf)
	case "//", ".//":
		if ai && bi {
			if b.I == 0 {
				return errorValue()
			}
			return IntValue(a.I / b.I)
		}
		bf := toFloat(b)
		if bf == 0 {
			return errorValue()
		}
		return FloatValue(math.Trunc(toFloat(a) / bf))
	case "%":
		if ai && bi {
			if b.I == 0 {
				return errorValue()
			}
			m := a.I % b.I
			if m < 0 {
				m += absInt(b.I)
			}
			return IntValue(m)
		}
		bf := toFloat(b)
		if bf == 0 {
			return errorValue()
		}
		m := math.Mod(toFloat(a), bf)
		if m < 0 {
			m += math.Abs(bf)
		}
		return FloatValue(m)
	case "**":
		if ai && bi && b.I >= 0 {
			r := powInt(a.I, b.I)
			if r.ok {
				return IntValue(r.v)
			}
		}
		return FloatValue(math.Pow(toFloat(a), toFloat(b)))
	case "&":
		if ai && bi {
			return IntValue(a.I & b.I)
		}
		return errorValue()
	case "|":
		if ai && bi {
			return IntValue(a.I | b.I)
		}
		return errorValue()
	case "^":
		if ai && bi {
			return IntValue(a.I ^ b.I)
		}
		return errorValue()
	case "<<":
		if ai && bi {
			return IntValue(a.I << uint64(b.I))
		}
		return errorValue()
	case ">>":
		if ai && bi {
			return IntValue(a.I >> uint64(b.I))
		}
		return errorValue()
	case ">>>":
		if ai && bi {
			return IntValue(int64(uint64(a.I) >> uint64(b.I)))
		}
		return errorValue()
	}
	return errorValue()
}

type powRes struct {
	v  int64
	ok bool
}

func powInt(base, exp int64) powRes {
	if exp < 0 {
		return powRes{0, false}
	}
	var acc int64 = 1
	var b int64 = base
	for e := exp; e > 0; e >>= 1 {
		if e&1 == 1 {
			if acc != 0 && absInt(acc) > (1<<62)/absInt(b) {
				return powRes{0, false}
			}
			acc *= b
		}
		e >>= 0
