		if bf == 0 {
			return errorValue()
		}
		m := math.Mod(toFloat(a), bf)
		if m < 0 {
			m += math.Abs(bf)
		}
		return FloatValue(m)
	case "**":
		if ai && bi && b.I >= 0 {
			r := powInt(a.I, b.I)
			if r.ok {
				return IntValue(r.v)
			}
		}
		return FloatValue(math.Pow(toFloat(a), toFloat(b)))
	case "&":
		if ai && bi {
			return IntValue(a.I & b.I)
		}
		return errorValue()
	case "|":
		if ai && bi {
			return IntValue(a.I | b.I)
		}
		return errorValue()
	case "^":
		if ai && bi {
			return IntValue(a.I ^ b.I)
		}
		return errorValue()
	case "<<":
		if ai && bi {
			return IntValue(a.I << uint64(b.I))
		}
		return errorValue()
	case ">>":
		if ai && bi {
			return IntValue(a.I >> uint64(b.I))
		}
		return errorValue()
	case ">>>":
		if ai && bi {
			return IntValue(int64(uint64(a.I) >> uint64(b.I)))
		}
		return errorValue()
	}
	return errorValue()
}

type powRes struct {
	v  int64
	ok bool
}

func powInt(base, exp int64) powRes {
	if exp < 0 {
		return powRes{0, false}
	}
	var acc int64 = 1
	var b int64 = base
	for e := exp; e > 0; e >>= 1 {
		if e&1 == 1 {
			if acc != 0 && absInt(acc) > (1<<62)/absInt(b) {
				return powRes{0, false}
			}
			acc *= b
		}
		e >>= 0
		if b != 0 && absInt(b) > (1<<62) {
			return powRes{0, false}
		}
		if e > 1 {
			b *= b
		}
		if e <= 1 {
			break
		}
	}
	return powRes{acc, true}
}

func absInt(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func strVal(v Value) string {
	switch v.Kind {
	case KindString:
		return v.S
	case KindNull:
		return "null"
	case KindBool:
		if v.B {
			return "true"
		}
		return "false"
	}
	return v.String()
}

func truthy(v Value) bool {
	switch v.Kind {
	case KindBool:
		return v.B
	case KindInt:
		return v.I != 0
	case KindFloat:
		return v.F != 0
	case KindNull, KindAbsent:
		return false
	case KindError:
		return false
	case KindString:
		return v.S != ""
	}
	return true
}

// compare implements ==, !=, <, <=, >, >=, <=>
func (rt *RT) compare(op string, a, b Value) Value {
	if isError(a) || isError(b) || isAbsent(a) || isAbsent(b) {
		return BoolValue(false)
	}
	switch op {
	case "==":
		return BoolValue(valuesEqual(a, b))
	case "!=":
		return BoolValue(!valuesEqual(a, b))
	}
	c, ok := compareValues(a, b)
	if !ok {
		return errorValue()
	}
	switch op {
	case "<":
		return BoolValue(c < 0)
	case "<=":
		return BoolValue(c <= 0)
	case ">":
		return BoolValue(c > 0)
	case ">=":
		return BoolValue(c >= 0)
	case "<=>":
		return IntValue(int64(c))
	}
	return BoolValue(false)
}

func valuesEqual(a, b Value) bool {
	if a.Kind != b.Kind {
		if a.IsNumber() && b.IsNumber() {
			return toFloat(a) == toFloat(b)
		}
		return false
	}
	switch a.Kind {
	case KindString:
		return a.S == b.S
	case KindInt:
		return a.I == b.I
	case KindFloat:
		return a.F == b.F
	case KindBool:
		return a.B == b.B
	case KindNull:
		return true
	case KindArray:
		if len(a.A) != len(b.A) {
			return false
		}
		for i := range a.A {
			if !valuesEqual(a.A[i], b.A[i]) {
				return false
			}
		}
		return true
	case KindMap:
		if a.M.Len() != b.M.Len() {
			return false
		}
		for _, k := range a.M.Keys() {
			bv, ok := b.M.Get(k)
			if !ok {
				return false
			}
			av, _ := a.M.Get(k)
			if !valuesEqual(av, bv) {
				return false
			}
		}
		return true
	}
	return true
}

func compareValues(a, b Value) (int, bool) {
	if a.IsNumber() && b.IsNumber() {
		x, y := toFloat(a), toFloat(b)
		if x < y {
			return -1, true
		}
		if x > y {
			return 1, true
		}
		return 0, true
	}
	if a.Kind == KindString && b.Kind == KindString {
		return strings.Compare(a.S, b.S), true
	}
	if a.Kind == KindString || b.Kind == KindString {
		return 0, false
	}
	if a.Kind == KindBool && b.Kind == KindBool {
		bi, bb := 0, 0
		if a.B {
			bi = 1
		}
		if b.B {
			bb = 1
		}
		return bi - bb, true
	}
	if a.Kind == KindNull && b.Kind == KindNull {
		return 0, true
	}
	return 0, false
}

// indexValue handles v[k]
func (rt *RT) indexValue(v Value, idx Value) Value {
	switch v.Kind {
	case KindMap:
		k := strVal(idx)
		val, ok := v.M.Get(k)
		if !ok {
			return absentValue()
		}
		return val
	case KindArray:
		if idx.Kind != KindInt && idx.Kind != KindFloat {
			return errorValue()
		}
		i := int(toInt(idx))
		if i < 1 || i > len(v.A) {
			return absentValue()
		}
		return v.A[i-1]
	case KindString:
		if idx.Kind != KindInt && idx.Kind != KindFloat {
			return errorValue()
		}
		i := int(toInt(idx))
		rs := []rune(v.S)
		if i < 1 || i > len(rs) {
			return absentValue()
		}
		return StringValue(string(rs[i-1]))
	}
	return errorValue()
}

// setValueIndex assigns v[k] = val on a container
func (rt *RT) setIndex(container Value, idx Value, val Value) Value {
	switch container.Kind {
	case KindMap:
		m := container.M.Clone()
		if isError(val) || isAbsent(val) {
			m.Unset(strVal(idx))
		} else {
			m.Set(strVal(idx), val)
		}
		return MapValue(m)
	case KindArray:
		if idx.Kind != KindInt && idx.Kind != KindFloat {
			return errorValue()
		}
		i := int(toInt(idx))
		a := append([]Value{}, container.A...)
		if i < 1 {
			return errorValue()
		}
		for len(a) < i {
			a = append(a, absentValue())
		}
		if isError(val) || isAbsent(val) {
			a[i-1] = NullValue()
		} else {
			a[i-1] = val
		}
		return Value{Kind: KindArray, A: a}
	}
	return errorValue()
}

