package main

import (
	"fmt"
	"math"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

// ---------- expression evaluation ----------

func (rt *RT) eval(n *Node) Value {
	if n == nil {
		return absentValue()
	}
	switch n.Kind {
	case "int":
		return Value{Kind: KindInt, I: n.I, Lit: n.Str}
	case "float":
		return Value{Kind: KindFloat, F: n.F, Lit: n.Str}
	case "str":
		return rt.evalStringLiteral(n)
	case "bool":
		return BoolValue(n.Str == "true")
	case "null":
		return NullValue()
	case "inf":
		if strings.HasPrefix(n.Str, "-") {
			return FloatValue(math.Inf(-1))
		}
		return FloatValue(math.Inf(1))
	case "nan":
		return FloatValue(math.NaN())
	case "const":
		if n.Str == "M_PI" {
			return FloatValue(math.Pi)
		}
		return FloatValue(math.E)
	case "field":
		if isCaptureName(n.Name) {
			return rt.captureValue(n.Name)
		}
		if v, ok := rt.rec.Get(n.Name); ok {
			return v
		}
		return absentValue()
	case "field-braced":
		if v, ok := rt.rec.Get(n.Name); ok {
			return v
		}
		return absentValue()
	case "srec":
		return MapValue(rt.rec)
	case "fieldidx":
		idx := rt.eval(n.Left)
		return rt.recordIndex(idx, false)
	case "fieldnameidx":
		idx := rt.eval(n.Left)
		return rt.recordIndex(idx, true)
	case "fieldpairidx":
		idx := rt.eval(n.Left)
		v := rt.recordIndex(idx, false)
		nm := rt.recordIndex(idx, true)
		m := NewMap()
		m.Set(nm.String(), v)
		return MapValue(m)
	case "oos":
		if v, ok := rt.oos.Get(n.Name); ok {
			return v
		}
		return absentValue()
	case "oosidx":
		idx := rt.eval(n.Left)
		k := strVal(idx)
		if v, ok := rt.oos.Get(k); ok {
			return v
		}
		return absentValue()
	case "oosnameidx":
		idx := rt.eval(n.Left)
		return StringValue(strVal(idx))
	case "oospairidx":
		idx := rt.eval(n.Left)
		k := strVal(idx)
		v, _ := rt.oos.Get(k)
		m := NewMap()
		m.Set(k, v)
		return MapValue(m)
	case "oosvar":
		if v, ok := rt.oos.Get(n.Name); ok {
			return v
		}
		return absentValue()
	case "ctx":
		return rt.ctxValue(n.Str)
	case "env":
		idx := rt.eval(n.Left)
		if idx != nil {
			k := strVal(idx)
			if k == "*" {
				m := NewMap()
				for _, kv := range os.Environ() {
					i := strings.Index(kv, "=")
					if i > 0 {
						m.Set(kv[:i], StringValue(kv[i+1:]))
					}
				}
				return MapValue(m)
			}
			return StringValue(os.Getenv(k))
		}
		return StringValue("")
	case "envcall":
		return StringValue("")
	case "index":
		v := rt.eval(n.Left)
		idx := rt.eval(n.Right)
		if isAbsent(v) {
			return absentValue()
		}
		if isError(v) {
			return errorValue()
		}
		return rt.indexValue(v, idx)
	case "arraylit":
		a := []Value{}
		for _, e := range n.List {
			v := rt.eval(e)
			if isError(v) {
				return errorValue()
			}
			if isAbsent(v) {
				continue
			}
			a = append(a, v)
		}
		return Value{Kind: KindArray, A: a}
	case "maplit":
		m := NewMap()
		for _, e := range n.List {
			v := rt.eval(e)
			if v.Kind != KindMap || v.M.Len() != 1 {
				return errorValue()
			}
			for _, k := range v.M.Keys() {
				val, _ := v.M.Get(k)
				if isError(val) {
					return errorValue()
				}
				m.Set(k, val)
			}
		}
		return MapValue(m)
	case "funcdef":
		rt.funcs[n.Name] = n
		return absentValue()
	case "subrdef":
		rt.subrs[n.Name] = n
		return absentValue()
	case "call":
		if f, ok := rt.funcs[n.Name]; ok {
			args := rt.evalArgs(n.List)
			return rt.callUserFunc(f, args)
		}
		args := rt.evalArgs(n.List)
		if fn, ok := dslFuncs[n.Name]; ok {
			return fn(rt, args)
		}
		if s, ok := rt.subrs[n.Name]; ok {
			rt.callUserFunc(s, args)
			return absentValue()
		}
		return errorValue()
	case "ident":
		if v, ok := rt.lookupLocal(n.Str); ok {
			return v
		}
		return absentValue()
	case "unop":
		v := rt.eval(n.Left)
		switch n.Str {
		case "-":
			if v.Kind == KindInt {
				return IntValue(-v.I)
			}
			if v.IsNumber() {
				return FloatValue(-toFloat(v))
			}
			return errorValue()
		case "+":
			if v.IsNumber() {
				return v
			}
			return errorValue()
		case "!":
			return BoolValue(!truthy(v))
		case "~":
			if v.Kind == KindInt {
				return IntValue(^v.I)
			}
			return errorValue()
		}
		return errorValue()
	case "binop":
		switch n.Str {
		case "&&":
			l := rt.eval(n.Left)
			if !truthy(l) {
				return BoolValue(false)
			}
			r := rt.eval(n.Right)
			return BoolValue(truthy(r))
		case "||":
			l := rt.eval(n.Left)
			if truthy(l) {
				return BoolValue(true)
			}
			r := rt.eval(n.Right)
			return BoolValue(truthy(r))
		case "^^":
			l := rt.eval(n.Left)
			r := rt.eval(n.Right)
			return BoolValue(truthy(l) != truthy(r))
		case "??":
			l := rt.eval(n.Left)
			if isAbsent(l) || isError(l) {
				return rt.eval(n.Right)
			}
			return l
		case "???":
			l := rt.eval(n.Left)
			if isAbsent(l) || isError(l) || (l.Kind == KindString && l.S == "") || l.Kind == KindNull {
				return rt.eval(n.Right)
			}
			return l
		case "=~":
			l := rt.eval(n.Left)
			r := rt.eval(n.Right)
			if l.Kind != KindString || r.Kind != KindString {
				return errorValue()
			}
			re, err := regexCompileSpec(r.S, n.Re)
			if err != nil {
				return errorValue()
			}
			m := re.FindStringSubmatch(l.S)
			if m == nil {
				return BoolValue(false)
			}
			rt.captures = m
			return BoolValue(true)
		case "!=~":
			l := rt.eval(n.Left)
			r := rt.eval(n.Right)
			if l.Kind != KindString || r.Kind != KindString {
				return errorValue()
			}
			re, err := regexCompileSpec(r.S, n.Re)
			if err != nil {
				return errorValue()
			}
			m := re.FindStringSubmatch(l.S)
			if m != nil {
				rt.captures = m
			}
			return BoolValue(m == nil)
		default:
			l := rt.eval(n.Left)
			r := rt.eval(n.Right)
			if n.Str == "." {
				if isError(l) || isError(r) || isAbsent(l) || isAbsent(r) {
					return errorValue()
				}
				return StringValue(strVal(l) + strVal(r))
			}
			if isBoolOp(n.Str) {
				return rt.compare(n.Str, l, r)
			}
			return rt.arith(n.Str, l, r)
		}
	case "funcval":
		return Value{Kind: KindFunc, N: n}
	}
	return errorValue()
}

func isBoolOp(op string) bool {
	switch op {
	case "==", "!=", "<", "<=", ">", ">=", "<=>":
		return true
	}
	return false
}

func isCaptureName(s string) bool {
	if len(s) == 1 && s[0] >= '1' && s[0] <= '9' {
		return true
	}
	return false
}

func (rt *RT) captureValue(name string) Value {
	i := int(name[0] - '1')
	if rt.captures == nil || i >= len(rt.captures) {
		return StringValue("")
	}
	return StringValue(rt.captures[i])
}

func (rt *RT) evalStringLiteral(n *Node) Value {
	s := n.Str
	if rt.captures != nil && strings.Contains(s, "\\") {
		var b strings.Builder
		for i := 0; i < len(s); i++ {
			if s[i] == '\\' && i+1 < len(s) && s[i+1] >= '1' && s[i+1] <= '9' {
				idx := int(s[i+1] - '1')
				if idx < len(rt.captures) {
					b.WriteString(rt.captures[idx])
				}
				i++
				continue
			}
			b.WriteByte(s[i])
		}
		s = b.String()
	}
	return StringValue(s)
}

func (rt *RT) evalArgs(list []*Node) []Value {
	args := []Value{}
	for _, e := range list {
		if e.Kind == "funcdef" || e.Kind == "funcexpr" {
			args = append(args, Value{Kind: KindFunc, N: e})
			continue
		}
		v := rt.eval(e)
		args = append(args, v)
	}
	return args
}

func (rt *RT) recordIndex(idx Value, wantName bool) Value {
	if idx.Kind == KindInt || (idx.Kind == KindFloat && idx.F == float64(int64(idx.F))) {
		i := int(toInt(idx))
		keys := rt.rec.Keys()
		if i < 1 || i > len(keys) {
			return absentValue()
		}
		if wantName {
			return StringValue(keys[i-1])
		}
		v, _ := rt.rec.Get(keys[i-1])
		return v
	}
	k := strVal(idx)
	if wantName {
		return StringValue(k)
	}
	if v, ok := rt.rec.Get(k); ok {
		return v
	}
	return absentValue()
}

func (rt *RT) ctxValue(name string) Value {
	switch name {
	case "NF":
		return IntValue(int64(rt.rec.Len()))
	case "NR":
		return IntValue(rt.ctx.NR)
	case "FNR":
		return IntValue(rt.ctx.FNR)
	case "FILENAME":
		return StringValue(rt.ctx.Filename)
	case "FILENUM":
		return IntValue(rt.ctx.Filenum)
	case "IPS":
		return StringValue(rt.ctx.opt.IPS)
	case "IFS":
		return StringValue(rt.ctx.opt.IFS)
	case "IRS":
		return StringValue(rt.ctx.opt.IRS)
	case "OPS":
		return StringValue(rt.ctx.opt.OPS)
	case "OFS":
		return StringValue(rt.ctx.opt.OFS)
	case "ORS":
		return StringValue(rt.ctx.opt.ORS)
	case "FLATSEP":
		return StringValue(rt.ctx.opt.FlatSep)
	}
	return absentValue()
}

func (rt *RT) callUserFunc(f *Node, args []Value) Value {
	rt.pushScope()
	defer rt.popScope()
	params := []string{}
	for _, p := range f.List {
		if p.Kind == "ident" {
			params = append(params, p.Str)
		} else if p.Kind == "vardecl" {
			params = append(params, p.Name)
		}
	}
	for i, p := range params {
		if i < len(args) {
			rt.locals[len(rt.locals)-1][p] = args[i]
		} else {
			rt.locals[len(rt.locals)-1][p] = absentValue()
		}
	}
	rt.ret = false
	rt.evalBody(f.Body)
	rt.ret = false
	return rt.retVal
}

// evalBody runs a list of statements.
func (rt *RT) evalBody(body []*Node) {
	for _, st := range body {
		if rt.brk || rt.cont || rt.ret {
			return
		}
		rt.evalStmt(st)
	}
}

// ---------- statement evaluation ----------

func (rt *RT) evalStmt(n *Node) {
	switch n.Kind {
	case "exprstmt":
		v := rt.eval(n.Left)
		if isError(v) {
			return
		}
		rt.lastValue = v
		rt.filterVal = v
		rt.hasFilter = true
	case "blockstmt":
		rt.pushScope()
		defer rt.popScope()
		rt.evalBody(n.Body)
	case "begin":
		// handled at verb level
		rt.evalBody(n.Body)
	case "end":
		rt.evalBody(n.Body)
	case "assign":
		rt.evalAssign(n)
	case "vardecl":
		var v Value
		if n.Left != nil {
			v = rt.eval(n.Left)
		} else {
			v = absentValue()
		}
		if isError(v) {
			return
		}
		if n.Str != "" && !isAbsent(v) {
			v = coerceType(v, n.Str)
		}
		rt.locals[len(rt.locals)-1][n.Name] = v
	case "if":
		c := rt.eval(n.Left)
		if truthy(c) {
			rt.pushScope()
			rt.evalBody(n.Body)
			rt.popScope()
		} else if n.Right != nil {
			if n.Right.Kind == "if" || n.Right.Kind == "blockstmt" {
				rt.evalStmt(n.Right)
			} else {
				rt.evalBody(n.Right.Body)
			}
		}
	case "while":
		for {
			c := rt.eval(n.Left)
			if !truthy(c) {
				break
			}
			rt.pushScope()
			rt.evalBody(n.Body)
			rt.popScope()
			if rt.brk {
				rt.brk = false
				break
			}
			rt.cont = false
		}
	case "dowhile":
		for {
			rt.pushScope()
			rt.evalBody(n.Body)
			rt.popScope()
			if rt.brk {
				rt.brk = false
				break
			}
			rt.cont = false
			c := rt.eval(n.Left)
			if !truthy(c) {
				break
			}
		}
	case "forc":
		rt.pushScope()
		defer rt.popScope()
		rt.evalStmt(n.List[0])
		for {
			c := rt.eval(n.List[1])
			if !truthy(c) {
				break
			}
			rt.evalBody(n.Body)
			if rt.brk {
				rt.brk = false
				break
			}
			rt.cont = false
			rt.evalStmt(n.List[2])
		}
	case "forin":
		cont := rt.eval(n.Left)
		rt.pushScope()
		defer rt.popScope()
		switch cont.Kind {
		case KindArray:
			for _, e := range cont.A {
				rt.locals[len(rt.locals)-1][n.Str] = e
				rt.evalBody(n.Body)
				if rt.brk {
					rt.brk = false
					break
				}
				rt.cont = false
			}
		case KindMap:
			for _, k := range cont.M.Keys() {
				val, _ := cont.M.Get(k)
				rt.locals[len(rt.locals)-1][n.Str] = StringValue(k)
				rt.evalBody(n.Body)
				if rt.brk {
					rt.brk = false
					break
				}
				rt.cont = false
			}
		}
	case "forkv":
		cont := rt.eval(n.Left)
		rt.pushScope()
		defer rt.popScope()
		switch cont.Kind {
		case KindArray:
			for i, e := range cont.A {
				rt.locals[len(rt.locals)-1][n.Str] = IntValue(int64(i + 1))
				rt.locals[len(rt.locals)-1][n.Name] = e
				rt.evalBody(n.Body)
				if rt.brk {
					rt.brk = false
					break
				}
				rt.cont = false
			}
		case KindMap:
			for _, k := range cont.M.Keys() {
				val, _ := cont.M.Get(k)
				rt.locals[len(rt.locals)-1][n.Str] = StringValue(k)
				rt.locals[len(rt.locals)-1][n.Name] = val
				rt.evalBody(n.Body)
				if rt.brk {
					rt.brk = false
					break
				}
				rt.cont = false
			}
		}
	case "break":
		rt.brk = true
	case "continue":
		rt.cont = true
	case "return":
		if n.Left != nil {
			rt.retVal = rt.eval(n.Left)
		} else {
			rt.retVal = absentValue()
		}
		rt.ret = true
	case "call":
		if s, ok := rt.subrs[n.Name]; ok {
			args := rt.evalArgs(n.List)
			rt.callUserFunc(s, args)
		}
	case "funcdef":
		rt.funcs[n.Name] = n
	case "subrdef":
		rt.subrs[n.Name] = n
	case "emit":
		rt.doEmit(n, "emit")
	case "emitf":
		rt.doEmit(n, "emitf")
	case "emitp":
		rt.doEmit(n, "emitp")
	case "emit1":
		v := rt.eval(n.Left)
		rt.emitValue(v, nil, "emit", n.Third)
	case "print":
		rt.doPrint(n.List, "\n", n.Third, false)
	case "printn":
		rt.doPrint(n.List, "", n.Third, false)
	case "eprint":
		rt.doPrint(n.List, "\n", nil, true)
	case "eprintn":
		rt.doPrint(n.List, "", nil, true)
	case "dump":
		var v Value
		if n.Left != nil {
			v = rt.eval(n.Left)
		} else {
			v = MapValue(rt.oos)
		}
		rt.doPrint([]Value{v}, "\n", n.Third, false)
	case "edump":
		var v Value
		if n.Left != nil {
			v = rt.eval(n.Left)
		} else {
			v = MapValue(rt.oos)
		}
		rt.doPrint([]Value{v}, "\n", nil, true)
	case "tee":
		rt.doTee(n)
	case "panic":
		msg := ""
		for _, e := range n.List {
			msg += strVal(rt.eval(e))
		}
		fmt.Fprintln(os.Stderr, "mlr: "+msg)
		os.Exit(1)
	case "stdout":
	case "stderr":
	case "env":
	case "all":
	case "unset":
		rt.doUnset(n)
	}
}

func coerceType(v Value, typ string) Value {
	switch typ {
	case "int":
		if v.Kind == KindInt {
			return v
		}
		if v.IsNumber() {
			return IntValue(int64(toFloat(v)))
		}
		if v.Kind == KindString {
			if i, err := strconv.ParseInt(v.S, 10, 64); err == nil {
				return IntValue(i)
			}
		}
		return errorValue()
	case "float":
		if v.IsNumber() || v.Kind == KindString {
			if f, err := strconv.ParseFloat(strVal(v), 64); err == nil {
				return FloatValue(f)
			}
		}
		return errorValue()
	case "bool", "boolean":
		return BoolValue(truthy(v))
	case "str", "string":
		return StringValue(strVal(v))
	case "num", "number":
		if v.IsNumber() {
			return v
		}
		if v.Kind == KindString {
			if x, ok := parseNumber(v.S); ok {
				return Value{Kind: x.Kind, I: x.I, F: x.F}
			}
		}
		return errorValue()
	case "map":
		if v.Kind == KindMap {
			return v
		}
		return errorValue()
	}
	return v
}

func (rt *RT) evalAssign(n *Node) {
	lhs := n.Left
	op := n.Str
	// $* = expr
	if lhs.Kind == "srec" {
		v := rt.eval(n.Right)
		if op != "=" {
			cur := MapValue(rt.rec)
			v = rt.arithAssign(op, cur, v)
		}
		if isError(v) {
			return
		}
		if v.Kind == KindMap {
			rt.rec = v.M.Clone()
		}
		return
	}
	if lhs.Kind == "field" || lhs.Kind == "field-braced" {
		v := rt.eval(n.Right)
		if op != "=" {
			var cur Value
			if existing, ok := rt.rec.Get(lhs.Name); ok {
				cur = existing
			} else {
				cur = absentValue()
			}
			v = rt.arithAssign(op, cur, v)
		}
		if isError(v) {
			return
		}
		if isAbsent(v) {
			rt.rec.Unset(lhs.Name)
			return
		}
		rt.rec.Set(lhs.Name, v)
		return
	}
	if lhs.Kind == "oos" || lhs.Kind == "oos-braced" {
		v := rt.eval(n.Right)
		if op != "=" {
			var cur Value
			if existing, ok := rt.oos.Get(lhs.Name); ok {
				cur = existing
			} else {
				cur = absentValue()
			}
			v = rt.arithAssign(op, cur, v)
		}
		if isError(v) {
			return
		}
		if isAbsent(v) {
			rt.oos.Unset(lhs.Name)
			return
		}
		rt.oos.Set(lhs.Name, v)
		return
	}
	if lhs.Kind == "ident" {
		v := rt.eval(n.Right)
		if op != "=" {
			cur, ok := rt.lookupLocal(lhs.Str)
			if !ok {
				cur = absentValue()
			}
			v = rt.arithAssign(op, cur, v)
		}
		if isError(v) {
			return
		}
		if isAbsent(v) {
			return
		}
		rt.setLocal(lhs.Str, v)
		return
	}
	// indexed assignment
	if lhs.Kind == "index" {
		container := lhs.Left
		idx := rt.eval(lhs.Right)
		var cur Value
		switch container.Kind {
		case "field", "field-braced":
			if existing, ok := rt.rec.Get(container.Name); ok {
				cur = existing
			} else {
				cur = absentValue()
			}
		case "oos":
			if existing, ok := rt.oos.Get(container.Name); ok {
				cur = existing
			} else {
				cur = absentValue()
			}
		case "srec":
			cur = MapValue(rt.rec)
		case "index":
			cur = rt.eval(container)
		default:
			cur = rt.eval(container)
		}
		v := rt.eval(n.Right)
		if op != "=" {
			old := absentValue()
			if cur.Kind == KindMap {
				if e, ok := cur.M.Get(strVal(idx)); ok {
					old = e
				}
			} else if cur.Kind == KindArray {
				i := int(toInt(idx))
				if i >= 1 && i <= len(cur.A) {
					old = cur.A[i-1]
				}
			}
			v = rt.arithAssign(op, old, v)
		}
		if isError(v) {
			return
		}
		newv := rt.setIndex(cur, idx, v)
		if isError(newv) {
			return
		}
		switch container.Kind {
		case "field", "field-braced":
			rt.rec.Set(container.Name, newv)
		case "oos":
			rt.oos.Set(container.Name, newv)
		case "srec":
			if newv.Kind == KindMap {
				rt.rec = newv.M.Clone()
			}
		default:
			// nested: set into parent
			rt.assignNested(container, newv)
		}
		return
	}
}

func (rt *RT) assignNested(container *Node, val Value) {
	switch container.Kind {
	case "field", "field-braced":
		rt.rec.Set(container.Name, val)
	case "oos":
		rt.oos.Set(container.Name, val)
	case "index":
		parent := container.Left
		idx := rt.eval(container.Right)
		pv := rt.eval(parent)
		np := rt.setIndex(pv, idx, val)
		rt.assignNested(parent, np)
	}
}

func (rt *RT) arithAssign(op string, cur, v Value) Value {
	switch op {
	case "=":
		return v
	case "+=":
		return rt.arith("+", cur, v)
	case "-=":
		return rt.arith("-", cur, v)
	case "*=":
		return rt.arith("*", cur, v)
	case "/=":
		return rt.arith("/", cur, v)
	case "//=":
		return rt.arith("//", cur, v)
	case "^=":
		return rt.arith("^", cur, v)
	case "%=":
		return rt.arith("%", cur, v)
	case ".=":
		return rt.arith(".", cur, v)
	case "**=":
		return rt.arith("**", cur, v)
	case "<<=":
		return rt.arith("<<", cur, v)
	case ">>=":
		return rt.arith(">>", cur, v)
	}
	return errorValue()
}

func (rt *RT) doUnset(n *Node) {
	for _, t := range n.List {
		switch t.Kind {
		case "field", "field-braced":
			rt.rec.Unset(t.Name)
		case "oos":
			rt.oos.Unset(t.Name)
		case "srec":
			rt.rec = NewMap()
		case "index":
			container := t.Left
			idx := rt.eval(t.Right)
			switch container.Kind {
			case "field", "field-braced":
				if cur, ok := rt.rec.Get(container.Name); ok {
					nc := rt.setIndex(cur, idx, absentValue())
					if nc.Kind == KindMap {
						rt.rec.Set(container.Name, nc)
					}
				}
			case "oos":
				if cur, ok := rt.oos.Get(container.Name); ok {
					nc := rt.setIndex(cur, idx, absentValue())
					if nc.Kind == KindMap {
						rt.oos.Set(container.Name, nc)
					}
				}
			}
		}
	}
}

// emit

func (rt *RT) doEmit(n *Node, kind string) {
	if len(n.List) == 0 {
		return
	}
	target := n.List[0]
	var names []Value
	if len(n.List) > 1 {
		for _, e := range n.List[1:] {
			names = append(names, rt.eval(e))
		}
	}
	v := rt.eval(target)
	rt.emitValue(v, names, kind, n.Third)
}

func (rt *RT) emitValue(v Value, names []Value, kind string, redir *Node) {
	if isError(v) || isAbsent(v) {
		return
	}
	recs := []*Record{}
	if v.Kind != KindMap {
		name := "value"
		r := NewMap()
		r.Set(name, v)
		recs = append(recs, r)
	} else {
		if len(names) == 0 {
			for _, k := range v.M.Keys() {
				val, _ := v.M.Get(k)
				r := NewMap()
				flattenIntoRecord(r, k, val)
				recs = append(recs, r)
			}
		} else {
			keys := []string{}
			for _, nm := range names {
				keys = append(keys, strVal(nm))
			}
			rt.emitNested(v.M, keys, 0, NewMap(), &recs, kind)
		}
	}
	for _, r := range recs {
		rt.emitOut = append(rt.emitOut, r)
		if redir != nil {
			rt.writeRedirect(redir, r)
		}
	}
}

func flattenIntoRecord(r *Record, k string, v Value) {
	switch v.Kind {
	case KindMap:
		if v.M.Len() == 0 {
			r.Set(k, v)
			return
		}
		for _, kk := range v.M.Keys() {
			val, _ := v.M.Get(kk)
			sep := "."
			if rt.ctx != nil {
				sep = rt.ctx.opt.FlatSep
			}
			flattenIntoRecord(r, k+sep+kk, val)
		}
	case KindArray:
		if len(v.A) == 0 {
			r.Set(k, v)
			return
		}
		sep := "."
		if rt.ctx != nil {
			sep = rt.ctx.opt.FlatSep
		}
		for i, e := range v.A {
			flattenIntoRecord(r, fmt.Sprintf("%s%s%d", k, sep, i+1), e)
		}
	default:
		r.Set(k, v)
	}
}

func (rt *RT) emitNested(m *Map, keys []string, depth int, prefix *Record, recs *[]*Record, kind string) {
	if depth >= len(keys) {
		r := prefix.Clone()
		for _, k := range m.Keys() {
			val, _ := m.Get(k)
			if kind == "emitp" {
				flattenIntoRecord(r, k, val)
			} else {
				flattenIntoRecord(r, k, val)
			}
		}
		*recs = append(*recs, r)
		return
	}
	for _, k := range m.Keys() {
		val, _ := m.Get(k)
		np := prefix.Clone()
		np.Set(keys[depth], StringValue(k))
		if val.Kind == KindMap {
			rt.emitNested(val.M, keys, depth+1, np, recs, kind)
		} else if val.Kind == KindArray {
			for _, e := range val.A {
				if e.Kind == KindMap {
					rt.emitNested(e.M, keys, depth+1, np, recs, kind)
				} else {
					r := np.Clone()
					r.Set("value", e)
					*recs = append(*recs, r)
				}
			}
		} else {
			r := np.Clone()
			r.Set("value", val)
			*recs = append(*recs, r)
		}
	}
}

func (rt *RT) doPrint(args []Value, suffix string, redir *Node, toStderr bool) {
	var b strings.Builder
	for _, e := range args {
		b.WriteString(strVal(e))
	}
	b.WriteString(suffix)
	if toStderr {
		fmt.Fprint(os.Stderr, b.String())
		return
	}
	if redir != nil {
		rt.writeRedirectText(redir, b.String())
		return
	}
	fmt.Print(b.String())
}

func (rt *RT) writeRedirect(redir *Node, rec *Record) {
	fn := strVal(rt.eval(redir.Left))
	appendMode := redir.Str == ">>"
	f, err := openAppend(fn, appendMode)
	if err != nil {
		return
	}
	defer f.Close()
	w := NewWriter(rt.ctx.opt, f)
	w.Write(rec)
	w.WriteEnd()
}

func (rt *RT) writeRedirectText(redir *Node, text string) {
	fn := strVal(rt.eval(redir.Left))
	appendMode := redir.Str == ">>"
	f, err := openAppend(fn, appendMode)
	if err != nil {
		return
	}
	defer f.Close()
	f.WriteString(text)
}

func openAppend(fn string, appendMode bool) (*os.File, error) {
	if appendMode {
		return os.OpenFile(fn, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	}
	return os.Create(fn)
}

func (rt *RT) doTee(n *Node) {
	if len(n.List) == 0 {
		return
	}
	fn := strVal(rt.eval(n.List[0]))
	f, err := openAppend(fn, false)
	if err != nil {
		return
	}
	defer f.Close()
	w := NewWriter(rt.ctx.opt, f)
	w.Write(rt.rec)
	w.WriteEnd()
}

