func wantNum(v Value) (float64, bool) {
	if v.IsNumber() {
		return toFloat(v), true
	}
	if v.Kind == KindString {
		if f, err := strconv.ParseFloat(strings.TrimSpace(v.S), 64); err == nil {
			return f, true
		}
	}
	return 0, false
}

func wantInt(v Value) (int64, bool) {
	if v.Kind == KindInt {
		return v.I, true
	}
	if v.IsNumber() {
		return int64(toFloat(v)), true
	}
	if v.Kind == KindString {
		if i, err := strconv.ParseInt(strings.TrimSpace(v.S), 10, 64); err == nil {
			return i, true
		}
	}
	return 0, false
}

func wantStr(v Value) string { return strVal(v) }

func num1(fn func(float64) float64) dslFunc {
	return func(rt *RT, args []Value) Value {
		x, ok := wantNum(arg(args, 0))
		if !ok {
			return errorValue()
		}
		return FloatValue(fn(x))
	}
}

func buildFuncs() {
