			for _, k := range v.M.Keys() {
				val, _ := v.M.Get(k)
				a = append(a, val)
			}
			return Value{Kind: KindArray, A: a}
		case KindArray:
			return v
		}
		return errorValue()
	}
	dslFuncs["haskey"] = func(rt *RT, args []Value) Value {
		v := arg(args, 0)
		k := strVal(arg(args, 1))
		switch v.Kind {
		case KindMap:
			return BoolValue(v.M.Has(k))
		case KindArray:
			i, ok := wantInt(arg(args, 1))
			if !ok {
				return BoolValue(false)
			}
			return BoolValue(i >= 1 && i <= int64(len(v.A)))
		}
		return BoolValue(false)
	}
	dslFuncs["append"] = func(rt *RT, args []Value) Value {
		v := arg(args, 0)
		if v.Kind != KindArray {
			return errorValue()
		}
		a := append([]Value{}, v.A...)
		a = append(a, arg(args, 1))
		return Value{Kind: KindArray, A: a}
	}
	dslFuncs["concat"] = func(rt *RT, args []Value) Value {
		a := []Value{}
		for _, v := range args {
			switch v.Kind {
			case KindArray:
				a = append(a, v.A...)
			case KindMap:
				for _, k := range v.M.Keys() {
					val, _ := v.M.Get(k)
					a = append(a, val)
				}
			default:
				a = append(a, v)
			}
		}
		return Value{Kind: KindArray, A: a}
	}
