				a = append(a, v.A...)
			case KindMap:
				for _, k := range v.M.Keys() {
					val, _ := v.M.Get(k)
					a = append(a, val)
				}
			default:
				a = append(a, v)
			}
		}
		return Value{Kind: KindArray, A: a}
	}
	dslFuncs["arrayify"] = func(rt *RT, args []Value) Value {
		return arrayify(arg(args, 0))
	}
	dslFuncs["flatten"] = func(rt *RT, args []Value) Value {
