	}
	dslFuncs["unflatten"] = func(rt *RT, args []Value) Value {
		return unflattenFn(rt, args)
	}
	dslFuncs["mapdiff"] = variadicMapFn(mapDiffFn)
	dslFuncs["mapexcept"] = variadicMapFn(mapExceptFn)
	dslFuncs["mapselect"] = variadicMapFn(mapSelectFn)
	dslFuncs["mapsum"] = variadicMapFn(mapSumFn)
	dslFuncs["depth"] = func(rt *RT, args []Value) Value {
