	}
	dslFuncs["json_parse"] = func(rt *RT, args []Value) Value {
		return jsonParseFn(strVal(arg(args, 0)))
	}
	dslFuncs["json_stringify"] = func(rt *RT, args []Value) Value {
		v := arg(args, 0)
		var sb strings.Builder
		sb.WriteString("{")
		if v.Kind == KindMap {
			for i, k := range v.M.Keys() {
				val, _ := v.M.Get(k)
				if i > 0 {
					sb.WriteString(", ")
				}
				sb.WriteString(jsonQuote(k))
				sb.WriteString(": ")
				val.JSON(&sb)
			}
		} else if v.Kind == KindArray {
			for i, e := range v.A {
				if i > 0 {
					sb.WriteString(", ")
				}
				sb.WriteString(jsonQuote(strconv.Itoa(i + 1)))
				sb.WriteString(": ")
				e.JSON(&sb)
			}
		}
		sb.WriteString("}")
		return StringValue(sb.String())
	}
	// stats
	dslFuncs["count"] = statsFn(func(vals []Value) Value { return IntValue(int64(len(vals))) })
	dslFuncs["null_count"] = statsFn(func(vals []Value) Value {
		n := 0
		for _, v := range vals {
			if v.Kind == KindNull || (v.Kind == KindString && v.S == "") {
				n++
			}
		}
		return IntValue(int64(n))
