	dslFuncs["sum3"] = statsFn(numericAgg(0, func(acc, x float64) float64 { return acc + x*x*x }))
	dslFuncs["sum4"] = statsFn(numericAgg(0, func(acc, x float64) float64 { return acc + x*x*x*x }))
	dslFuncs["mean"] = statsFn(meanFn)
	dslFuncs["variance"] = statsFn(varFn)
	dslFuncs["var"] = statsFn(varFn)
