		v := varFn(vals)
		if v.Kind != KindFloat && v.Kind != KindInt {
			return v
		}
		return FloatValue(math.Sqrt(toFloat(v)))
	})
	dslFuncs["stat"] = statsFn(varFn)
	dslFuncs["skewness"] = statsFn(skewFn)
	dslFuncs["kurtosis"] = statsFn(kurtFn)
	dslFuncs["meaneb"] = statsFn(meanEbFn)
