	dslFuncs["percentile"] = func(rt *RT, args []Value) Value {
		vals := valueList(arg(args, 0))
		nd, _ := wantNum(arg(args, 1))
		return percentileOf(vals, nd, false)
	}
	dslFuncs["percentiles"] = func(rt *RT, args []Value) Value {
		vals := valueList(arg(args, 0))
		spec := arg(args, 1)
		m := NewMap()
		if spec.Kind == KindArray {
			for _, e := range spec.A {
				nd, _ := wantNum(e)
				key := "p" + numFmt(nd)
				m.Set(key, percentileOf(vals, nd, false))
			}
		} else {
			for _, k := range spec.M.Keys() {
				val, _ := spec.M.Get(k)
				nd, _ := wantNum(val)
				m.Set(k, percentileOf(vals, nd, false))
			}
		}
		return MapValue(m)
	}
	dslFuncs["minlen"] = statsFn(func(vals []Value) Value {
		best := -1
		for _, v := range vals {
			l := len([]rune(strVal(v)))
			if best < 0 || l < best {
				best = l
			}
		}
		if best < 0 {
			return errorValue()
		}
		return IntValue(int64(best))
	})
	dslFuncs["maxlen"] = statsFn(func(vals []Value) Value {
		best := -1
		for _, v := range vals {
			l := len([]rune(strVal(v)))
			if l > best {
				best = l
			}
		}
		if best < 0 {
			return errorValue()
		}
		return IntValue(int64(best))
	})
	dslFuncs["sort_collection"] = func(rt *RT, args []Value) Value {
		return sortCollection(arg(args, 0), arg(args, 1))
	}
	dslFuncs["sort"] = func(rt *RT, args []Value) Value {
		v := arg(args, 0)
		asc := true
		if len(args) > 1 {
			asc = truthy(arg(args, 1))
		}
		return sortCollection(v, BoolValue(asc))
	}
	// system
	dslFuncs["version"] = func(rt *RT, args []Value) Value {
		return StringValue("6.16.0")
	}
	dslFuncs["hostname"] = func(rt *RT, args []Value) Value {
		h, err := os.Hostname()
		if err != nil {
