		}
		return StringValue(h)
	}
	dslFuncs["system"] = func(rt *RT, args []Value) Value {
		cmd := strVal(arg(args, 0))
		out, err := exec.Command("sh", "-c", cmd).Output()
		if err != nil {
			return errorValue()
		}
		s := string(out)
		s = strings.TrimSuffix(s, "\n")
		return StringValue(s)
	}
	dslFuncs["os"] = func(rt *RT, args []Value) Value {
		return StringValue("linux")
	}
	dslFuncs["stat"] = func(rt *RT, args []Value) Value {
		fn := strVal(arg(args, 0))
		st, err := os.Stat(fn)
		if err != nil {
			return errorValue()
		}
		m := NewMap()
		m.Set("size", IntValue(st.Size()))
		m.Set("mode", StringValue(st.Mode().String()))
		m.Set("mtime", FloatValue(float64(st.ModTime().Unix())))
		return MapValue(m)
	}
	dslFuncs["exec"] = func(rt *RT, args []Value) Value {
		cmd := strVal(arg(args, 0))
		cmdArgs := []string{}
		if len(args) > 1 && arg(args, 1).Kind == KindArray {
			for _, e := range arg(args, 1).A {
				cmdArgs = append(cmdArgs, strVal(e))
			}
		}
		out, err := exec.Command(cmd, cmdArgs...).Output()
		if err != nil {
			return errorValue()
		}
		s := string(out)
		s = strings.TrimSuffix(s, "\n")
		return StringValue(s)
	}
	// higher-order functions
	dslFuncs["any"] = hofAny
	dslFuncs["every"] = hofEvery
	dslFuncs["apply"] = hofApply
	dslFuncs["fold"] = hofFold
	dslFuncs["reduce"] = hofFold
	dslFuncs["select"] = hofSelect
	// time
	buildTimeFuncs()
}

