package main

import (
	"crypto/md5"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/hex"
	"fmt"
	"math"
	"os"
	"os/exec"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

type dslFunc func(rt *RT, args []Value) Value

var dslFuncs map[string]dslFunc

func init() {
	dslFuncs = map[string]dslFunc{}
	reg := func(name string, n int, fn dslFunc) { dslFuncs[name] = fn }
	_ = reg
	buildFuncs()
}

func arg(args []Value, i int) Value {
	if i < len(args) {
		return args[i]
	}
	return absentValue()
}

func wantNum(v Value) (float64, bool) {
	if v.IsNumber() {
		return toFloat(v), true
	}
	if v.Kind == KindString {
		if f, err := strconv.ParseFloat(strings.TrimSpace(v.S), 64); err == nil {
			return f, true
		}
	}
	return 0, false
}

func wantInt(v Value) (int64, bool) {
	if v.Kind == KindInt {
		return v.I, true
	}
	if v.IsNumber() {
		return int64(toFloat(v)), true
	}
	if v.Kind == KindString {
		if i, err := strconv.ParseInt(strings.TrimSpace(v.S), 10, 64); err == nil {
			return i, true
		}
	}
	return 0, false
}

func wantStr(v Value) string { return strVal(v) }

func num1(fn func(float64) float64) dslFunc {
	return func(rt *RT, args []Value) Value {
		x, ok := wantNum(arg(args, 0))
		if !ok {
			return errorValue()
		}
		return FloatValue(fn(x))
	}
}

func buildFuncs() {
	// math
	m1 := map[string]dslFunc{
		"abs": func(rt *RT, args []Value) Value {
			v := arg(args, 0)
			if v.Kind == KindInt {
				return IntValue(absInt(v.I))
			}
			x, ok := wantNum(v)
			if !ok {
				return errorValue()
			}
			return FloatValue(math.Abs(x))
		},
		"acos": num1(math.Acos), "acosh": num1(math.Acosh), "asin": num1(math.Asin),
		"asinh": num1(math.Asinh), "atan": num1(math.Atan), "atanh": num1(math.Atanh),
		"cbrt": num1(math.Cbrt), "ceil": num1(math.Ceil), "cos": num1(math.Cos),
		"cosh": num1(math.Cosh), "erf": num1(math.Erf), "erfc": num1(math.Erfc),
		"exp": num1(math.Exp), "expm1": num1(math.Expm1), "floor": num1(math.Floor),
		"log": num1(math.Log), "log10": num1(math.Log10), "log1p": num1(math.Log1p),
		"sin": num1(math.Sin), "sinh": num1(math.Sinh), "sqrt": num1(math.Sqrt),
		"tan": num1(math.Tan), "tanh": num1(math.Tanh),
		"qnorm": num1(func(x float64) float64 { return invNorm(x) }),
		"invqnorm": num1(func(x float64) float64 { return invNorm(x) }),
		"sgn": num1(func(x float64) float64 {
			if x > 0 {
				return 1
			}
			if x < 0 {
				return -1
			}
			return 0
		}),
		"round": func(rt *RT, args []Value) Value {
			v := arg(args, 0)
			x, ok := wantNum(v)
			if !ok {
				return errorValue()
			}
			if v.Kind == KindInt {
				return v
			}
			return IntValue(int64(math.Round(x)))
		},
		"roundm": num1(func(x float64) float64 {
			if x < 0 {
				return math.Ceil(x)
			}
			return math.Floor(x)
