		"logifit": func(rt *RT, args []Value) Value {
			x, ok := wantNum(arg(args, 0))
			if !ok {
				return errorValue()
			}
			m, _ := wantNum(arg(args, 1))
			b, _ := wantNum(arg(args, 2))
			return FloatValue(1.0 / (1.0 + math.Exp(-(m*x + b))))
		},
		"atan2": func(rt *RT, args []Value) Value {
			x, ok1 := wantNum(arg(args, 0))
			y, ok2 := wantNum(arg(args, 1))
			if !ok1 || !ok2 {
				return errorValue()
			}
			return FloatValue(math.Atan2(x, y))
		},
