	}
	return r
}

func maxMin(args []Value, wantMax bool) Value {
	if len(args) == 0 {
		return errorValue()
	}
	var best Value
	first := true
	for _, v := range args {
		if isAbsent(v) || isError(v) {
			continue
		}
		if first {
			best = v
			first = false
			continue
		}
		c, ok := compareValues(v, best)
		if !ok {
			continue
		}
		if (wantMax && c > 0) || (!wantMax && c < 0) {
			best = v
		}
	}
	if first {
		return errorValue()
	}
	return best
}

