func collapseWS(s string) string {
	var b strings.Builder
	inSpace := false
	for _, r := range s {
		if isSpaceRune(r) {
			if !inSpace {
				b.WriteRune(' ')
				inSpace = true
			}
			continue
		}
		b.WriteRune(r)
		inSpace = false
	}
	return b.String()
}

func isSpaceRune(r rune) bool {
	return r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\v' || r == '\f'
}

func substrFn(rt *RT, args []Value, base int) Value {
	s := []rune(strVal(arg(args, 0)))
	m, ok1 := wantInt(arg(args, 1))
	n, ok2 := wantInt(arg(args, 2))
	if !ok1 || !ok2 {
		return errorValue()
	}
	l := int64(len(s))
	if m < 0 {
		m += l + int64(base)
	}
	if n < 0 {
		n += l + int64(base)
	}
	m += int64(base)
	n += int64(base) + 1
	if m < 0 {
		m = 0
	}
	if n > l {
		n = l
	}
	if m > n || m > l {
		return StringValue("")
	}
	return StringValue(string(s[m:n]))
}

func subFn(rt *RT, args []Value, global, useRegex bool) Value {
	s := strVal(arg(args, 0))
	old := strVal(arg(args, 1))
	nw := strVal(arg(args, 2))
	if !useRegex {
		if global {
			return StringValue(strings.ReplaceAll(s, old, nw))
		}
		return StringValue(strings.Replace(s, old, nw, 1))
	}
	re, err := regexCompileSpec(old, false)
	if err != nil {
		return errorValue()
	}
	if global {
		out := re.ReplaceAllStringFunc(s, func(m string) string {
			groups := re.FindStringSubmatch(m)
			return expandCaptures(nw, groups)
		})
		return StringValue(out)
	}
	loc := re.FindStringSubmatchIndex(s)
	if loc == nil {
		return StringValue(s)
	}
	groups := re.FindStringSubmatch(s)
	var b strings.Builder
	b.WriteString(s[:loc[0]])
	b.WriteString(expandCaptures(nw, groups))
	b.WriteString(s[loc[1]:])
	return StringValue(b.String())
}

func expandCaptures(tmpl string, groups []string) string {
	var b strings.Builder
	for i := 0; i < len(tmpl); i++ {
		if tmpl[i] == '\\' && i+1 < len(tmpl) && tmpl[i+1] >= '0' && tmpl[i+1] <= '9' {
			n := int(tmpl[i+1] - '0')
			if n < len(groups) {
				b.WriteString(groups[n])
			}
			i++
			continue
		}
		b.WriteByte(tmpl[i])
	}
	return b.String()
}

func splitKV(rt *RT, args []Value, pairMode bool, useRegex bool) Value {
	s := strVal(arg(args, 0))
	ps := strVal(arg(args, 1))
	kvs := strVal(arg(args, 2))
	parts := strings.Split(s, kvs)
	m := NewMap()
	for _, p := range parts {
		var k, v string
		if pairMode {
			i := strings.Index(p, ps)
			if i < 0 {
				k = strconv.Itoa(m.Len() + 1)
				v = p
			} else {
				k = p[:i]
				v = p[i+len(ps):]
			}
		} else {
			k = strconv.Itoa(m.Len() + 1)
			v = p
		}
		m.Set(k, StringValue(v))
	}
	return MapValue(m)
}

func unformat(rt *RT, args []Value, infer bool) Value {
	f := strVal(arg(args, 0))
	s := strVal(arg(args, 1))
	// convert Go-style format to a regex
	var re strings.Builder
	i := 0
	for i < len(f) {
		if f[i] == '%' {
			if i+1 >= len(f) {
				return errorValue()
			}
			j := i + 1
			for j < len(f) && !strings.ContainsRune("diouxXeEfgGs", rune(f[j])) {
				j++
			}
			if j >= len(f) {
				return errorValue()
			}
			switch f[j] {
			case 'd', 'i', 'u', 'o', 'x', 'X':
				re.WriteString(`([-+]?[0-9]+)`)
			case 'e', 'E', 'f', 'g', 'G':
				re.WriteString(`([-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?)`)
			case 's':
				re.WriteString(`([^ ]+)`)
			default:
				return errorValue()
			}
			i = j + 1
			continue
		}
		re.WriteString(regexp.QuoteMeta(string(f[i])))
		i++
	}
	compiled, err := regexCompile(re.String(), false)
	if err != nil {
		return errorValue()
	}
	m := compiled.FindStringSubmatch(s)
	if m == nil {
		return errorValue()
	}
	a := []Value{}
	for _, g := range m[1:] {
		if infer {
			a = append(a, inferValue(g, nil))
		} else {
			a = append(a, StringValue(g))
		}
	}
	return Value{Kind: KindArray, A: a}
}

func regexCompile(body string, ci bool) (*regexpT, error) {
	return compileRegex(body)
}

func fmtNum(rt *RT, v Value, f string, keepOnError bool) Value {
	switch v.Kind {
	case KindArray:
		a := []Value{}
		for _, e := range v.A {
			r := fmtNum(rt, e, f, keepOnError)
			if isError(r) {
				return r
			}
			a = append(a, r)
		}
		return Value{Kind: KindArray, A: a}
	case KindMap:
		m := NewMap()
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			r := fmtNum(rt, val, f, keepOnError)
			if isError(r) {
				return r
			}
			m.Set(k, r)
		}
		return MapValue(m)
	}
	if !v.IsNumber() {
		if keepOnError {
			return v
		}
		return errorValue()
	}
	// percent-thousands extension
	gofmt := f
	thousands := false
	if strings.Contains(gofmt, "_") {
		gofmt = strings.ReplaceAll(gofmt, "_", "")
		thousands = true
	}
	var out string
	switch {
	case strings.Contains(gofmt, "%"):
		if v.Kind == KindInt {
			out = fmt.Sprintf(gofmt, v.I)
		} else {
			out = fmt.Sprintf(gofmt, toFloat(v))
		}
	default:
		return errorValue()
	}
	if thousands {
		out = addThousands(out)
	}
	return StringValue(out)
}

func addThousands(s string) string {
	neg := strings.HasPrefix(s, "-")
	if neg {
		s = s[1:]
	}
	i := strings.Index(s, ".")
	var intPart, fracPart string
	if i >= 0 {
		intPart, fracPart = s[:i], s[i:]
	} else {
		intPart, fracPart = s, ""
	}
	var b strings.Builder
	n := len(intPart)
	for j := 0; j < n; j++ {
		if j > 0 && (n-j)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteByte(intPart[j])
	}
	if neg {
		return "-" + b.String() + fracPart
	}
	return b.String() + fracPart
}

func valueList(v Value) []Value {
	switch v.Kind {
	case KindArray:
		return v.A
	case KindMap:
		out := []Value{}
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			out = append(out, val)
		}
		return out
	}
	return nil
}

func statsFn(fn func([]Value) Value) dslFunc {
	return func(rt *RT, args []Value) Value {
		vals := valueList(arg(args, 0))
		if vals == nil {
			return errorValue()
		}
		return fn(vals)
	}
}

func numericAgg(init float64, fn func(float64, float64) float64) func([]Value) Value {
	return func(vals []Value) Value {
		acc := init
		for _, v := range vals {
			x, ok := wantNum(v)
			if !ok {
				return errorValue()
			}
			acc = fn(acc, x)
		}
		return FloatValue(acc)
	}
}

func meanFn(vals []Value) Value {
	sum := 0.0
	n := 0
	for _, v := range vals {
		x, ok := wantNum(v)
		if !ok {
			return errorValue()
		}
		sum += x
		n++
	}
	if n == 0 {
		return errorValue()
	}
	return FloatValue(sum / float64(n))
}

func varFn(vals []Value) Value {
	m, ok := meanFn(vals)
	if !ok.IsNumber() {
		return m
	}
	mean := toFloat(m)
	s := 0.0
	n := 0
	for _, v := range vals {
		x, _ := wantNum(v)
		s += (x - mean) * (x - mean)
		n++
	}
	if n < 2 {
		return FloatValue(0)
	}
	return FloatValue(s / float64(n-1))
}

func skewFn(vals []Value) Value {
	m, ok := meanFn(vals)
	if !ok.IsNumber() {
		return m
	}
	mean := toFloat(m)
	var s2, s3 float64
	n := 0
	for _, v := range vals {
		x, _ := wantNum(v)
		d := x - mean
		s2 += d * d
		s3 += d * d * d
		n++
	}
	if s2 == 0 {
		return FloatValue(0)
	}
	sd := math.Sqrt(s2 / float64(n))
	return FloatValue((s3 / float64(n)) / (sd * sd * sd))
}

func kurtFn(vals []Value) Value {
	m, ok := meanFn(vals)
	if !ok.IsNumber() {
		return m
	}
	mean := toFloat(m)
	var s2, s4 float64
	n := 0
	for _, v := range vals {
		x, _ := wantNum(v)
		d := x - mean
		s2 += d * d
		s4 += d * d * d * d
		n++
	}
	if s2 == 0 {
		return FloatValue(0)
	}
	vv := s2 / float64(n)
	return FloatValue((s4 / float64(n)) / (vv * vv))
}

func meanEbFn(vals []Value) Value {
	v := varFn(vals)
	if !v.IsNumber() {
		return v
	}
	variance := toFloat(v)
	n := float64(len(vals))
	return FloatValue(math.Sqrt(variance/n) * 1.96)
}

func percentileOf(vals []Value, nd float64, interpolated bool) Value {
	nums := []float64{}
	for _, v := range vals {
		x, ok := wantNum(v)
		if !ok {
			return errorValue()
		}
		nums = append(nums, x)
	}
	if len(nums) == 0 {
		return errorValue()
	}
	sortFloats(nums)
	if interpolated {
		idx := nd / 100.0 * float64(len(nums)-1)
		lo := math.Floor(idx)
		hi := math.Ceil(idx)
		if lo == hi {
			return FloatValue(nums[int(lo)])
		}
		return FloatValue(nums[int(lo)] + (idx-lo)*(nums[int(hi)]-nums[int(lo)]))
	}
	idx := int(math.Ceil(nd / 100.0 * float64(len(nums))))
	if idx < 1 {
		idx = 1
	}
	if idx > len(nums) {
		idx = len(nums)
	}
	return FloatValue(nums[idx-1])
}

func sortFloats(a []float64) {
	for i := 1; i < len(a); i++ {
		for j := i; j > 0 && a[j] < a[j-1]; j-- {
			a[j], a[j-1] = a[j-1], a[j]
		}
	}
}

func numFmt(f float64) string {
	if f == float64(int64(f)) {
		return strconv.FormatInt(int64(f), 10)
	}
	return fmt.Sprintf("%g", f)
}

func modeFn(vals []Value, wantMode bool) Value {
	counts := map[string]int64{}
	order := []string{}
	lookup := map[string]Value{}
	for _, v := range vals {
		k := strVal(v)
		if _, ok := counts[k]; !ok {
			order = append(order, k)
			lookup[k] = v
		}
		counts[k]++
	}
	if len(order) == 0 {
		return errorValue()
	}
	best := order[0]
	bestc := counts[best]
	for _, k := range order {
		c := counts[k]
		if wantMode && c > bestc {
			best, bestc = k, c
		}
		if !wantMode && c < bestc {
			best, bestc = k, c
		}
	}
	return lookup[best]
}

func hashFn(fn func([]byte) string) dslFunc {
	return func(rt *RT, args []Value) Value {
		return StringValue(fn([]byte(strVal(arg(args, 0)))))
	}
}

func depthOf(v Value) int {
	switch v.Kind {
	case KindMap:
		max := 0
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			d := depthOf(val)
			if d > max {
				max = d
			}
		}
		return max + 1
	case KindArray:
		max := 0
		for _, e := range v.A {
			d := depthOf(e)
			if d > max {
				max = d
			}
		}
		return max + 1
	}
	return 0
}

func leafCount(v Value) int {
	switch v.Kind {
	case KindMap:
		n := 0
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			n += leafCount(val)
		}
		return n
	case KindArray:
		n := 0
		for _, e := range v.A {
			n += leafCount(e)
		}
		return n
	}
	return 1
}

func arrayify(v Value) Value {
	switch v.Kind {
	case KindMap:
		keys := v.M.Keys()
		consecutive := len(keys) > 0
		for i, k := range keys {
			if k != strconv.Itoa(i+1) {
				consecutive = false
				break
			}
		}
		m := NewMap()
		for _, k := range keys {
			val, _ := v.M.Get(k)
			m.Set(k, arrayify(val))
		}
		if consecutive {
			return Value{Kind: KindArray, A: m.Values()}
		}
		return MapValue(m)
	case KindArray:
		a := []Value{}
		for _, e := range v.A {
			a = append(a, arrayify(e))
		}
		return Value{Kind: KindArray, A: a}
	}
	return v
}

func flattenFn(rt *RT, args []Value) Value {
	var prefix string
	var sep string
	var m Value
	if len(args) == 2 {
		sep = strVal(arg(args, 1))
		m = arg(args, 0)
		prefix = ""
	} else if len(args) >= 3 {
		prefix = strVal(arg(args, 0))
		sep = strVal(arg(args, 1))
		m = arg(args, 2)
	} else {
		sep = "."
		m = arg(args, 0)
	}
	out := NewMap()
	flattenValueInto(prefix, sep, m, out)
	return MapValue(out)
}

func flattenValueInto(prefix, sep string, v Value, out *Map) {
	switch v.Kind {
	case KindMap:
		if v.M.Len() == 0 {
			out.Set(prefix, v)
			return
		}
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			np := k
			if prefix != "" {
				np = prefix + sep + k
			}
			flattenValueInto(np, sep, val, out)
		}
	case KindArray:
		if len(v.A) == 0 {
			out.Set(prefix, v)
			return
		}
		for i, e := range v.A {
			np := fmt.Sprintf("%d", i+1)
			if prefix != "" {
				np = prefix + sep + np
			}
			flattenValueInto(np, sep, e, out)
		}
	default:
		out.Set(prefix, v)
	}
}

func unflattenFn(rt *RT, args []Value) Value {
	sep := "."
	var m Value
	if len(args) >= 2 {
		sep = strVal(arg(args, 1))
		m = arg(args, 0)
	} else {
		m = arg(args, 0)
	}
	out := NewMap()
	if m.Kind != KindMap {
		return errorValue()
	}
	for _, k := range m.M.Keys() {
		val, _ := m.M.Get(k)
		parts := strings.Split(k, sep)
		cur := out
		for i, p := range parts {
			if i == len(parts)-1 {
				cur.Set(p, val)
			} else {
				if existing, ok := cur.Get(p); ok && existing.Kind == KindMap {
					cur = existing.M
				} else {
					nm := NewMap()
					cur.Set(p, MapValue(nm))
					cur = nm
				}
			}
		}
	}
	return MapValue(out)
}

func variadicMapFn(fn func(base *Map, rest []Value) Value) dslFunc {
	return func(rt *RT, args []Value) Value {
		var base *Map
		rest := []Value{}
		if len(args) > 0 {
			v := arg(args, 0)
			if v.Kind != KindMap {
				return errorValue()
			}
			base = v.M.Clone()
			rest = args[1:]
		} else {
			base = NewMap()
		}
		return fn(base, rest)
	}
}

func mapDiffFn(base *Map, rest []Value) Value {
	for _, v := range rest {
		switch v.Kind {
		case KindString:
			base.Unset(v.S)
		case KindArray:
			for _, e := range v.A {
				base.Unset(strVal(e))
			}
		default:
			base.Unset(strVal(v))
		}
	}
	return MapValue(base)
}

func mapExceptFn(base *Map, rest []Value) Value {
	for _, v := range rest {
		switch v.Kind {
		case KindString:
			base.Unset(v.S)
		case KindArray:
			for _, e := range v.A {
				base.Unset(strVal(e))
			}
		default:
			base.Unset(strVal(v))
		}
	}
	return MapValue(base)
}

func mapSelectFn(base *Map, rest []Value) Value {
	keep := map[string]bool{}
	for _, v := range rest {
		switch v.Kind {
		case KindString:
			keep[v.S] = true
		case KindArray:
			for _, e := range v.A {
				keep[strVal(e)] = true
			}
		default:
			keep[strVal(v)] = true
		}
	}
	for _, k := range base.Keys() {
		if !keep[k] {
			base.Unset(k)
		}
	}
	return MapValue(base)
}

func mapSumFn(base *Map, rest []Value) Value {
	for _, v := range rest {
		if v.Kind != KindMap {
			return errorValue()
		}
		base.SetAll(v.M)
	}
	return MapValue(base)
}

func jsonParseFn(s string) Value {
	jr := &jsonReaderLite{data: s}
	v, err := parseJSONValueLite(jr)
	if err != nil {
		return errorValue()
	}
	return v
}

func sortCollection(v Value, asc Value) Value {
	var ascending = true
	if asc.Kind != KindAbsent && asc.Kind != KindNull {
		ascending = truthy(asc)
	}
	switch v.Kind {
	case KindArray:
		a := append([]Value{}, v.A...)
		sortValues(a, ascending)
		return Value{Kind: KindArray, A: a}
	case KindMap:
		type kv2 struct {
			k string
			v Value
		}
		pairs := []kv2{}
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			pairs = append(pairs, kv2{k, val})
		}
		sort.SliceStable(pairs, func(i, j int) bool {
			c, ok := compareValues(pairs[i].v, pairs[j].v)
			if !ok {
				c = strings.Compare(pairs[i].k, pairs[j].k)
			}
			if ascending {
				return c < 0
			}
			return c > 0
		})
		m := NewMap()
		for _, p := range pairs {
			m.Set(p.k, p.v)
		}
		return MapValue(m)
	}
	return errorValue()
}

func sortValues(a []Value, ascending bool) {
	sort.SliceStable(a, func(i, j int) bool {
		c, ok := compareValues(a[i], a[j])
		if !ok {
			c = strings.Compare(strVal(a[i]), strVal(a[j]))
		}
		if ascending {
			return c < 0
		}
		return c > 0
	})
}

// higher-order functions

func callFunc(rt *RT, f Value, args []Value) Value {
	if f.Kind != KindFunc || f.N == nil {
		return errorValue()
	}
	return rt.callUserFunc(f.N, args)
}

func hofAny(rt *RT, args []Value) Value {
	return hofAll(rt, args, false)
}

func hofEvery(rt *RT, args []Value) Value {
	return hofAll(rt, args, true)
}

func hofAll(rt *RT, args []Value, wantAll bool) Value {
	v := arg(args, 0)
	f := arg(args, 1)
	if v.Kind == KindArray {
		for _, e := range v.A {
			r := callFunc(rt, f, []Value{e})
			if truthy(r) != wantAll {
				return BoolValue(!wantAll)
			}
		}
		return BoolValue(wantAll)
	}
	if v.Kind == KindMap {
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			r := callFunc(rt, f, []Value{StringValue(k), val})
			if truthy(r) != wantAll {
				return BoolValue(!wantAll)
			}
		}
		return BoolValue(wantAll)
	}
	return errorValue()
}

func hofApply(rt *RT, args []Value) Value {
	v := arg(args, 0)
	f := arg(args, 1)
	switch v.Kind {
	case KindArray:
		a := []Value{}
		for _, e := range v.A {
			a = append(a, callFunc(rt, f, []Value{e}))
		}
		return Value{Kind: KindArray, A: a}
	case KindMap:
		m := NewMap()
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			r := callFunc(rt, f, []Value{StringValue(k), val})
			if r.Kind == KindMap && r.M.Len() == 1 {
				for _, kk := range r.M.Keys() {
					nv, _ := r.M.Get(kk)
					m.Set(kk, nv)
				}
			}
		}
		return MapValue(m)
	}
	return errorValue()
}

func hofFold(rt *RT, args []Value) Value {
	v := arg(args, 0)
	f := arg(args, 1)
	acc := arg(args, 2)
	switch v.Kind {
	case KindArray:
		for _, e := range v.A {
			acc = callFunc(rt, f, []Value{acc, e})
		}
		return acc
	case KindMap:
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			accv := acc
			acck := ""
			if accv.Kind == KindMap && accv.M.Len() == 1 {
				for _, kk := range accv.M.Keys() {
					acck = kk
					nv, _ := accv.M.Get(kk)
					accv = nv
				}
			}
			r := callFunc(rt, f, []Value{StringValue(acck), accv, StringValue(k), val})
			acc = r
		}
		return acc
	}
	return errorValue()
}

func hofSelect(rt *RT, args []Value) Value {
	v := arg(args, 0)
	f := arg(args, 1)
	switch v.Kind {
	case KindArray:
		a := []Value{}
		for _, e := range v.A {
			if truthy(callFunc(rt, f, []Value{e})) {
				a = append(a, e)
			}
		}
		return Value{Kind: KindArray, A: a}
	case KindMap:
		m := NewMap()
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			if truthy(callFunc(rt, f, []Value{StringValue(k), val})) {
				m.Set(k, val)
			}
		}
		return MapValue(m)
	}
	return errorValue()
}

// time helpers

func fmtHMS(secs float64, frac bool) Value1 {
	total := int64(math.Floor(secs))
	h := total / 3600
	m := (total % 3600) / 60
	s := total % 60
	if frac {
		f := secs - float64(total)
		return Value1(fmt.Sprintf("%02d:%02d:%02d%s", h, m, s, fmtFrac(f, 6))) + ""
	}
	return Value1(fmt.Sprintf("%02d:%02d:%02d", h, m, s)) + ""
}

func fmtFrac(f float64, nd int) string {
	if f == 0 {
		return ""
	}
	return fmt.Sprintf("%.*f", nd, f)[1:]
}

func fmtDHMS(secs float64, frac bool) string {
	total := int64(math.Floor(secs))
	d := total / 86400
	rem := total % 86400
	h := rem / 3600
	m := (rem % 3600) / 60
	s := rem % 60
	if frac {
		f := secs - float64(total)
		return fmt.Sprintf("%dd%02dh%02dm%02d%s", d, h, m, s, fmtFrac(f, 6)) + "s"
	}
	return fmt.Sprintf("%dd%02dh%02dm%02ds", d, h, m, s)
}

func parseDHMS(s string, frac bool) (float64, bool) {
	re := regexp.MustCompile(`^(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:([\d.]+)s)?$`)
	m := re.FindStringSubmatch(s)
	if m == nil {
		return 0, false
	}
	var total float64
	if m[1] != "" {
		d, _ := strconv.ParseFloat(m[1], 64)
		total += d * 86400
	}
	if m[2] != "" {
		h, _ := strconv.ParseFloat(m[2], 64)
		total += h * 3600
	}
	if m[3] != "" {
		mm, _ := strconv.ParseFloat(m[3], 64)
		total += mm * 60
	}
	if m[4] != "" {
		sec, _ := strconv.ParseFloat(m[4], 64)
		total += sec
	}
	return total, true
}

func parseHMS(s string, frac bool) (float64, bool) {
	parts := strings.Split(s, ":")
	if len(parts) < 2 || len(parts) > 3 {
		return 0, false
	}
	var total float64
	for _, p := range parts {
		x, err := strconv.ParseFloat(p, 64)
		if err != nil {
			return 0, false
		}
		total = total*60 + x
	}
	return total, true
}

func parseGMTTime(s string) (time.Time, bool) {
	layouts := []string{"2006-01-02T15:04:05Z", "2006-01-02 15:04:05", "2006-01-02T15:04:05",
		"2006-01-02T15:04:05.999999999Z", "2006-01-02", "2006-01-02T15:04:05.999999999"}
	for _, l := range layouts {
		if t, err := time.Parse(l, s); err == nil {
			return t.UTC(), true
		}
	}
	return time.Time{}, false
}

func parseLocalTime(s string) (time.Time, bool) {
	layouts := []string{"2006-01-02 15:04:05", "2006-01-02T15:04:05", "2006-01-02"}
	for _, l := range layouts {
		if t, err := time.ParseInLocation(l, s, time.Local); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

func strftime(f string, t time.Time) string {
	var b strings.Builder
	i := 0
	for i < len(f) {
		if f[i] != '%' {
			b.WriteByte(f[i])
			i++
			continue
		}
		if i+1 >= len(f) {
			b.WriteByte(f[i])
			break
		}
		c := f[i+1]
		switch c {
		case 'Y':
			b.WriteString(t.Format("2006"))
		case 'y':
			b.WriteString(t.Format("06"))
		case 'm':
			b.WriteString(t.Format("01"))
		case 'd':
			b.WriteString(t.Format("02"))
		case 'H':
			b.WriteString(t.Format("15"))
		case 'M':
			b.WriteString(t.Format("04"))
		case 'S':
			b.WriteString(t.Format("05"))
		case 'j':
			b.WriteString(fmt.Sprintf("%03d", t.YearDay()))
		case 's':
			b.WriteString(fmt.Sprintf("%d", t.Unix()))
		case 'F':
			b.WriteString(t.Format("2006-01-02"))
		case 'T':
			b.WriteString(t.Format("15:04:05"))
		case '%':
			b.WriteByte('%')
		case 'b':
			b.WriteString(t.Format("Jan"))
		case 'B':
			b.WriteString(t.Format("January"))
		case 'a':
			b.WriteString(t.Format("Mon"))
		case 'A':
			b.WriteString(t.Format("Monday"))
		case 'p':
			b.WriteString(t.Format("PM"))
		case 'Z':
			b.WriteString(t.Format("MST"))
		default:
			b.WriteByte('%')
			b.WriteByte(c)
		}
		i += 2
	}
	return b.String()
}

