			}
			acc = fn(acc, x)
		}
		return FloatValue(acc)
	}
}

func meanFn(vals []Value) Value {
	sum := 0.0
	n := 0
	for _, v := range vals {
		x, ok := wantNum(v)
		if !ok {
			return errorValue()
		}
		sum += x
		n++
	}
	if n == 0 {
		return errorValue()
	}
	return FloatValue(sum / float64(n))
}

func varFn(vals []Value) Value {
	m, ok := meanFn(vals)
	if !ok.IsNumber() {
		return m
	}
	mean := toFloat(m)
	s := 0.0
	n := 0
	for _, v := range vals {
		x, _ := wantNum(v)
		s += (x - mean) * (x - mean)
		n++
	}
	if n < 2 {
		return FloatValue(0)
	}
	return FloatValue(s / float64(n-1))
}

func skewFn(vals []Value) Value {
	m, ok := meanFn(vals)
	if !ok.IsNumber() {
		return m
	}
	mean := toFloat(m)
	var s2, s3 float64
	n := 0
	for _, v := range vals {
		x, _ := wantNum(v)
		d := x - mean
		s2 += d * d
		s3 += d * d * d
		n++
	}
	if s2 == 0 {
		return FloatValue(0)
	}
	sd := math.Sqrt(s2 / float64(n))
	return FloatValue((s3 / float64(n)) / (sd * sd * sd))
}

func kurtFn(vals []Value) Value {
	m, ok := meanFn(vals)
	if !ok.IsNumber() {
		return m
	}
	mean := toFloat(m)
	var s2, s4 float64
	n := 0
	for _, v := range vals {
		x, _ := wantNum(v)
		d := x - mean
		s2 += d * d
		s4 += d * d * d * d
		n++
	}
	if s2 == 0 {
		return FloatValue(0)
	}
	vv := s2 / float64(n)
	return FloatValue((s4 / float64(n)) / (vv * vv))
}

func meanEbFn(vals []Value) Value {
	v := varFn(vals)
	if !v.IsNumber() {
		return v
	}
	variance := toFloat(v)
	n := float64(len(vals))
	return FloatValue(math.Sqrt(variance/n) * 1.96)
}

func percentileOf(vals []Value, nd float64, interpolated bool) Value {
	nums := []float64{}
	for _, v := range vals {
		x, ok := wantNum(v)
		if !ok {
			return errorValue()
		}
		nums = append(nums, x)
	}
	if len(nums) == 0 {
		return errorValue()
	}
	sortFloats(nums)
	if interpolated {
		idx := nd / 100.0 * float64(len(nums)-1)
		lo := math.Floor(idx)
		hi := math.Ceil(idx)
		if lo == hi {
			return FloatValue(nums[int(lo)])
		}
		return FloatValue(nums[int(lo)] + (idx-lo)*(nums[int(hi)]-nums[int(lo)]))
	}
	idx := int(math.Ceil(nd / 100.0 * float64(len(nums))))
	if idx < 1 {
		idx = 1
	}
	if idx > len(nums) {
		idx = len(nums)
	}
	return FloatValue(nums[idx-1])
}

func sortFloats(a []float64) {
	for i := 1; i < len(a); i++ {
		for j := i; j > 0 && a[j] < a[j-1]; j-- {
			a[j], a[j-1] = a[j-1], a[j]
		}
	}
}

func numFmt(f float64) string {
	if f == float64(int64(f)) {
		return strconv.FormatInt(int64(f), 10)
	}
	return fmt.Sprintf("%g", f)
}

func modeFn(vals []Value, wantMode bool) Value {
	counts := map[string]int64{}
	order := []string{}
	lookup := map[string]Value{}
	for _, v := range vals {
		k := strVal(v)
		if _, ok := counts[k]; !ok {
			order = append(order, k)
			lookup[k] = v
		}
		counts[k]++
	}
	if len(order) == 0 {
		return errorValue()
	}
	best := order[0]
	bestc := counts[best]
	for _, k := range order {
		c := counts[k]
		if wantMode && c > bestc {
			best, bestc = k, c
		}
		if !wantMode && c < bestc {
			best, bestc = k, c
		}
	}
	return lookup[best]
}

func hashFn(fn func([]byte) string) dslFunc {
	return func(rt *RT, args []Value) Value {
		return StringValue(fn([]byte(strVal(arg(args, 0)))))
	}
}

func depthOf(v Value) int {
	switch v.Kind {
	case KindMap:
		max := 0
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			d := depthOf(val)
			if d > max {
				max = d
			}
		}
		return max + 1
	case KindArray:
		max := 0
		for _, e := range v.A {
			d := depthOf(e)
			if d > max {
				max = d
			}
		}
		return max + 1
	}
	return 0
}

func leafCount(v Value) int {
	switch v.Kind {
	case KindMap:
		n := 0
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			n += leafCount(val)
		}
		return n
	case KindArray:
		n := 0
		for _, e := range v.A {
			n += leafCount(e)
		}
		return n
	}
	return 1
}

func arrayify(v Value) Value {
	switch v.Kind {
	case KindMap:
		keys := v.M.Keys()
		consecutive := len(keys) > 0
		for i, k := range keys {
			if k != strconv.Itoa(i+1) {
				consecutive = false
				break
			}
		}
		m := NewMap()
		for _, k := range keys {
			val, _ := v.M.Get(k)
			m.Set(k, arrayify(val))
		}
		if consecutive {
			return Value{Kind: KindArray, A: m.Values()}
		}
		return MapValue(m)
	case KindArray:
		a := []Value{}
		for _, e := range v.A {
			a = append(a, arrayify(e))
		}
		return Value{Kind: KindArray, A: a}
	}
	return v
}

func flattenFn(rt *RT, args []Value) Value {
	var prefix string
	var sep string
	var m Value
	if len(args) == 2 {
		sep = strVal(arg(args, 1))
		m = arg(args, 0)
		prefix = ""
	} else if len(args) >= 3 {
		prefix = strVal(arg(args, 0))
		sep = strVal(arg(args, 1))
		m = arg(args, 2)
	} else {
		sep = "."
		m = arg(args, 0)
	}
	out := NewMap()
	flattenValueInto(prefix, sep, m, out)
	return MapValue(out)
}

func flattenValueInto(prefix, sep string, v Value, out *Map) {
	switch v.Kind {
	case KindMap:
		if v.M.Len() == 0 {
			out.Set(prefix, v)
			return
		}
		for _, k := range v.M.Keys() {
			val, _ := v.M.Get(k)
			np := k
			if prefix != "" {
				np = prefix + sep + k
			}
			flattenValueInto(np, sep, val, out)
		}
	case KindArray:
		if len(v.A) == 0 {
			out.Set(prefix, v)
			return
		}
		for i, e := range v.A {
			np := fmt.Sprintf("%d", i+1)
			if prefix != "" {
				np = prefix + sep + np
			}
			flattenValueInto(np, sep, e, out)
		}
	default:
		out.Set(prefix, v)
	}
}

func unflattenFn(rt *RT, args []Value) Value {
	sep := "."
	var m Value
	if len(args) >= 2 {
		sep = strVal(arg(args, 1))
		m = arg(args, 0)
	} else {
		m = arg(args, 0)
	}
	out := NewMap()
	if m.Kind != KindMap {
		return errorValue()
	}
	for _, k := range m.M.Keys() {
		val, _ := m.M.Get(k)
		parts := strings.Split(k, sep)
		cur := out
		for i, p := range parts {
			if i == len(parts)-1 {
				cur.Set(p, val)
			} else {
				if existing, ok := cur.Get(p); ok && existing.Kind == KindMap {
					cur = existing.M
				} else {
					nm := NewMap()
					cur.Set(p, MapValue(nm))
					cur = nm
				}
			}
		}
	}
	return MapValue(out)
}

func variadicMapFn(fn func(base *Map, rest []Value) Value) dslFunc {
	return func(rt *RT, args []Value) Value {
