		rest := []Value{}
		if len(args) > 0 {
			v := arg(args, 0)
			if v.Kind != KindMap {
				return errorValue()
			}
			base = v.M.Clone()
			rest = args[1:]
		} else {
			base = NewMap()
		}
		return fn(base, rest)
	}
}

