func parseJSONValueLite(jr *jsonReaderLite) (Value, error) {
	jr.skipWS()
	if jr.pos >= len(jr.data) {
		return errorValue(), fmt.Errorf("eof")
	}
	c := jr.data[jr.pos]
	switch c {
	case '{':
		jr.pos++
		m := NewMap()
