			}
			if jr.data[jr.pos] == ',' {
				jr.pos++
				continue
			}
			k, err := parseJSONStrLite(jr)
			if err != nil {
				return errorValue(), err
			}
			jr.skipWS()
			if jr.pos >= len(jr.data) || jr.data[jr.pos] != ':' {
				return errorValue(), fmt.Errorf("colon")
			}
			jr.pos++
			v, err := parseJSONValueLite(jr)
			if err != nil {
				return errorValue(), err
			}
			m.Set(k, v)
		}
		return MapValue(m), nil
	case '[':
		jr.pos++
		arr := []Value{}
		for {
			jr.skipWS()
			if jr.pos >= len(jr.data) {
				return errorValue(), fmt.Errorf("unterminated")
			}
			if jr.data[jr.pos] == ']' {
				jr.pos++
				break
			}
			if jr.data[jr.pos] == ',' {
				jr.pos++
				continue
			}
			v, err := parseJSONValueLite(jr)
			if err != nil {
				return errorValue(), err
			}
			arr = append(arr, v)
		}
		return Value{Kind: KindArray, A: arr}, nil
	case '"':
		s, err := parseJSONStrLite(jr)
		return StringValue(s), err
	case 't':
		if strings.HasPrefix(jr.data[jr.pos:], "true") {
			jr.pos += 4
			return BoolValue(true), nil
		}
	case 'f':
		if strings.HasPrefix(jr.data[jr.pos:], "false") {
			jr.pos += 5
			return BoolValue(false), nil
		}
	case 'n':
		if strings.HasPrefix(jr.data[jr.pos:], "null") {
			jr.pos += 4
			return NullValue(), nil
		}
	}
