func parseJSONStrLite(jr *jsonReaderLite) (string, error) {
	jr.skipWS()
	if jr.pos >= len(jr.data) || jr.data[jr.pos] != '"' {
		return "", fmt.Errorf("expected string")
	}
	jr.pos++
	var b strings.Builder
	for jr.pos < len(jr.data) {
		c := jr.data[jr.pos]
		jr.pos++
		if c == '"' {
			return b.String(), nil
		}
		if c == '\\' {
			if jr.pos >= len(jr.data) {
				break
			}
			e := jr.data[jr.pos]
			jr.pos++
			switch e {
			case '"':
				b.WriteByte('"')
			case '\\\\':
				b.WriteByte('\\\\')
			case '/':
				b.WriteByte('/')
			case 'b':
				b.WriteByte('\\b')
			case 'f':
				b.WriteByte('\\f')
			case 'n':
				b.WriteByte('\\n')
			case 'r':
				b.WriteByte('\\r')
			case 't':
				b.WriteByte('\\t')
			case 'u':
