{"command": "cd /workspace; cat > dsl_verb.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"strings"
)

type dslVerb struct {
	src       string
	quiet     bool
	invert    bool
	isFilter  bool
	rt        *RT
	beginBody []*Node
	endBody   []*Node
	begun     bool
	astMode   string
	exitAfter bool
	echoExpr  bool
}

func newDSLVerb(spec *VerbSpec, p *parsed, isFilter bool, opt *Options) (*dslVerb, error) {
	src := ""
	for _, l := range opt.LoadDSL {
		data, err := os.ReadFile(l)
		if err != nil {
			return nil, fmt.Errorf("mlr: open %s: no such file or directory", l)
		}
		src += string(data) + "\n"
	}
	if p.S["-f"] != "" {
		data, err := os.ReadFile(p.S["-f"])
		if err != nil {
			return nil, fmt.Errorf("mlr: open %s: no such file or directory", p.S["-f"])
		}
		src += string(data) + "\n"
	}
	if p.S["-e"] != "" {
		src += p.S["-e"] + "\n"
	}
	if spec.main != "" {
		src += spec.main
	}
	if src == "" {
		return nil, fmt.Errorf("mlr: mlr put: DSL expression required")
	}
	v := &dslVerb{quiet: p.B["-q"], invert: p.B["-x"], isFilter: isFilter}
	if p.B["-X"] {
		v.exitAfter = true
	}
	if p.B["-v"] {
		v.echoExpr = true
		v.astMode = "-p"
	} else if p.B["-p"] {
		v.astMode = "-p"
	} else if p.B["-d"] {
		v.astMode = "-d"
	} else if p.B["-D"] {
		v.astMode = "-D"
	} else if p.B["-E"] {
		v.echoExpr = true
	}
	stmts, err := parseProgram(src)
	if err != nil {
		return nil, err
	}
	if v.echoExpr {
		fmt.Println(src)
	}
	if v.astMode != "" {
		fmt.Print(renderAST(stmts, v.astMode))
	}
	if v.exitAfter {
		os.Exit(0)
	}
	rt := NewRT(NewCtx(opt), &DSLOpts{quiet: v.quiet, invert: v.invert})
	for _, kv := range p.S["-s"] != "" ? []string{} : []string{} {
	}
	// -s name=value
	for _, e := range splitPairs(p.S["-s"]) {
		i := strings.Index(e, "=")
		if i < 0 {
			continue
		}
		name := e[:i]
		val := e[i+1:]
		rt.oos.Set(name, inferValue(val, opt))
	}
	for _, st := range stmts {
		if st.Kind == "begin" {
			v.beginBody = append(v.beginBody, st.Body...)
		} else if st.Kind == "end" {
			v.endBody = append(v.endBody, st.Body...)
		}
	}
	v.rt = rt
	v.src = src
	return v, nil
}

func splitPairs(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}

func (v *dslVerb) runBegin() {
	if v.begun {
		return
	}
	v.begun = true
	v.rt.evalBody(v.beginBody)
}

func (v *dslVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	v.runBegin()
	rt := v.rt
	rt.rec = rec.Clone()
	rt.captures = nil
	rt.emitOut = nil
	rt.brk = false
	rt.cont = false
	rt.ret = false
	rt.evalBody(stmtsOf(v))
	recs := rt.emitOut
	if !v.quiet && !v.isFilter {
		recs = append(recs, rt.rec)
	}
	if v.isFilter {
		pass := true
		if rt.hasFilter {
			pass = truthy(rt.filterVal)
		}
		if v.invert {
			pass = !pass
		}
		if !pass {
			return recs, nil
		}
		return recs, nil
	}
	return recs, nil
}

func (v *dslVerb) End(ctx *Ctx) ([]*Record, error) {
	rt := v.rt
	rt.rec = NewMap()
	rt.captures = nil
	rt.emitOut = nil
	rt.evalBody(v.endBody)
	recs := rt.emitOut
	return recs, nil
}

func (v *dslVerb) Close() error { return nil }

func stmtsOf(v *dslVerb) []*Node { return v.body }

func renderAST(stmts []*Node, mode string) string {
	var b strings.Builder
	for _, st := range stmts {
		renderNode(&b, st, mode, 0)
	}
	return b.String()
}

func renderNode(b *strings.Builder, n *Node, mode string, depth int) {
	ind := strings.Repeat("  ", depth)
	if mode == "-D" {
		b.WriteString("(" + n.Kind)
		for _, c := range []*Node{n.Left, n.Right, n.Third} {
			if c != nil {
				b.WriteString(" ")
				renderNode(b, c, mode, depth)
			}
		}
		for _, c := range n.List {
			b.WriteString(" ")
			renderNode(b, c, mode, depth)
		}
		b.WriteString(")")
		return
	}
	b.WriteString(ind + n.Kind)
	if n.Str != "" {
		b.WriteString(" " + n.Str)
	}
	if n.Name != "" {
		b.WriteString(" " + n.Name)
	}
	b.WriteString("\n")
	for _, c := range []*Node{n.Left, n.Right, n.Third} {
		if c != nil {
			renderNode(b, c, mode, depth+1)
		}
	}
	for _, c := range n.List {
		renderNode(b, c, mode, depth+1)
	}
	for _, c := range n.Body {
		renderNode(b, c, mode, depth+1)
	}
}
