{"command": "cd /workspace; python3 - <<'PYEOF'
s=open('recordio.go').read()
old=s[s.index('func (lr *lineReader) Next() (*Record, error) {'):s.index('func (lr *lineReader) Close() error { return nil }')]
new='''func (lr *lineReader) Next() (*Record, error) {
	for {
		if lr.eof {
			return nil, io.EOF
		}
		if isCSVFormat(lr.opt.IFormat) {
			rec, done, err := lr.nextCSV()
			if err != nil {
				return nil, err
			}
			if done {
				return nil, io.EOF
			}
			if rec == nil {
				continue
			}
			return rec, nil
		}
		line, err := lr.src.ReadString('\\n')
		if err != nil {
			if err == io.EOF {
				lr.eof = true
				if line == "" {
					return nil, io.EOF
				}
			} else {
				return nil, err
			}
		}
		line = strings.TrimSuffix(line, "\\n")
		line = strings.TrimSuffix(line, "\\r")
		if lr.opt.CommentsMode != CommentsNone {
			if strings.HasPrefix(line, lr.opt.CommentsPrefix) {
				if lr.opt.CommentsMode == CommentsPass {
					fmt.Println(lr.opt.CommentsPrefix + strings.TrimPrefix(line, lr.opt.CommentsPrefix))
				}
				continue
			}
		}
		switch lr.opt.IFormat {
		case FormatDKVP:
			return dkvpRecord(lr.opt, splitLine(line, lr.opt.IFS, lr.opt.IFSRegex, false)), nil
		case FormatNIDX:
			return nidxRecord(splitLine(line, lr.opt.IFS, lr.opt.IFSRegex, lr.opt.RepIfs)), nil
		case FormatPPrint:
			return nidxRecord(splitLine(line, lr.opt.IFS, lr.opt.IFSRegex, false)), nil
		}
		return NewMap(), nil
	}
}

func isCSVFormat(f Format) bool {
	return f == FormatCSV || f == FormatTSV || f == FormatCSVLite || f == FormatTSVLite
}

// nextCSV reads one CSV/TSV record, handling quoted fields.
func (lr *lineReader) nextCSV() (*Record, bool, error) {
	fields, err := lr.readCSVFields()
	if err != nil {
		return nil, true, err
	}
	if len(fields) == 1 && fields[0] == "" && lr.finished {
		return nil, true, nil
	}
	if len(fields) == 0 {
		return nil, false, nil
	}
	rec := lr.csvRecord(fields)
	if rec == nil {
		return nil, false, fmt.Errorf("mlr: ragged CSV input")
	}
	if rec.Len() == 0 {
		// header line: no output record
		return nil, false, nil
	}
	return rec, false, nil
}

func (lr *lineReader) readCSVFields() ([]string, error) {
	sep := lr.opt.IFS
	if len(sep) != 1 {
		sep = ","
	}
	quoteMode := lr.opt.IFormat == FormatCSV || lr.opt.IFormat == FormatTSV
	fields := []string{}
	var cur strings.Builder
	inQuotes := false
	fieldStart := true
	seenAny := false
	for {
		c, ok, eof := lr.readByte()
		if eof {
			if cur.Len() > 0 || inQuotes || len(fields) > 0 {
				fields = append(fields, cur.String())
			}
			return fields, nil
		}
		_ = ok
		if inQuotes {
			if c == '"' {
				nc, _, eof2 := lr.peekByte()
				if eof2 {
					inQuotes = false
					continue
				}
				if nc == '"' {
					lr.readByte()
					cur.WriteByte('"')
					continue
				}
				if lr.opt.LazyQuotes {
					cur.WriteByte('"')
					continue
				}
				inQuotes = false
				continue
			}
			cur.WriteByte(c)
			continue
		}
		if quoteMode && fieldStart && c == '"' && !lr.opt.CSVTrimSpace {
			inQuotes = true
			fieldStart = false
			seenAny = true
			continue
		}
		if string(c) == sep {
			fields = append(fields, cur.String())
			cur.Reset()
			fieldStart = true
