// ---------- flatten / unflatten ----------

type flattenVerb struct {
	fields []string
	sep    string
	all    bool
	un     bool
}

func newFlattenVerb(p *parsed, un bool, opt *Options) *flattenVerb {
	sep := p.S["-s"]
	if sep == "" {
		sep = opt.FlatSep
	}
	return &flattenVerb{fields: fieldList(p.S["-f"]), sep: sep, un: un}
}

func (v *flattenVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		if len(v.fields) > 0 {
			found := false
			for _, f := range v.fields {
				if k == f {
					found = true
					break
				}
			}
			if !found {
				out.Set(k, val)
				continue
			}
		}
		if v.un {
			flat := NewMap()
			rt := &RT{ctx: ctx}
			rt.flattenIntoRecord(flat, "", val)
			m := NewMap()
			for _, kk := range flat.Keys() {
				fv, _ := flat.Get(kk)
				parts := strings.Split(kk, v.sep)
				cur := m
				for i, pp := range parts {
					if i == len(parts)-1 {
						cur.Set(pp, fv)
					} else {
						if e, ok := cur.Get(pp); ok && e.Kind == KindMap {
							cur = e.M
						} else {
							nm := NewMap()
							cur.Set(pp, MapValue(nm))
							cur = nm
						}
					}
				}
			}
			out.Set(k, MapValue(m))
			continue
		}
		flat := NewMap()
		rt := &RT{ctx: ctx}
		rt.flattenIntoRecord(flat, "", val)
		for _, kk := range flat.Keys() {
			fv, _ := flat.Get(kk)
			out.Set(k+v.sep+kk, fv)
		}
	}
	return []*Record{out}, nil
}

func (v *flattenVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *flattenVerb) Close() error                    { return nil }

// ---------- format-values ----------

type formatValuesVerb struct {
	intFmt    string
	floatFmt  string
	strFmt    string
	toInt     bool
	rt        *RT
}

func newFormatValuesVerb(p *parsed) *formatValuesVerb {
	i := p.S["-i"]
	if i == "" {
		i = "%d"
	}
	f := p.S["-f"]
	if f == "" {
		f = "%f"
	}
	s := p.S["-s"]
	if s == "" {
		s = "%s"
	}
	return &formatValuesVerb{intFmt: i, floatFmt: f, strFmt: s, toInt: p.B["-n"]}
}

func (v *formatValuesVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		if v.toInt && val.Kind == KindInt {
			val = Value{Kind: KindFloat, F: float64(val.I)}
		}
		var fmtStr string
		switch val.Kind {
		case KindInt:
			fmtStr = v.intFmt
		case KindFloat:
			fmtStr = v.floatFmt
		default:
			fmtStr = v.strFmt
		}
		nv := fmtnumValue(val, fmtStr)
		if isError(nv) {
			continue
		}
		out.Set(k, nv)
	}
	return []*Record{out}, nil
}

func fmtnumValue(v Value, fmtStr string) Value {
	gf := strings.ReplaceAll(fmtStr, "_", "")
	thousands := gf != fmtStr
	var out string
	switch v.Kind {
	case KindInt:
		out = fmt.Sprintf(gf, v.I)
	case KindFloat:
		out = fmt.Sprintf(gf, v.F)
	case KindBool:
		if v.B {
			out = fmt.Sprintf(gf, int64(1))
		} else {
			out = fmt.Sprintf(gf, int64(0))
		}
	case KindString:
		out = fmt.Sprintf(gf, v.S)
	default:
		out = v.String()
	}
	if thousands {
		out = addThousands(out)
	}
	return StringValue(out)
}

func (v *formatValuesVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *formatValuesVerb) Close() error                    { return nil }

