func (v *bootstrapVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	v.buf = append(v.buf, rec)
	return nil, nil
}

func (v *bootstrapVerb) End(ctx *Ctx) ([]*Record, error) {
	n := v.n
	if n < 0 {
		n = len(v.buf)
	}
	out := []*Record{}
	if len(v.buf) == 0 {
		return out, nil
	}
	for i := 0; i < n; i++ {
		j := int(randUint32()) % len(v.buf)
		out = append(out, v.buf[j].Clone())
	}
	return out, nil
}

func (v *bootstrapVerb) Close() error { return nil }

type shuffleVerb struct {
	buf []*Record
}

func (v *shuffleVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	v.buf = append(v.buf, rec)
	return nil, nil
}

func (v *shuffleVerb) End(ctx *Ctx) ([]*Record, error) {
	out := append([]*Record{}, v.buf...)
	for i := len(out) - 1; i > 0; i-- {
		j := int(randUint32()) % (i + 1)
		out[i], out[j] = out[j], out[i]
	}
	return out, nil
}

func (v *shuffleVerb) Close() error { return nil }

type sampleVerb struct {
	k      int
	groups []string
	res    map[string][]*Record
	keys   []string
	buf    []*Record
}

func newSampleVerb(p *parsed) *sampleVerb {
	return &sampleVerb{k: atoi(p.S["-k"], 1), groups: fieldList(p.S["-g"]),
		res: map[string][]*Record{}}
}

func (v *sampleVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if len(v.groups) == 0 {
		v.buf = append(v.buf, rec)
		return nil, nil
	}
	key := groupKey(rec, v.groups)
	list, ok := v.res[key]
	if !ok {
		v.keys = append(v.keys, key)
	}
	if len(list) < v.k {
		v.res[key] = append(list, rec)
	} else {
		i := int(randUint32()) % (len(list) + 1)
		if i < v.k {
			list[i] = rec
		}
		v.res[key] = list
	}
	return nil, nil
}

func (v *sampleVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	if len(v.groups) == 0 {
		for i, rec := range v.buf {
			if i < v.k {
				out = append(out, rec)
			}
		}
		return out, nil
	}
	for _, key := range v.keys {
		out = append(out, v.res[key]...)
	}
	return out, nil
}

func (v *sampleVerb) Close() error { return nil }

// ---------- top ----------

type topVerb struct {
	fields  []string
	groups  []string
	n       int
	all     bool
	min     bool
	floats  bool
	o       string
	groupsByKey map[string][]*Record
	keys    []string
	valsByKey map[string][]topEntry
}

type topEntry struct {
	rec  *Record
	val  Value
}

func newTopVerb(p *parsed) *topVerb {
	return &topVerb{fields: fieldList(p.S["-f"]), groups: fieldList(p.S["-g"]),
		n: atoi(p.S["-n"], 1), all: p.B["-a"], min: p.B["--min"], floats: p.B["-F"],
		o: p.S["-o"], groupsByKey: map[string][]*Record{}, valsByKey: map[string][]topEntry{}}
}

func (v *topVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if len(v.fields) == 0 {
		return nil, fmt.Errorf("mlr: mlr top: -f field names required")
	}
	key := groupKey(rec, v.groups)
	if _, ok := v.valsByKey[key]; !ok {
		v.keys = append(v.keys, key)
	}
	if len(v.fields) > 1 {
		v.groupsByKey[key] = append(v.groupsByKey[key], rec.Clone())
		return nil, nil
	}
	val, ok := rec.Get(v.fields[0])
	if !ok {
		return nil, nil
	}
	if v.floats {
		val = Value{Kind: KindFloat, F: toFloat(val)}
	}
	list := v.valsByKey[key]
	list = append(list, topEntry{rec: rec.Clone(), val: val})
	v.valsByKey[key] = list
	return nil, nil
}

func (v *topVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	for _, key := range v.keys {
		list := v.valsByKey[key]
		sort.SliceStable(list, func(i, j int) bool {
			c, ok := compareValues(list[i].val, list[j].val)
			if !ok {
				c = strings.Compare(strVal(list[i].val), strVal(list[j].val))
			}
			if v.min {
				return c < 0
			}
			return c > 0
		})
		if len(list) > v.n {
			list = list[:v.n]
		}
		for idx, e := range list {
			if v.all {
				r := e.rec.Clone()
				if len(v.fields) == 1 {
					name := v.o
					if name == "" {
						name = "top_idx"
					}
					r.Set(name, IntValue(int64(idx+1)))
				}
				out = append(out, r)
				continue
			}
			r := NewMap()
			parts := strings.Split(key, "\x00")
			for i, g := range v.groups {
				if i < len(parts) {
					r.Set(g, StringValue(parts[i]))
				}
			}
			for _, f := range v.fields {
				val, ok := e.rec.Get(f)
				if ok {
					r.Set(f, val)
				}
			}
			name := v.o
			if name == "" {
				name = "top_idx"
			}
			r.Set(name, IntValue(int64(idx+1)))
			out = append(out, r)
		}
	}
	return out, nil
}

func (v *topVerb) Close() error { return nil }

// ---------- least/most-frequent ----------

type freqVerb struct {
	fields  []string
	n       int
	suppress bool
	o       string
	least   bool
	counts  map[string]int64
	first   map[string]Value
	keys    []string
}

func newFreqVerb(p *parsed, least bool) (*freqVerb, error) {
	f := fieldList(p.S["-f"])
	if len(f) == 0 {
		return nil, fmt.Errorf("mlr: mlr %s: -f field names required", map[bool]string{true: "least-frequent", false: "most-frequent"}[least])
	}
	return &freqVerb{fields: f, n: atoi(p.S["-n"], 10), suppress: p.B["-b"],
		o: p.S["-o"], least: least, counts: map[string]int64{}, first: map[string]Value{}}, nil
}

func (v *freqVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	var b strings.Builder
	for _, f := range v.fields {
		val, ok := rec.Get(f)
		if ok {
			b.WriteString(strVal(val))
		}
		b.WriteByte(0)
	}
	key := b.String()
	if _, ok := v.counts[key]; !ok {
		list := []Value{}
		for _, f := range v.fields {
			val, _ := rec.Get(f)
			list = append(list, val)
		}
		v.first[key] = Value{Kind: KindArray, A: list}
		v.keys = append(v.keys, key)
	}
	v.counts[key]++
	return nil, nil
}

func (v *freqVerb) End(ctx *Ctx) ([]*Record, error) {
	type entry struct {
		key   string
		count int64
	}
	entries := []entry{}
	for _, k := range v.keys {
		entries = append(entries, entry{k, v.counts[k]})
	}
	sort.SliceStable(entries, func(i, j int) bool {
		if v.least {
			return entries[i].count < entries[j].count
		}
		return entries[i].count > entries[j].count
	})
	if len(entries) > v.n {
		entries = entries[:v.n]
	}
	out := []*Record{}
	for _, e := range entries {
		r := NewMap()
		val := v.first[e.key]
		for i, f := range v.fields {
			if val.Kind == KindArray && i < len(val.A) {
				r.Set(f, val.A[i])
			}
		}
		if !v.suppress {
			name := v.o
			if name == "" {
				name = "count"
			}
			r.Set(name, IntValue(e.count))
		}
		out = append(out, r)
	}
	return out, nil
}

func (v *freqVerb) Close() error { return nil }

// ---------- bar ----------

type barVerb struct {
	fields  []string
	lo      float64
	hi      float64
	width   int
	auto    bool
	fill    string
	out     string
	blank   string
	buf     []*Record
}

func newBarVerb(p *parsed) *barVerb {
	return &barVerb{fields: fieldList(p.S["-f"]), lo: atof(p.S["--lo"], 0.0),
		hi: atof(p.S["--hi"], 100.0), width: atoi(p.S["-w"], 40), auto: p.B["--auto"],
		fill: p.S["-c"], out: p.S["-x"], blank: p.S["-b"]}
}

func (v *barVerb) fixDefaults() {
	if v.fill == "" {
		v.fill = "*"
	}
	if v.out == "" {
		v.out = "#"
	}
	if v.blank == "" {
		v.blank = "."
	}
}

func (v *barVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	v.fixDefaults()
	if v.auto {
		v.buf = append(v.buf, rec.Clone())
		return nil, nil
	}
	return []*Record{v.barify(rec, v.lo, v.hi)}, nil
}

func (v *barVerb) barify(rec *Record, lo, hi float64) *Record {
	out := rec.Clone()
	for _, f := range v.fields {
		val, ok := rec.Get(f)
		if !ok || !val.IsNumber() {
			continue
		}
		x := toFloat(val)
		width := v.width
		var s string
		if x < lo {
			s = strings.Repeat(v.out, width)
		} else if x > hi {
			s = strings.Repeat(v.fill, width)
		} else {
			frac := (x - lo) / (hi - lo)
			if frac < 0 {
				frac = 0
			}
			if frac > 1 {
				frac = 1
			}
			n := int(frac * float64(width))
			s = strings.Repeat(v.fill, n) + strings.Repeat(v.blank, width-n)
		}
		out.Set(f, StringValue(s))
	}
	return out
}

func (v *barVerb) End(ctx *Ctx) ([]*Record, error) {
	if !v.auto {
		return nil, nil
	}
	lo, hi := math.Inf(1), math.Inf(-1)
	for _, rec := range v.buf {
		for _, f := range v.fields {
			val, ok := rec.Get(f)
			if !ok || !val.IsNumber() {
				continue
			}
			x := toFloat(val)
			if x < lo {
				lo = x
			}
			if x > hi {
				hi = x
			}
		}
	}
	if math.IsInf(lo, 1) {
		lo, hi = 0, 100
	}
	out := []*Record{}
	for _, rec := range v.buf {
		out = append(out, v.barify(rec, lo, hi))
	}
	return out, nil
}

func (v *barVerb) Close() error { return nil }

// ---------- sub/gsub/ssub ----------

type subVerb struct {
	fields   []string
	regex    string
	all      bool
	old      string
	nw       string
	useRegex bool
	global   bool
}

func newSubVerb(p *parsed, main string, global, useRegex bool) (*subVerb, error) {
	v := &subVerb{fields: fieldList(p.S["-f"]), regex: p.S["-r"], all: p.B["-a"],
		global: global, useRegex: useRegex}
	parts := fieldList(main)
	if len(parts) == 2 {
		v.old, v.nw = parts[0], parts[1]
	} else if len(parts) == 1 {
		v.old = parts[0]
	}
	return v, nil
}

func (v *subVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if v.old == "" {
		return nil, fmt.Errorf("mlr: mlr sub: old and new strings required")
	}
	out := rec.Clone()
	var re *regexp.Regexp
	if v.useRegex {
		r, err := regexCompileSpec(v.old, false)
		if err != nil {
			return nil, err
		}
		re = r
	}
	for _, k := range rec.Keys() {
		do := false
		if v.all {
			do = true
		} else if len(v.fields) > 0 {
			for _, f := range v.fields {
				if k == f {
					do = true
					break
				}
			}
		} else if v.regex != "" {
			r, err := regexCompileSpec(v.regex, false)
			if err == nil && r.MatchString(k) {
				do = true
			}
		}
		if !do {
			continue
		}
		val, _ := rec.Get(k)
		s := val.String()
		var ns string
		if re != nil {
			if v.global {
				ns = re.ReplaceAllStringFunc(s, func(m string) string {
					return expandCaptures(v.nw, re.FindStringSubmatch(m))
				})
			} else {
				loc := re.FindStringSubmatchIndex(s)
				if loc == nil {
					ns = s
				} else {
					var b strings.Builder
					b.WriteString(s[:loc[0]])
					b.WriteString(expandCaptures(v.nw, re.FindStringSubmatch(s)))
					b.WriteString(s[loc[1]:])
					ns = b.String()
				}
			}
		} else {
			if v.global {
				ns = strings.ReplaceAll(s, v.old, v.nw)
			} else {
				ns = strings.Replace(s, v.old, v.nw, 1)
			}
		}
		if ns != s {
			out.Set(k, StringValue(ns))
		}
	}
	return []*Record{out}, nil
}

func (v *subVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *subVerb) Close() error                    { return nil }

// ---------- latin1-to-utf8 / utf8-to-latin1 ----------

type convertVerb struct{ toUTF8 bool }

func (v *convertVerb) convert(vv Value) Value {
	switch vv.Kind {
	case KindString:
		var b strings.Builder
		if v.toUTF8 {
			for _, c := range []byte(vv.S) {
				if c < 0x80 {
					b.WriteByte(c)
				} else {
					b.WriteRune(runeFromCode(int(c)))
				}
			}
			return StringValue(b.String())
		}
		for _, r := range vv.S {
			if r < 256 {
				b.WriteByte(byte(r))
			} else {
				b.WriteByte('?')
			}
		}
		return StringValue(b.String())
	case KindMap:
		m := NewMap()
		for _, k := range vv.M.Keys() {
			val, _ := vv.M.Get(k)
			m.Set(v.convert(StringValue(k)).S, v.convert(val))
		}
		return MapValue(m)
	case KindArray:
		a := []Value{}
		for _, e := range vv.A {
			a = append(a, v.convert(e))
		}
		return Value{Kind: KindArray, A: a}
	}
	return vv
}

func (v *convertVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		out.Set(v.convert(StringValue(k)).S, v.convert(val))
	}
	return []*Record{out}, nil
}

func (v *convertVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *convertVerb) Close() error                    { return nil }

// ---------- remove-empty-columns ----------

type removeEmptyColumnsVerb struct {
	buf    []*Record
	seen   map[string]int
	nonEmpty map[string]int
	keys   []string
}

func newRemoveEmptyColumnsVerb() *removeEmptyColumnsVerb {
	return &removeEmptyColumnsVerb{seen: map[string]int{}, nonEmpty: map[string]int{}}
}

func (v *removeEmptyColumnsVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	for _, k := range rec.Keys() {
		if _, ok := v.seen[k]; !ok {
			v.keys = append(v.keys, k)
		}
		v.seen[k]++
		val, _ := rec.Get(k)
		if val.String() != "" {
			v.nonEmpty[k]++
		}
	}
	v.buf = append(v.buf, rec.Clone())
	return nil, nil
}

func (v *removeEmptyColumnsVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	for _, rec := range v.buf {
		r := NewMap()
		for _, k := range rec.Keys() {
			if v.seen[k] == v.nonEmpty[k] && v.nonEmpty[k] == 0 {
				continue
			}
			val, _ := rec.Get(k)
			r.Set(k, val)
		}
		out = append(out, r)
	}
	return out, nil
}

func (v *removeEmptyColumnsVerb) Close() error { return nil }

// ---------- unsparsify ----------

type unsparsifyVerb struct {
	fillWith string
	fields   []string
	union    []string
	seen     map[string]bool
	buf      []*Record
}

func newUnsparsifyVerb(p *parsed) *unsparsifyVerb {
	return &unsparsifyVerb{fillWith: p.S["--fill-with"], fields: fieldList(p.S["-f"]),
		seen: map[string]bool{}}
}

func (v *unsparsifyVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	for _, k := range rec.Keys() {
		if len(v.fields) > 0 {
			found := false
			for _, f := range v.fields {
				if k == f {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}
		if !v.seen[k] {
			v.seen[k] = true
			v.union = append(v.union, k)
		}
	}
	v.buf = append(v.buf, rec.Clone())
	return nil, nil
}

func (v *unsparsifyVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	for _, rec := range v.buf {
		r := rec.Clone()
		for _, k := range v.union {
			if _, ok := r.Get(k); !ok {
				if v.fillWith != "" {
					r.Set(k, inferValue(v.fillWith, ctx.opt))
				} else {
					r.Set(k, StringValue(""))
				}
			}
		}
		out = append(out, r)
	}
	return out, nil
}

func (v *unsparsifyVerb) Close() error { return nil }
