package main

import (
	"fmt"
	"math"
	"os"
	"sort"
	"strconv"
	"strings"
)

// ---------- summary ----------

var summaryAll = []string{"field_type", "count", "null_count", "distinct_count", "mode",
	"sum", "mean", "stddev", "var", "skewness", "minlen", "maxlen", "min", "p25", "median",
	"p75", "max", "iqr", "lof", "lif", "uif", "uof"}

var summaryDefault = []string{"field_type", "count", "mean", "min", "max", "null_count",
	"distinct_count"}

type summaryVerb struct {
	which     []string
	transpose bool
	fields    []string
	types     map[string][]string
	vals      map[string][]Value
	keys      []string
}

func newSummaryVerb(p *parsed) *summaryVerb {
	which := summaryDefault
	if p.B["--all"] {
		which = summaryAll
	}
	if p.S["-a"] != "" {
		which = strings.Split(p.S["-a"], ",")
	}
	if p.S["-x"] != "" {
		excl := map[string]bool{}
		for _, e := range strings.Split(p.S["-x"], ",") {
			excl[e] = true
		}
		nw := []string{}
		for _, w := range summaryAll {
			if !excl[w] {
				nw = append(nw, w)
			}
		}
		which = nw
	}
	return &summaryVerb{which: which, transpose: p.B["--transpose"],
		types: map[string][]string{}, vals: map[string][]Value{}}
}

func typeNameOf(v Value) string {
	switch v.Kind {
	case KindInt:
		return "int"
	case KindFloat:
		return "float"
	case KindBool:
		return "boolean"
	case KindString:
		return "string"
	case KindMap:
		return "map"
	case KindArray:
		return "array"
	case KindNull:
		return "null"
	case KindAbsent:
		return "absent"
	case KindError:
		return "error"
	}
	return ""
}

func (v *summaryVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	for _, k := range rec.Keys() {
		if _, ok := v.vals[k]; !ok {
			v.keys = append(v.keys, k)
			v.fields = append(v.fields, k)
		}
		val, _ := rec.Get(k)
		v.vals[k] = append(v.vals[k], val)
	}
	return nil, nil
}

func (v *summaryVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	for _, f := range v.keys {
		r := NewMap()
		vals := v.vals[f]
		for _, name := range v.which {
			r.Set(name, summaryValue(name, f, vals))
		}
		out = append(out, r)
	}
	if !v.transpose {
		return out, nil
	}
	// transpose: one record per summarizer, with field names as columns
	out2 := []*Record{}
	for i, name := range v.which {
		r := NewMap()
		r.Set("field_name", StringValue(name))
		for _, f := range v.keys {
			if i < len(out) {
				val, ok := out[i].Get(f)
				if ok {
					r.Set(f, val)
				}
			}
		}
		out2 = append(out2, r)
	}
	return out2, nil
}

func summaryValue(name, f string, vals []Value) Value {
	switch name {
	case "field_type":
		set := map[string]bool{}
		var list []string
		for _, v := range vals {
			t := typeNameOf(v)
			if !set[t] {
				set[t] = true
				list = append(list, t)
			}
		}
		return StringValue(strings.Join(list, ","))
	case "count":
		return IntValue(int64(len(vals)))
	case "null_count":
		n := 0
		for _, v := range vals {
			if v.Kind == KindNull || (v.Kind == KindString && v.S == "") {
				n++
			}
		}
		return IntValue(int64(n))
	case "distinct_count":
		set := map[string]bool{}
		for _, v := range vals {
			set[strVal(v)] = true
		}
		return IntValue(int64(len(set)))
	case "mode":
		counts := map[string]int64{}
		first := map[string]Value{}
		var order []string
		for _, v := range vals {
			k := strVal(v)
			if _, ok := counts[k]; !ok {
				order = append(order, k)
				first[k] = v
			}
			counts[k]++
		}
		best := ""
		bestc := int64(-1)
		for _, k := range order {
			if counts[k] > bestc {
				best, bestc = k, counts[k]
			}
		}
		if best == "" {
			return StringValue("")
		}
		return first[best]
	case "minlen":
		best := -1
		for _, v := range vals {
			l := len(strVal(v))
			if best < 0 || l < best {
				best = l
			}
		}
		return IntValue(int64(best))
	case "maxlen":
		best := -1
		for _, v := range vals {
			l := len(strVal(v))
			if l > best {
				best = l
			}
		}
		return IntValue(int64(best))
	case "sum", "mean", "var", "stddev", "skewness":
		nums := []float64{}
		for _, v := range vals {
			x, ok := wantNum(v)
			if !ok {
				return StringValue("")
			}
			nums = append(nums, x)
		}
		switch name {
		case "sum":
			s := 0.0
			for _, x := range nums {
				s += x
			}
			return FloatValue(s)
		case "mean":
			s := 0.0
			for _, x := range nums {
				s += x
			}
			return FloatValue(s / float64(len(nums)))
		case "var", "stddev":
			s := 0.0
			for _, x := range nums {
				s += x
			}
			m := s / float64(len(nums))
			ss := 0.0
			for _, x := range nums {
				ss += (x - m) * (x - m)
			}
			vv := ss / float64(len(nums))
			if name == "var" {
				return FloatValue(vv)
			}
			return FloatValue(math.Sqrt(vv))
		}
	case "min", "max", "p25", "median", "p75", "iqr", "lof", "lif", "uif", "uof":
		if name == "min" || name == "max" {
			var best Value
			first := true
			for _, v := range vals {
				if first {
					best = v
					first = false
					continue
				}
				c, ok := compareValues(v, best)
				if !ok {
					continue
				}
				if (name == "min" && c < 0) || (name == "max" && c > 0) {
					best = v
				}
			}
			if first {
				return StringValue("")
			}
			return best
		}
		nums := []float64{}
		strs := []string{}
		allNum := true
		for _, v := range vals {
			strs = append(strs, strVal(v))
			x, ok := wantNum(v)
			if !ok {
				allNum = false
			} else {
				nums = append(nums, x)
			}
		}
		pct := func(nd float64) Value {
			if allNum {
				sort.Float64s(nums)
				idx := int(math.Ceil(nd / 100.0 * float64(len(nums))))
				if idx < 1 {
					idx = 1
				}
				if idx > len(nums) {
					idx = len(nums)
				}
				return FloatValue(nums[idx-1])
			}
			sort.Strings(strs)
			idx := int(math.Ceil(nd / 100.0 * float64(len(strs))))
			if idx < 1 {
				idx = 1
			}
			if idx > len(strs) {
				idx = len(strs)
			}
			return StringValue(strs[idx-1])
		}
		p25 := pct(25)
		p50 := pct(50)
		p75 := pct(75)
		switch name {
		case "p25":
			return p25
		case "median":
			return p50
		case "p75":
			return p75
		case "iqr", "lof", "lif", "uif", "uof":
			if !allNum {
				return StringValue("")
			}
			iqr := toFloat(p75) - toFloat(p25)
			switch name {
			case "iqr":
				return FloatValue(iqr)
			case "lof":
				return FloatValue(toFloat(p25) - 3.0*iqr)
			case "lif":
				return FloatValue(toFloat(p25) - 1.5*iqr)
			case "uif":
				return FloatValue(toFloat(p75) + 1.5*iqr)
			case "uof":
				return FloatValue(toFloat(p75) + 3.0*iqr)
			}
		}
	}
	return StringValue("")
}

func (v *summaryVerb) Close() error { return nil }

// ---------- histogram ----------

type histogramVerb struct {
	fields []string
	lo     float64
	hi     float64
	nbins  int
	auto   bool
	prefix string
	buf    []*Record
}

func newHistogramVerb(p *parsed) *histogramVerb {
	return &histogramVerb{fields: fieldList(p.S["-f"]), lo: atof(p.S["--lo"], 0),
		hi: atof(p.S["--hi"], 100), nbins: atoi(p.S["--nbins"], 20), auto: p.B["--auto"],
		prefix: p.S["-o"]}
}

func (v *histogramVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if v.auto {
		for _, f := range v.fields {
			val, ok := rec.Get(f)
			if !ok || !val.IsNumber() {
				continue
			}
			x := toFloat(val)
			if x < v.lo {
				v.lo = x
			}
			if x > v.hi {
				v.hi = x
			}
		}
	}
	v.buf = append(v.buf, rec.Clone())
	return nil, nil
}

func (v *histogramVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	counts := map[string]map[int]int{}
	order := []string{}
	for _, rec := range v.buf {
		key := groupKey(rec, nil)
		_ = key
		for _, f := range v.fields {
			val, ok := rec.Get(f)
			if !ok || !val.IsNumber() {
				continue
			}
			x := toFloat(val)
			if x < v.lo || x > v.hi {
				continue
			}
			idx := int((x - v.lo) / (v.hi - v.lo) * float64(v.nbins))
			if idx < 0 {
				idx = 0
			}
			if idx >= v.nbins {
				idx = v.nbins - 1
			}
			if _, ok := counts[f]; !ok {
				counts[f] = map[int]int{}
				order = append(order, f)
			}
			counts[f][idx]++
		}
	}
	r := NewMap()
	for _, f := range order {
		for i := 0; i < v.nbins; i++ {
			name := v.prefix + f + "_" + strconv.Itoa(i+1)
			r.Set(name, IntValue(int64(counts[f][i])))
		}
	}
	if len(order) > 0 {
		out = append(out, r)
	}
	return out, nil
}

func (v *histogramVerb) Close() error { return nil }

// ---------- merge-fields ----------

type mergeFieldsVerb struct {
	specs     []statsSpec
	fields    []string
	regex     string
	collapse  []string
	output    string
	keep      bool
	interpolated bool
	groupFields []string
	groups    map[string]*mergeAcc
	keys      []string
}

type mergeAcc struct {
	counts map[string]int64
	n      int
	nullCount int
	distinct map[string]int64
	sum, sum2, sum3, sum4 float64
	values []float64
	strvals []string
}

func newMergeFieldsVerb(p *parsed) (*mergeFieldsVerb, error) {
	specs, err := parseStats1Specs(p.S["-a"])
	if err != nil {
		return nil, fmt.Errorf("mlr: mlr merge-fields: %s", strings.TrimPrefix(err.Error(), "mlr: mlr stats1: "))
	}
	return &mergeFieldsVerb{specs: specs, fields: fieldList(p.S["-f"]), regex: p.S["-r"],
		collapse: fieldList(p.S["-c"]), output: p.S["-o"], keep: p.B["-k"],
		interpolated: p.B["-i"], groups: map[string]*mergeAcc{}}, nil
}

func (v *mergeFieldsVerb) fieldsFor(rec *Record) ([]string, []string) {
	var fields []string
	var collapsed []string
	for _, k := range rec.Keys() {
		var match bool
		if len(v.fields) > 0 {
			for _, f := range v.fields {
				if f == k {
					match = true
					break
				}
			}
		} else if v.regex != "" {
			re, err := regexCompileSpec(v.regex, false)
			if err == nil && re.MatchString(k) {
				match = true
			}
		}
		if !match {
			continue
		}
		cn := k
		for _, c := range v.collapse {
			cn = strings.Replace(cn, c, "", 1)
		}
		fields = append(fields, k)
		collapsed = append(collapsed, cn)
	}
	return fields, collapsed
}

func (v *mergeFieldsVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	fields, collapsed := v.fieldsFor(rec)
	groups := map[string]bool{}
	_ = groups
	for i, f := range fields {
		val, _ := rec.Get(f)
		cn := collapsed[i]
		acc, ok := v.groups[cn]
		if !ok {
			acc = &mergeAcc{counts: map[string]int64{}, distinct: map[string]int64{}}
			v.groups[cn] = acc
			v.keys = append(v.keys, cn)
		}
		acc.counts[strVal(val)]++
		if val.Kind == KindNull || (val.Kind == KindString && val.S == "") {
			acc.nullCount++
		}
		if val.IsNumber() {
			x := toFloat(val)
			acc.sum += x
			acc.sum2 += x * x
			acc.sum3 += x * x * x
			acc.sum4 += x * x * x * x
			acc.values = append(acc.values, x)
		}
		acc.strvals = append(acc.strvals, strVal(val))
		acc.n++
	}
	return nil, nil
}

func (v *mergeFieldsVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	for _, key := range v.keys {
		acc := v.groups[key]
		r := NewMap()
		if !v.keep {
			// omit input fields contributed
			for _, k := range v.lastKeys() {
				if collapsedMatches(k, key, v.collapse) {
					continue
				}
				val, _ := r.Get(k)
				_ = val
				continue
			}
		}
		name := v.output
		if name == "" {
			name = key
		}
		for _, spec := range v.specs {
			sv := stats1Value(spec, acc, v.interpolated)
			r.Set(name+"_"+spec.name, sv)
		}
		out = append(out, r)
	}
	return out, nil
}

var lastRec *Record

func (v *mergeFieldsVerb) lastKeys() []string {
	if lastRec == nil {
		return nil
	}
	return lastRec.Keys()
}

func collapsedMatches(k, key string, subs []string) bool {
	cn := k
	for _, c := range subs {
		cn = strings.Replace(cn, c, "", 1)
	}
	return cn == key
}

func (v *mergeFieldsVerb) Close() error { return nil }

// ---------- step ----------

type stepVerb struct {
	specs      []string
	fields     []string
	groups     []string
	weights    []float64
	suffixes   []string
	state      map[string]*stepState
	keys       []string
}

type stepState struct {
	count int64
	prev  map[string]Value
	sums  map[string]float64
	prods map[string]float64
	ewma  map[string][]float64
	win   []map[string]float64
	first map[string]Value
	next  map[string]Value
}

func newStepVerb(p *parsed) *stepVerb {
	specs := strings.Split(p.S["-a"], ",")
	if p.S["-a"] == "" {
		specs = nil
	}
	weights := []float64{}
	if p.S["-d"] != "" {
		for _, w := range strings.Split(p.S["-d"], ",") {
			weights = append(weights, atof(w, 0.5))
		}
	}
	if len(weights) == 0 {
		weights = []float64{0.5}
	}
	suffixes := []string{}
	if p.S["-o"] != "" {
		suffixes = strings.Split(p.S["-o"], ",")
	}
	if len(suffixes) == 0 {
		for _, w := range weights {
			suffixes = append(suffixes, numFmt(w))
		}
	}
	return &stepVerb{specs: specs, fields: fieldList(p.S["-f"]), groups: fieldList(p.S["-g"]),
		weights: weights, suffixes: suffixes, state: map[string]*stepState{}}
}

func (v *stepVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if len(v.specs) == 0 {
		return nil, fmt.Errorf("mlr: mlr step: -a stepper names required")
	}
	key := groupKey(rec, v.groups)
	st, ok := v.state[key]
	if !ok {
		st = &stepState{prev: map[string]Value{}, sums: map[string]float64{},
			prods: map[string]float64{}, ewma: map[string][]float64{}, first: map[string]Value{}}
		v.state[key] = st
		v.keys = append(v.keys, key)
	}
	st.count++
	out := rec.Clone()
	parts := strings.Split(key, "\x00")
	for i, g := range v.groups {
		if i < len(parts) {
			// already present
		}
	}
	for _, spec := range v.specs {
		base := spec
		extra := ""
		if strings.HasPrefix(spec, "slwin") {
			parts2 := strings.Split(spec, "_")
			if len(parts2) == 3 {
				base = "slwin"
				extra = spec
			}
		}
		for _, f := range v.fields {
			val, ok := rec.Get(f)
			if !ok {
				continue
			}
			switch base {
			case "counter":
				name := f + "_" + spec
				st.sums[name]++
				out.Set(name, IntValue(int64(st.sums[name])))
			case "delta":
				name := f + "_" + spec
				if prev, ok := st.prev[f]; ok {
					out.Set(name, rt_arith("-", val, prev))
				}
				st.prev[f] = val
			case "ratio":
				name := f + "_" + spec
				if prev, ok := st.prev[f]; ok {
					out.Set(name, rt_arith("/", val, prev))
				}
				st.prev[f] = val
			case "rsum":
				name := f + "_" + spec
				st.sums[name] += toFloat(val)
				out.Set(name, FloatValue(st.sums[name]))
			case "rprod":
				name := f + "_" + spec
				if _, ok := st.prods[name]; !ok {
					st.prods[name] = 1
				}
				st.prods[name] *= toFloat(val)
				out.Set(name, FloatValue(st.prods[name]))
			case "ewma":
				for i, w := range v.weights {
					name := f + "_ewma_" + v.suffixes[i]
					cur := st.ewma[name]
					var nw float64
					if len(cur) == 0 {
						nw = toFloat(val)
					} else {
						nw = w*toFloat(val) + (1-w)*cur[len(cur)-1]
					}
					st.ewma[name] = append(cur, nw)
					out.Set(name, FloatValue(nw))
				}
			case "from-first":
				name := f + "_" + spec
				if _, ok := st.first[f]; !ok {
					st.first[f] = val
				}
				out.Set(name, rt_arith("-", val, st.first[f]))
			case "shift", "shift_lag":
				name := f + "_" + spec
				if prev, ok := st.prev[f]; ok {
					out.Set(name, prev)
				}
				st.prev[f] = val
			case "shift_lead":
				// handled after all records are seen
				name := f + "_" + spec
				if _, ok := st.first[f]; !ok {
				}
				_ = name
			case "slwin":
				n, m := 0, 0
				fmt.Sscanf(extra, "slwin_%d_%d", &n, &m)
				name := f + "_" + spec
				st.win = append(st.win, map[string]float64{f: toFloat(val)})
				if len(st.win) > n+m+1 {
					st.win = st.win[len(st.win)-n-m-1:]
				}
				var s float64
				cnt := 0
				for _, w := range st.win {
					s += w[f]
					cnt++
				}
				if cnt > 0 {
					out.Set(name, FloatValue(s/float64(cnt)))
				}
			}
		}
	}
	return []*Record{out}, nil
}

func rt_arith(op string, a, b Value) Value {
	rt := &RT{}
	return rt.arith(op, a, b)
}

func (v *stepVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *stepVerb) Close() error                    { return nil }

