new='''type mergeFieldsVerb struct {
	specs        []statsSpec
	fields       []string
	regex        string
	collapse     []string
	output       string
	keep         bool
	interpolated bool
}

type mergeAcc struct {
	acc stats1Acc
}

func newMergeFieldsVerb(p *parsed) (*mergeFieldsVerb, error) {
	specs, err := parseStats1Specs(p.S["-a"])
	if err != nil {
		return nil, fmt.Errorf("mlr: mlr merge-fields: %s", strings.TrimPrefix(err.Error(), "mlr: mlr stats1: "))
	}
	return &mergeFieldsVerb{specs: specs, fields: fieldList(p.S["-f"]), regex: p.S["-r"],
		collapse: fieldList(p.S["-c"]), output: p.S["-o"], keep: p.B["-k"],
		interpolated: p.B["-i"]}, nil
}

func (v *mergeFieldsVerb) fieldsFor(rec *Record) ([]string, []string) {
	var fields []string
	var collapsed []string
	for _, k := range rec.Keys() {
		var match bool
		if len(v.fields) > 0 {
			for _, f := range v.fields {
				if f == k {
					match = true
					break
				}
			}
		} else if v.regex != "" {
			re, err := regexCompileSpec(v.regex, false)
			if err == nil && re.MatchString(k) {
				match = true
			}
		}
		if !match {
			continue
		}
		cn := k
		for _, c := range v.collapse {
			cn = strings.Replace(cn, c, "", 1)
		}
		fields = append(fields, k)
		collapsed = append(collapsed, cn)
	}
	return fields, collapsed
}

func (v *mergeFieldsVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	fields, collapsed := v.fieldsFor(rec)
	groups := map[string]*stats1Acc{}
	order := []string{}
	for i, f := range fields {
		val, _ := rec.Get(f)
		cn := collapsed[i]
		if len(v.collapse) == 0 && v.output != "" {
			cn = v.output
		}
		acc, ok := groups[cn]
		if !ok {
			acc = newStats1Acc()
			groups[cn] = acc
			order = append(order, cn)
		}
		acc.counts[strVal(val)]++
		if val.Kind == KindNull || (val.Kind == KindString && val.S == "") {
			acc.nullCount++
		}
		if val.IsNumber() {
			x := toFloat(val)
			acc.sum += x
			acc.sum2 += x * x
			acc.sum3 += x * x * x
			acc.sum4 += x * x * x * x
			acc.values = append(acc.values, x)
		}
		acc.strvals = append(acc.strvals, strVal(val))
		acc.n++
	}
	out := NewMap()
	for _, k := range rec.Keys() {
		if v.keep {
			val, _ := rec.Get(k)
			out.Set(k, val)
			continue
		}
		skip := false
		for _, f := range fields {
			if k == f {
				skip = true
				break
			}
		}
		if skip {
			continue
		}
		val, _ := rec.Get(k)
		out.Set(k, val)
	}
	for _, cn := range order {
		acc := groups[cn]
		name := cn
		if len(v.collapse) == 0 && v.output != "" {
			name = v.output
		}
		for _, spec := range v.specs {
			out.Set(name+"_"+spec.name, stats1Value(spec, acc, v.interpolated))
		}
	}
	return []*Record{out}, nil
}

func (v *mergeFieldsVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *mergeFieldsVerb) Close() error                    { return nil }

