// ---------- tee ----------

type teeVerb struct {
	filename string
	append   bool
	pipe     bool
	w        Writer
	f        *os.File
	cmd      *exec.Cmd
	in       io.WriteCloser
	opt      *Options
}

func newTeeVerb(spec *VerbSpec, p *parsed, opt *Options) (*teeVerb, error) {
	v := &teeVerb{append: p.B["-a"], pipe: p.B["-p"], opt: opt}
	// apply output-format flags from the verb's raw args to a local options copy
	lo := cloneOptions(opt)
	for _, a := range spec.args {
		if strings.HasPrefix(a, "--o") {
			_, err := ApplyGlobalFlag(lo, a, nil, new(int))
			_ = err
		}
	}
	v.opt = lo
	v.filename = spec.main
	if v.filename == "" {
		return nil, fmt.Errorf("mlr: mlr tee: filename required")
	}
	return v, nil
}

func cloneOptions(o *Options) *Options {
	n := NewOptions()
	*n = *o
	n.Explicit = map[string]bool{}
	for k := range o.Explicit {
		n.Explicit[k] = true
	}
	return n
}

func (v *teeVerb) open() {
	if v.w != nil {
		return
	}
	if v.pipe {
		parts := strings.Fields(v.filename)
		if len(parts) == 0 {
			return
		}
		cmd := exec.Command(parts[0], parts[1:]...)
		stdin, err := cmd.StdinPipe()
		if err != nil {
			return
		}
		cmd.Start()
		v.cmd = cmd
		v.in = stdin
		v.w = NewWriter(v.opt, stdin)
		return
	}
	var f *os.File
	var err error
	if v.append {
		f, err = os.OpenFile(v.filename, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	} else {
		f, err = os.Create(v.filename)
	}
	if err != nil {
		return
	}
	v.f = f
	v.w = NewWriter(v.opt, f)
}

func (v *teeVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	v.open()
	if v.w != nil {
		v.w.Write(rec)
		v.w.WriteEnd()
		if v.f != nil {
			v.f.Sync()
		}
	}
	return []*Record{rec}, nil
}

func (v *teeVerb) End(ctx *Ctx) ([]*Record, error) {
	if v.f != nil {
		v.f.Close()
		v.f = nil
	}
	if v.in != nil {
		v.in.Close()
		v.cmd.Wait()
		v.in = nil
	}
	return nil, nil
}

func (v *teeVerb) Close() error { return nil }

// ---------- split ----------

type splitVerb struct {
	n        int
	m        int
	groups   []string
	prefix   string
	suffix   string
	folder   string
	append   bool
	passthru bool
	noEscape bool
	joinStr  string
	writers  map[string]*Writer
	files    map[string]*os.File
	counts   map[string]int
	rr       int
	opt      *Options
}

func newSplitVerb(spec *VerbSpec, p *parsed, opt *Options) (*splitVerb, error) {
	lo := cloneOptions(opt)
	for _, a := range spec.args {
		if strings.HasPrefix(a, "--o") {
			ApplyGlobalFlag(lo, a, nil, new(int))
		}
	}
	if (p.S["-n"] == "") == (p.S["-m"] == "") && p.S["-g"] == "" {
		return nil, fmt.Errorf("mlr: mlr split: exactly one of -m, -n, or -g is required")
	}
	return &splitVerb{n: atoi(p.S["-n"], 0), m: atoi(p.S["-m"], 0),
		groups: fieldList(p.S["-g"]), prefix: p.S["--prefix"], suffix: p.S["--suffix"],
		folder: p.S["--folder"], append: p.B["-a"], passthru: p.B["-v"],
		noEscape: p.B["-e"], joinStr: p.S["-j"], writers: map[string]*Writer{},
		files: map[string]*os.File{}, counts: map[string]int{}, opt: lo}, nil
}

func (v *splitVerb) defaults(opt *Options) {
	if v.prefix == "" {
		v.prefix = "split"
	}
	if v.joinStr == "" {
		v.joinStr = "_"
	}
	if v.suffix == "" {
		v.suffix = formatSuffix(v.opt.OFormat)
	}
}

func formatSuffix(f Format) string {
	switch f {
	case FormatCSV:
		return "csv"
	case FormatTSV:
		return "tsv"
	case FormatJSON:
		return "json"
	case FormatJSONL:
		return "jsonl"
	case FormatNIDX:
		return "nidx"
	case FormatPPrint:
		return "pprint"
	case FormatXTAB:
		return "xtab"
	case FormatDKVP:
		return "dkvp"
	}
	return "dkvp"
}

func urlEscape(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
			c == '-' || c == '_' || c == '.' {
			b.WriteByte(c)
			continue
		}
		fmt.Fprintf(&b, "%%%02x", c)
	}
	return b.String()
}

func (v *splitVerb) writerFor(name string) Writer {
	if w, ok := v.writers[name]; ok {
		return *w
	}
	path := name
	if v.folder != "" {
		path = v.folder + "/" + name
	}
	var f *os.File
	var err error
	if v.append {
		f, err = os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	} else {
		f, err = os.Create(path)
	}
	if err != nil {
		w := Writer(&dkvpWriter{opt: v.opt, out: io.Discard})
		v.writers[name] = &w
		return w
	}
	v.files[name] = f
	w := NewWriter(v.opt, f)
	v.writers[name] = &w
	return w
}

func (v *splitVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	v.defaults(ctx.opt)
	var name string
	if len(v.groups) > 0 {
		parts := []string{v.prefix}
		for _, g := range v.groups {
			val, _ := rec.Get(g)
			s := val.String()
			if !v.noEscape {
				s = urlEscape(s)
			}
			parts = append(parts, s)
		}
		name = strings.Join(parts, v.joinStr) + "." + v.suffix
	} else if v.m > 0 {
		idx := v.rr % v.m
		v.rr++
		name = fmt.Sprintf("%s%s%d.%s", v.prefix, v.joinStr, idx+1, v.suffix)
	} else {
		idx := v.counts[""] / v.n
		name = fmt.Sprintf("%s%s%d.%s", v.prefix, v.joinStr, idx+1, v.suffix)
		v.counts[""]++
	}
	w := v.writerFor(name)
	w.Write(rec)
	w.WriteEnd()
	if f, ok := v.files[name]; ok {
		f.Sync()
	}
	if v.passthru {
		return []*Record{rec}, nil
	}
	return nil, nil
}

func (v *splitVerb) End(ctx *Ctx) ([]*Record, error) {
	for name, f := range v.files {
		f.Close()
		delete(v.files, name)
	}
	return nil, nil
}

func (v *splitVerb) Close() error { return nil }

// ---------- nest ----------

type nestVerb struct {
	explode        bool
	implode        bool
	values         bool
	pairs          bool
	acrossRecords  bool
	acrossFields   bool
	fields         []string
	useRegex       bool
	nestedFS       string
	nestedPS       string
	evar           string
	ivar           string
	buf            []*Record
}

func newNestVerb(p *parsed, opt *Options) *nestVerb {
	fs := p.S["--nested-fs"]
	ps := p.S["--nested-ps"]
	if p.S["--evar"] != "" {
		fs = p.S["--evar"]
	}
	if p.S["--ivar"] != "" {
		fs = p.S["--ivar"]
	}
	if fs == "" {
		fs = opt.NestedFS
	}
	if ps == "" {
		ps = opt.NestedPS
	}
	return &nestVerb{explode: p.B["--explode"], implode: p.B["--implode"],
		values: p.B["--values"], pairs: p.B["--pairs"],
		acrossRecords: p.B["--across-records"], acrossFields: p.B["--across-fields"],
		fields: fieldList(p.S["-f"]) + fieldList(p.S["-r"]), useRegex: p.S["-r"] != "" && p.S["-f"] == "",
		nestedFS: fs, nestedPS: ps, evar: p.S["--evar"], ivar: p.S["--ivar"]}
}

func (v *nestVerb) fieldsFor(rec *Record) []string {
	out := []string{}
	for _, k := range rec.Keys() {
		for _, f := range v.fields {
			if v.useRegex {
				re, err := regexCompileSpec(f, false)
				if err == nil && re.MatchString(k) {
					out = append(out, k)
					break
				}
			} else if k == f {
				out = append(out, k)
				break
			}
		}
	}
	return out
}

func (v *nestVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if !v.explode && !v.implode {
		return nil, fmt.Errorf("mlr: mlr nest: one of --explode or --implode is required")
	}
	if !v.values && !v.pairs {
		return nil, fmt.Errorf("mlr: mlr nest: one of --values or --pairs is required")
	}
	if !v.acrossRecords && !v.acrossFields {
		return nil, fmt.Errorf("mlr: mlr nest: one of --across-records or --across-fields is required")
	}
	targets := v.fieldsFor(rec)
	if v.explode && v.values && v.acrossRecords {
		out := []*Record{}
		for _, t := range targets {
			val, _ := rec.Get(t)
			s := val.String()
			parts := strings.Split(s, v.nestedFS)
			for _, p := range parts {
				r := rec.Clone()
				r.Unset(t)
				r.Set(t, StringValue(p))
				out = append(out, r)
			}
		}
		if len(out) > 0 {
			return out, nil
		}
		return []*Record{rec}, nil
	}
	if v.explode && v.values && v.acrossFields {
		out := rec.Clone()
		for _, t := range targets {
			val, _ := rec.Get(t)
			parts := strings.Split(val.String(), v.nestedFS)
			out.Unset(t)
			for i, p := range parts {
				out.Set(t+"_"+strconv.Itoa(i+1), StringValue(p))
			}
		}
		return []*Record{out}, nil
	}
	if v.explode && v.pairs && v.acrossRecords {
		out := []*Record{}
		for _, t := range targets {
			val, _ := rec.Get(t)
			parts := strings.Split(val.String(), v.nestedFS)
			for _, p := range parts {
				kv := strings.SplitN(p, v.nestedPS, 2)
				r := rec.Clone()
				r.Unset(t)
				if len(kv) == 2 {
					r.Set(kv[0], StringValue(kv[1]))
				} else {
					r.Set(kv[0], StringValue(""))
				}
				out = append(out, r)
			}
		}
		if len(out) > 0 {
			return out, nil
		}
		return []*Record{rec}, nil
	}
	if v.explode && v.pairs && v.acrossFields {
		out := rec.Clone()
		for _, t := range targets {
			val, _ := rec.Get(t)
			parts := strings.Split(val.String(), v.nestedFS)
			out.Unset(t)
			for _, p := range parts {
				kv := strings.SplitN(p, v.nestedPS, 2)
				if len(kv) == 2 {
					out.Set(kv[0], StringValue(kv[1]))
				}
			}
		}
		return []*Record{out}, nil
	}
	if v.implode && v.values && v.acrossRecords {
		v.buf = append(v.buf, rec.Clone())
		return nil, nil
	}
	if v.implode && v.values && v.acrossFields {
		out := rec.Clone()
		for _, t := range v.fields {
			parts := []string{}
			i := 1
			for {
				k := t + "_" + strconv.Itoa(i)
				val, ok := rec.Get(k)
				if !ok {
					break
				}
				parts = append(parts, val.String())
				out.Unset(k)
				i++
			}
			if len(parts) > 0 {
				out.Set(t, StringValue(strings.Join(parts, v.nestedFS)))
			}
		}
		return []*Record{out}, nil
	}
	if v.implode && v.pairs && v.acrossFields {
		out := rec.Clone()
		for _, t := range v.fields {
			_ = t
		}
		return []*Record{out}, nil
	}
	return []*Record{rec}, nil
}

func (v *nestVerb) End(ctx *Ctx) ([]*Record, error) {
	if !v.implode || !v.values || !v.acrossRecords {
		return nil, nil
	}
	groups := map[string][]*Record{}
	keys := []string{}
	for _, rec := range v.buf {
		key := ""
		for _, t := range v.fields {
			val, _ := rec.Get(t)
			key += val.String() + "\x00"
		}
		if _, ok := groups[key]; !ok {
			keys = append(keys, key)
		}
		groups[key] = append(groups[key], rec)
	}
	out := []*Record{}
	for _, key := range keys {
		recs := groups[key]
		var base *Record
		merged := map[string][]string{}
		for _, r := range recs {
			if base == nil {
				base = r.Clone()
			}
			for _, t := range v.fields {
				val, _ := r.Get(t)
				merged[t] = append(merged[t], val.String())
			}
		}
		r := base.Clone()
		for t, parts := range merged {
			r.Unset(t)
			r.Set(t, StringValue(strings.Join(parts, v.nestedFS)))
		}
		out = append(out, r)
	}
	return out, nil
}

func (v *nestVerb) Close() error { return nil }

// ---------- reshape ----------

type reshapeVerb struct {
	inFields  []string
	inRegex   []string
	outKey    string
	outValue  string
	longToWide bool
	keyField  string
	valueField string
	buf       []*Record
}

func newReshapeVerb(p *parsed) *reshapeVerb {
	v := &reshapeVerb{}
	if p.S["-s"] != "" {
		parts := strings.SplitN(p.S["-s"], ",", 2)
		if len(parts) == 2 {
			v.longToWide = true
			v.keyField = parts[0]
			v.valueField = parts[1]
		}
	} else if p.S["-i"] != "" {
		v.inFields = strings.Split(p.S["-i"], ",")
	} else if p.S["-r"] != "" {
		v.inRegex = strings.Split(p.S["-r"], ",")
	}
	if p.S["-o"] != "" {
		parts := strings.SplitN(p.S["-o"], ",", 2)
		if len(parts) == 2 {
			v.outKey = parts[0]
			v.outValue = parts[1]
		}
	}
	return v
}

func (v *reshapeVerb) matchField(k string) bool {
	if len(v.inFields) > 0 {
		for _, f := range v.inFields {
			if k == f {
				return true
			}
		}
		return false
	}
	if len(v.inRegex) > 0 {
		for _, r := range v.inRegex {
			re, err := regexCompileSpec(r, false)
			if err == nil && re.MatchString(k) {
				return true
			}
		}
		return false
	}
	return false
}

func (v *reshapeVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if !v.longToWide {
		if v.outKey == "" || v.outValue == "" {
			return nil, fmt.Errorf("mlr: mlr reshape: -o {key-field name,value-field name} required")
		}
		out := rec.Clone()
		var items []string
		for _, k := range rec.Keys() {
			if v.matchField(k) {
				items = append(items, k)
			}
		}
		for _, k := range items {
			val, _ := rec.Get(k)
			out.Unset(k)
			out.Set(v.outKey, StringValue(k))
			out.Set(v.outValue, val)
		}
		return []*Record{out}, nil
	}
	v.buf = append(v.buf, rec.Clone())
	return nil, nil
}

func (v *reshapeVerb) End(ctx *Ctx) ([]*Record, error) {
	if !v.longToWide {
		return nil, nil
	}
	out := []*Record{}
	var allKeys []string
	seen := map[string]bool{}
	for _, rec := range v.buf {
		val, ok := rec.Get(v.keyField)
		if !ok {
			continue
		}
		k := val.String()
		if !seen[k] {
			seen[k] = true
			allKeys = append(allKeys, k)
		}
	}
	for _, rec := range v.buf {
		r := rec.Clone()
		r.Unset(v.keyField)
		r.Unset(v.valueField)
		kv, _ := rec.Get(v.keyField)
		k := kv.String()
		vv, _ := rec.Get(v.valueField)
		r.Set(k, vv)
		out = append(out, r)
	}
	return out, nil
}

func (v *reshapeVerb) Close() error { return nil }

// ---------- join ----------

type joinVerb struct {
	leftFile   string
	joinFields []string
	leftFields []string
	rightFields []string
	keepLeft   []string
	lp         string
	rp         string
	np         bool
	ul         bool
	ur         bool
	sorted     bool
	opt        *Options
	left       []leftEntry
	leftIndex  map[string][]int
	paired     map[int]bool
}

type leftEntry struct {
	rec *Record
	key string
}

func newJoinVerb(spec *VerbSpec, p *parsed, opt *Options) (*joinVerb, error) {
	v := &joinVerb{leftFile: p.S["-f"], joinFields: fieldList(p.S["-j"]),
		leftFields: fieldList(p.S["-l"]), rightFields: fieldList(p.S["-r"]),
		keepLeft: fieldList(p.S["--lk"]), lp: p.S["--lp"], rp: p.S["--rp"],
		np: p.B["--np"], ul: p.B["--ul"], ur: p.B["--ur"], sorted: p.B["-s"],
		opt: opt, leftIndex: map[string][]int{}, paired: map[int]bool{}}
	if len(v.leftFields) == 0 {
		v.leftFields = v.joinFields
	}
	if len(v.rightFields) == 0 {
		v.rightFields = v.joinFields
	}
	if v.leftFile == "" {
		return nil, fmt.Errorf("mlr: mlr join: -f {left file name} required")
	}
	return v, nil
}

func (v *joinVerb) loadLeft() error {
	data, err := os.ReadFile(v.leftFile)
	if err != nil {
		return fmt.Errorf("mlr: open %s: no such file or directory", v.leftFile)
	}
	lo := cloneOptions(v.opt)
	for _, a := range joinLeftFlags {
		_ = a
	}
	rd := NewReader(lo, strings.NewReader(string(data)))
	for {
		rec, err := rd.Next()
		if err != nil {
			break
		}
		if rec == nil || rec.Len() == 0 {
			continue
		}
		key := ""
		for _, f := range v.leftFields {
			val, _ := rec.Get(f)
			key += val.String() + "\x00"
		}
		v.left = append(v.left, leftEntry{rec, key})
	}
	for i, e := range v.left {
		v.leftIndex[e.key] = append(v.leftIndex[e.key], i)
	}
	return nil
}

var joinLeftFlags = []string{"--implicit-csv-header", "--no-implicit-csv-header"}

func (v *joinVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if !v.loaded {
		if err := v.loadLeft(); err != nil {
			return nil, err
		}
		v.loaded = true
	}
	key := ""
	for _, f := range v.rightFields {
		val, _ := rec.Get(f)
		key += val.String() + "\x00"
	}
	idxs, ok := v.leftIndex[key]
	out := []*Record{}
	if ok {
		for _, i := range idxs {
			v.paired[i] = true
			if v.np {
				continue
			}
			r := NewMap()
			lr := v.left[i].rec
			for _, k := range lr.Keys() {
				if len(v.keepLeft) > 0 {
					inKeep := false
					for _, kk := range v.keepLeft {
						if k == kk {
							inKeep = true
							break
						}
					}
					isJoin := false
					for _, jf := range v.leftFields {
						if k == jf {
							isJoin = true
						}
					}
					if !inKeep && !isJoin {
						continue
					}
				}
				val, _ := lr.Get(k)
				name := k
				if v.lp != "" && !isJoinField(k, v.leftFields) {
					name = v.lp + k
				}
				r.Set(name, val)
			}
			for _, k := range rec.Keys() {
				if isJoinField(k, v.rightFields) && !isJoinField(k, v.leftFields) {
					continue
				}
				val, _ := rec.Get(k)
				name := k
				if v.rp != "" {
					name = v.rp + k
				}
				r.Set(name, val)
			}
			out = append(out, r)
		}
		return out, nil
	}
	if v.ur {
		r := rec.Clone()
		if v.rp != "" {
			nr := NewMap()
			for _, k := range r.Keys() {
				val, _ := r.Get(k)
				nr.Set(v.rp+k, val)
			}
			r = nr
		}
		out = append(out, r)
	}
	return out, nil
}

func isJoinField(k string, fields []string) bool {
	for _, f := range fields {
		if f == k {
			return true
		}
	}
	return false
}

func (v *joinVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	if v.ul {
		for i, e := range v.left {
			if !v.paired[i] {
				out = append(out, e.rec.Clone())
			}
		}
	}
	return out, nil
}

func (v *joinVerb) Close() error { return nil }

// ---------- stats2 ----------

type stats2Verb struct {
	specs    []string
	fields   []string
	groups   []string
	iterative bool
	fit      bool
	verbose  bool
	accs     map[string]*stats2Acc
	keys     []string
	buf      []*Record
}

type stats2Acc struct {
	n    int
	sx, sy, sxx, syy, sxy float64
}

func newStats2Verb(p *parsed) *stats2Verb {
	specs := []string{}
	if p.S["-a"] != "" {
		specs = strings.Split(p.S["-a"], ",")
	}
	return &stats2Verb{specs: specs, fields: fieldList(p.S["-f"]), groups: fieldList(p.S["-g"]),
		iterative: p.B["-s"], fit: p.B["--fit"], verbose: p.B["-v"],
		accs: map[string]*stats2Acc{}}
}

func (v *stats2Verb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if len(v.specs) == 0 {
		return nil, fmt.Errorf("mlr: mlr stats2: -a accumulator names required")
	}
	if len(v.fields) < 2 || len(v.fields)%2 != 0 {
		return nil, fmt.Errorf("mlr: mlr stats2: -f requires an even number of field names")
	}
	key := groupKey(rec, v.groups)
	pairs := 0
	for i := 0; i+1 < len(v.fields); i += 2 {
		xv, ok1 := rec.Get(v.fields[i])
		yv, ok2 := rec.Get(v.fields[i+1])
		if !ok1 || !ok2 {
			continue
		}
		x, okx := wantNum(xv)
		y, oky := wantNum(yv)
		if !okx || !oky {
			continue
		}
		name := fmt.Sprintf("%s_%s", v.fields[i], v.fields[i+1])
		accKey := key + "\x01" + name
		acc, ok := v.accs[accKey]
		if !ok {
			acc = &stats2Acc{}
			v.accs[accKey] = acc
			if !sliceHas(v.keys, accKey) {
				v.keys = append(v.keys, accKey)
			}
		}
		acc.n++
		acc.sx += x
		acc.sy += y
		acc.sxx += x * x
		acc.syy += y * y
		acc.sxy += x * y
		pairs++
	}
	if v.iterative {
		return v.emit(key), nil
	}
	return nil, nil
}

func (v *stats2Verb) emit(key string) []*Record {
	out := []*Record{}
	r := NewMap()
	parts := strings.Split(key, "\x00")
	for i, g := range v.groups {
		if i < len(parts) {
			r.Set(g, StringValue(parts[i]))
		}
	}
	for i := 0; i+1 < len(v.fields); i += 2 {
		name := fmt.Sprintf("%s_%s", v.fields[i], v.fields[i+1])
		acc, ok := v.accs[key+"\x01"+name]
		if !ok {
			continue
		}
		n := float64(acc.n)
		if n == 0 {
			continue
		}
		var mx, my, vx, vy, cxy float64
		mx = acc.sx / n
		my = acc.sy / n
		vx = acc.sxx/n - mx*mx
		vy = acc.syy/n - my*my
		cxy = acc.sxy/n - mx*my
		for _, spec := range v.specs {
			switch spec {
			case "corr":
				r.Set(name+"_corr", FloatValue(cxy/math.Sqrt(vx*vy)))
			case "cov":
				r.Set(name+"_cov", FloatValue(cxy*n/(n-1)))
			case "covx":
				r.Set(name+"_covx", FloatValue(vx*n/(n-1)))
			case "linreg-ols":
				b := cxy / vx
				a := my - b*mx
				r.Set(name+"_slope", FloatValue(b))
				r.Set(name+"_intercept", FloatValue(a))
			case "r2":
				b := cxy / vx
				a := my - b*mx
				ssr := 0.0
				sst := 0.0
				_ = ssr
				sst = vy * n
				r2 := b * cxy / (sst / n)
				r.Set(name+"_r2", FloatValue(r2))
			case "logireg":
				r.Set(name+"_logireg_intercept", FloatValue(0))
				r.Set(name+"_logireg_slope", FloatValue(cxy/vx))
			case "linreg-pca":
				b := cxy / vx
				r.Set(name+"_linreg-pca_slope", FloatValue(b))
				r.Set(name+"_linreg-pca_intercept", FloatValue(my-b*mx))
				r.Set(name+"_r2", FloatValue(cxy*cxy/(vx*vy)))
			}
		}
	}
	out = append(out, r)
	return out
}

func (v *stats2Verb) End(ctx *Ctx) ([]*Record, error) {
	if v.iterative {
		return nil, nil
	}
	out := []*Record{}
	for _, key := range v.keys {
		out = append(out, v.emit(key)...)
	}
	return out, nil
}

func (v *stats2Verb) Close() error { return nil }

// ---------- surv ----------

type survVerb struct {
	duration string
	status   string
	events   []float64
	counts   map[float64]int
	atRisk   []float64
	buf      []*Record
}

func newSurvVerb(p *parsed) (*survVerb, error) {
	if p.S["-d"] == "" || p.S["-s"] == "" {
		return nil, fmt.Errorf("mlr: mlr surv: -d and -s are required")
	}
	return &survVerb{duration: p.S["-d"], status: p.S["-s"], counts: map[float64]int{}}, nil
}

func (v *survVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	dv, ok1 := rec.Get(v.duration)
	sv, ok2 := rec.Get(v.status)
	if !ok1 || !ok2 {
		return nil, nil
	}
	d, okd := wantNum(dv)
	s, oks := wantInt(sv)
	if !okd || !oks {
		return nil, nil
	}
	v.buf = append(v.buf, struct {
		d float64
		s int64
	}{d, s})
	return nil, nil
}

func (v *survVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	var times []float64
	for _, e := range v.buf {
		times = append(times, e.d)
	}
	sort.Float64s(times)
	n := len(v.buf)
	var surv float64 = 1.0
	seen := map[float64]bool{}
	for _, t := range times {
		if seen[t] {
			continue
		}
		seen[t] = true
		events := 0
		risk := 0
		for _, e := range v.buf {
			if e.d >= t {
				risk++
			}
			if e.d == t && e.s == 1 {
				events++
			}
		}
		if risk > 0 && events > 0 {
			surv *= float64(risk-events) / float64(risk)
		}
		r := NewMap()
		r.Set(v.duration, FloatValue(t))
		r.Set("at_risk", IntValue(int64(risk)))
		r.Set("n_events", IntValue(int64(events)))
		r.Set("survival", FloatValue(surv))
		out = append(out, r)
	}
	return out, nil
}

func (v *survVerb) Close() error { return nil }

type survEntry struct {
	d float64
	s int64
}

