// ---------- fraction ----------

type fractionVerb struct {
	fields []string
	groups []string
	percent bool
	cumulative bool
	sums map[string]float64
	buf  []*Record
	keys []string
}

func newFractionVerb(p *parsed) *fractionVerb {
	return &fractionVerb{fields: fieldList(p.S["-f"]), groups: fieldList(p.S["-g"]),
		percent: p.B["-p"], cumulative: p.B["-c"], sums: map[string]float64{}}
}

func (v *fractionVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	key := groupKey(rec, v.groups)
	v.buf = append(v.buf, rec.Clone())
	for _, f := range v.fields {
		val, ok := rec.Get(f)
		if !ok || !val.IsNumber() {
			continue
		}
		gk := key + "\x01" + f
		if _, ok := v.sums[gk]; !ok {
			v.sums[gk] = 0
			v.keys = append(v.keys, gk)
		}
		v.sums[gk] += toFloat(val)
	}
	return nil, nil
}

func (v *fractionVerb) End(ctx *Ctx) ([]*Record, error) {
	running := map[string]float64{}
	out := []*Record{}
	for _, rec := range v.buf {
		key := groupKey(rec, v.groups)
		r := rec.Clone()
		for _, f := range v.fields {
			val, ok := rec.Get(f)
			if !ok || !val.IsNumber() {
				continue
			}
			gk := key + "\x01" + f
			total := v.sums[gk]
			x := toFloat(val)
			name := f + "_fraction"
			if v.percent {
				name = f + "_percent"
			}
			if v.cumulative {
				name = f + "_cumulative_fraction"
				if v.percent {
					name = f + "_cumulative_percent"
				}
				running[gk] += x
				if total != 0 {
					r.Set(name, FloatValue(running[gk]/total))
				} else {
					r.Set(name, StringValue(""))
				}
				continue
			}
			if total != 0 {
				q := x / total
				if v.percent {
					q *= 100
				}
				r.Set(name, FloatValue(q))
			} else {
				r.Set(name, StringValue(""))
			}
		}
		out = append(out, r)
	}
	return out, nil
}

func (v *fractionVerb) Close() error { return nil }
