		varName = target.Name
	case "oosidx":
		varName = strVal(rt.eval(target.Left))
	}
	var names []Value
	if len(n.List) > 1 {
		for _, e := range n.List[1:] {
			names = append(names, rt.eval(e))
		}
	}
	v := rt.eval(target)
	rt.emitValue(v, names, kind, n.Third, varName)
}''')
