new='''func (v *flattenVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		if len(v.fields) > 0 {
			found := false
			for _, f := range v.fields {
				if k == f {
					found = true
					break
				}
			}
			if !found {
				out.Set(k, val)
				continue
			}
		}
		if v.un {
			if !strings.Contains(k, v.sep) {
				out.Set(k, val)
				continue
			}
			parts := strings.Split(k, v.sep)
			root := NewMap()
			cur := root
			for i, pp := range parts {
				if i == len(parts)-1 {
					cur.Set(pp, val)
				} else {
					if e, ok := cur.Get(pp); ok && e.Kind == KindMap {
						cur = e.M
					} else {
						nm := NewMap()
						cur.Set(pp, MapValue(nm))
						cur = nm
					}
				}
			}
			name := parts[0]
			if len(parts) == 1 {
				out.Set(name, val)
			} else {
				out.Set(name, MapValue(root.Get(name).M))
			}
			continue
		}
		if val.Kind != KindMap && val.Kind != KindArray {
			out.Set(k, val)
			continue
		}
		flat := NewMap()
		flattenValueInto("", v.sep, val, flat)
		for _, kk := range flat.Keys() {
			fv, _ := flat.Get(kk)
			if kk == "" {
				out.Set(k, fv)
				continue
			}
			out.Set(k+v.sep+kk, fv)
		}
	}
	return []*Record{out}, nil
}

