package main

import (
	"fmt"
	"os"
	"strings"
)

// runAuxent handles Miller's standalone auxiliary executables.
func runAuxent(name string, args []string) int {
	switch name {
	case "aux-list":
		fmt.Println("aux-list")
		fmt.Println("hex")
		fmt.Println("lecat")
		fmt.Println("termcvt")
		fmt.Println("unhex")
		return 0
	case "hex":
		return auxHex(args, false)
	case "unhex":
		return auxHex(args, true)
	case "lecat":
		return auxLECat(args)
	case "termcvt":
		return auxTermcvt(args)
	}
	return -1
}

func auxInput(args []string, cb func([]byte)) int {
	if len(args) == 0 {
		data, _ := readAllStdin()
		cb(data)
		return 0
	}
	for _, fn := range args {
		if fn == "-" {
			data, _ := readAllStdin()
			cb(data)
			continue
		}
		data, err := os.ReadFile(fn)
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr: open %s: no such file or directory\n", fn)
			return 1
		}
		cb(data)
	}
	return 0
}

func auxHex(args []string, decode bool) int {
	return auxInput(args, func(data []byte) {
		if decode {
			var out []byte
			hexs := strings.Map(func(r rune) rune {
				if (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F') {
					return r
				}
				return -1
			}, string(data))
			for i := 0; i+1 < len(hexs); i += 2 {
				var b byte
				fmt.Sscanf(hexs[i:i+2], "%02x", &b)
				out = append(out, b)
			}
			os.Stdout.Write(out)
			return
		}
		var b strings.Builder
		for i := 0; i < len(data); i += 16 {
			fmt.Fprintf(&b, "%08x  ", i)
			chunk := data[i:min(i+16, len(data))]
			for j := 0; j < 16; j++ {
				if j < len(chunk) {
					fmt.Fprintf(&b, "%02x ", chunk[j])
				} else {
					b.WriteString("   ")
				}
				if j == 7 {
					b.WriteString(" ")
				}
			}
			b.WriteString(" |")
			for _, c := range chunk {
				if c >= 32 && c < 127 {
					b.WriteByte(c)
				} else {
					b.WriteByte('.')
				}
			}
			b.WriteString("|\n")
		}
		fmt.Print(b.String())
	})
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func auxLECat(args []string) int {
	return auxInput(args, func(data []byte) {
		for _, c := range data {
			fmt.Printf("%02x\n", c)
		}
	})
}

func auxTermcvt(args []string) int {
	return auxInput(args, func(data []byte) {
		var b strings.Builder
		for i := 0; i < len(data); i++ {
			c := data[i]
			switch c {
			case 0x1b:
				b.WriteString("\\x1b")
			default:
				b.WriteByte(c)
			}
		}
		fmt.Print(b.String())
	})
}
