func (v *countDistinctVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if v.unlashed {
		for _, f := range v.fieldNames {
			val, _ := rec.Get(f)
			k := f + "\\x00" + val.String()
			if _, ok := v.countMap[k]; !ok {
				v.vals[k] = []Value{val}
			}
			v.countMap[k]++
		}
		return nil, nil
	}
	if v.allRecords {
		var b strings.Builder
		for _, k := range rec.Keys() {
			val, _ := rec.Get(k)
			b.WriteString(val.String())
			b.WriteByte(0)
		}
		key := b.String()
		if _, ok := v.countMap[key]; !ok {
			v.seen = append(v.seen, rec.Clone())
		}
		v.countMap[key]++
		return nil, nil
	}
	keys, vals := v.keysFor(rec)
	var b strings.Builder
	list := []Value{}
	names := []string{}
	for _, k := range keys {
		val := vals[k]
		b.WriteString(val.String())
		b.WriteByte(0)
		list = append(list, val)
		names = append(names, k)
	}
	key := b.String()
	if _, ok := v.countMap[key]; !ok {
		v.vals[key] = list
		v.names[key] = names
	}
	v.countMap[key]++
	return nil, nil
}

func (v *countDistinctVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	name := v.oName
	if name == "" {
		name = "count"
	}
	if v.nOnly {
		r := NewMap()
		r.Set(name, IntValue(int64(len(v.countMap))))
		return []*Record{r}, nil
	}
	if v.allRecords {
		for _, rec := range v.seen {
			var b strings.Builder
			for _, k := range rec.Keys() {
				val, _ := rec.Get(k)
				b.WriteString(val.String())
				b.WriteByte(0)
			}
			r := rec.Clone()
			r.Set(name, IntValue(v.countMap[b.String()]))
			out = append(out, r)
		}
		return out, nil
	}
	for _, key := range sortedIntKeys(v.countMap) {
		r := NewMap()
		list := v.vals[key]
		names := v.names[key]
		if v.unlashed {
			parts := strings.SplitN(key, "\\x00", 2)
			if len(parts) == 2 && len(list) > 0 {
				r.Set(parts[0], list[0])
			}
			r.Set(name, IntValue(v.countMap[key]))
			out = append(out, r)
			continue
		}
		for i, k := range names {
			if i < len(list) {
				r.Set(k, list[i])
			}
		}
		r.Set(name, IntValue(v.countMap[key]))
		out = append(out, r)
	}
	return out, nil
}

