type uniqVerb struct {
	distinctVerb
	countMap map[string]int64
	vals     map[string][]Value
	names    map[string][]string
	keys     []string
	recSeen  map[string]*Record
	recKeys  []string
}

func newUniqVerb(p *parsed) *uniqVerb {
	return &uniqVerb{distinctVerb: *newDistinctVerb(p, fieldList(p.S["-g"])),
		countMap: map[string]int64{}, vals: map[string][]Value{}, names: map[string][]string{},
		recSeen: map[string]*Record{}}
}

func (v *uniqVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if v.allRecords {
		var b strings.Builder
		for _, k := range rec.Keys() {
			val, _ := rec.Get(k)
			b.WriteString(val.String())
			b.WriteByte(0)
		}
		key := b.String()
		if _, ok := v.countMap[key]; !ok {
			v.recSeen[key] = rec.Clone()
			v.recKeys = append(v.recKeys, key)
		}
		v.countMap[key]++
		return nil, nil
	}
	var list []Value
	var names []string
	var b strings.Builder
	if len(v.excluded) > 0 {
		for _, k := range rec.Keys() {
			skip := false
			for _, x := range v.excluded {
				if k == x {
					skip = true
					break
				}
			}
			if skip {
				continue
			}
			val, _ := rec.Get(k)
			b.WriteString(val.String())
			b.WriteByte(0)
			list = append(list, val)
			names = append(names, k)
		}
	} else {
		fields := v.groupFields
		if len(fields) == 0 {
			fields = v.fieldNames
		}
		if len(fields) == 0 {
			fields = rec.Keys()
		}
		for _, f := range fields {
			val, ok := rec.Get(f)
			if !ok {
				val = NullValue()
			}
			b.WriteString(val.String())
			b.WriteByte(0)
			list = append(list, val)
			names = append(names, f)
		}
	}
	key := b.String()
	if _, ok := v.countMap[key]; !ok {
		v.vals[key] = list
		v.names[key] = names
		v.keys = append(v.keys, key)
	}
	v.countMap[key]++
	return nil, nil
}

func (v *uniqVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	name := v.oName
	if name == "" {
		name = "count"
	}
	if v.nOnly {
		r := NewMap()
		r.Set(name, IntValue(int64(len(v.countMap))))
		return []*Record{r}, nil
	}
	if v.allRecords {
		for _, key := range v.recKeys {
			r := v.recSeen[key].Clone()
			if v.showCounts {
				r.Set(name, IntValue(v.countMap[key]))
			}
			out = append(out, r)
		}
		return out, nil
	}
	for _, key := range v.keys {
		r := NewMap()
		list := v.vals[key]
		names := v.names[key]
		for i, f := range names {
			if i < len(list) {
				r.Set(f, list[i])
			}
		}
		if v.showCounts {
			r.Set(name, IntValue(v.countMap[key]))
		}
		out = append(out, r)
	}
	return out, nil
}

func (v *uniqVerb) Close() error { return nil }

