		val, ok := rec.Get(v.useF)
		if !ok {
			return nil, nil
		}
		count = int(toInt(val))
	}
	if count < 0 {
		count = 0
	}
	out := []*Record{}
	for i := 0; i < count; i++ {
		out = append(out, rec.Clone())
	}
	return out, nil
}

