// ---------- altkv ----------

type altkvVerb struct{}

func (v *altkvVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	items := []string{}
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		s := val.String()
		if s == "" {
			continue
		}
		items = append(items, strings.Split(s, ctx.opt.IFS)...)
	}
	out := NewMap()
	for i := 0; i+1 < len(items); i += 2 {
		out.Set(items[i], StringValue(items[i+1]))
	}
	if len(items)%2 == 1 {
		out.Set(strconv.Itoa(len(items)), StringValue(items[len(items)-1]))
	}
	return []*Record{out}, nil
}

func (v *altkvVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *altkvVerb) Close() error                    { return nil }

// ---------- case / clean-whitespace / unspace ----------

type caseVerb struct {
	keysOnly bool
	valsOnly bool
	fields   []string
	upper    bool
	lower    bool
	sentence bool
	title    bool
}

func newCaseVerb(p *parsed) *caseVerb {
	return &caseVerb{keysOnly: p.B["-k"], valsOnly: p.B["-v"], fields: fieldList(p.S["-f"]),
		upper: p.B["-u"], lower: p.B["-l"], sentence: p.B["-s"], title: p.B["-t"]}
}

func caseStr(s string, v *caseVerb) string {
	if v.upper {
		return strings.ToUpper(s)
	}
	if v.lower {
		return strings.ToLower(s)
	}
	if v.sentence {
		return upperFirst(strings.ToLower(s))
	}
	if v.title {
		words := strings.Split(s, " ")
		for i, w := range words {
			words[i] = upperFirst(strings.ToLower(w))
		}
		return strings.Join(words, " ")
	}
	return s
}

func upperFirst(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	r[0] = []rune(strings.ToUpper(string(r[0])))[0]
	return string(r)
}

func (v *caseVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		doKey := true
		doVal := true
		if v.keysOnly {
			doVal = false
		}
		if v.valsOnly {
			doKey = false
		}
		if len(v.fields) > 0 {
			found := false
			for _, f := range v.fields {
				if k == f {
					found = true
					break
				}
			}
			if !found {
				doKey = false
				doVal = false
			}
		}
		nk := k
		nv := val
		if doKey {
			nk = caseStr(k, v)
		}
		if doVal {
			nv = StringValue(caseStr(val.String(), v))
		}
		out.Set(nk, nv)
	}
	return []*Record{out}, nil
}

func (v *caseVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *caseVerb) Close() error                    { return nil }

type cleanWhitespaceVerb struct{ keysOnly, valsOnly bool }

func newCleanWhitespaceVerb(p *parsed) *cleanWhitespaceVerb {
	return &cleanWhitespaceVerb{keysOnly: p.B["-k"], valsOnly: p.B["-v"]}
}

func cleanWhitespace(s string) string {
	s = strings.TrimSpace(s)
	fields := strings.Fields(s)
	return strings.Join(fields, " ")
}

func (v *cleanWhitespaceVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		nk := k
		nv := val
		if !v.valsOnly {
			nk = cleanWhitespace(k)
		}
		if !v.keysOnly {
			nv = StringValue(cleanWhitespace(val.String()))
		}
		out.Set(nk, nv)
	}
	return []*Record{out}, nil
}

func (v *cleanWhitespaceVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *cleanWhitespaceVerb) Close() error                    { return nil }

type unspaceVerb struct {
	filler              string
	keysOnly, valsOnly  bool
	fields              []string
}

func newUnspaceVerb(p *parsed) *unspaceVerb {
	f := p.S["-f"]
	if f == "" {
		f = "_"
	}
	return &unspaceVerb{filler: f, keysOnly: p.B["-k"], valsOnly: p.B["-v"], fields: fieldList(p.S["-f"])}
}

func (v *unspaceVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		inField := len(v.fields) == 0
		for _, f := range v.fields {
			if k == f {
				inField = true
			}
		}
		nk := k
		nv := val
		if !v.valsOnly && inField {
			nk = strings.ReplaceAll(k, " ", v.filler)
		}
		if !v.keysOnly && inField {
			nv = StringValue(strings.ReplaceAll(val.String(), " ", v.filler))
		}
		out.Set(nk, nv)
	}
	return []*Record{out}, nil
}

func (v *unspaceVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *unspaceVerb) Close() error                    { return nil }

// ---------- decimate / gap ----------

type decimateVerb struct {
	everyN    bool
	everyLast bool
	groups    []string
	n         int
	counts    map[string]int64
}

func newDecimateVerb(p *parsed) *decimateVerb {
	return &decimateVerb{everyN: p.B["-b"], everyLast: p.B["-e"] || !p.B["-b"],
		groups: fieldList(p.S["-g"]), n: atoi(p.S["-n"], 10), counts: map[string]int64{}}
}

func (v *decimateVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	key := groupKey(rec, v.groups)
	v.counts[key]++
	c := v.counts[key]
	if v.n <= 0 {
		return nil, nil
	}
	if v.everyN {
		if c%int64(v.n) == 1 {
			return []*Record{rec}, nil
		}
		return nil, nil
	}
	if c%int64(v.n) == 0 {
		return []*Record{rec}, nil
	}
	return nil, nil
}

func (v *decimateVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *decimateVerb) Close() error                    { return nil }

type gapVerb struct {
	groups  []string
	n       int
	count   int64
	last    string
	hasLast bool
}

func newGapVerb(p *parsed) *gapVerb {
	return &gapVerb{groups: fieldList(p.S["-g"]), n: atoi(p.S["-n"], 0)}
}

func (v *gapVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	if len(v.groups) > 0 {
		key := groupKey(rec, v.groups)
		if v.hasLast && key != v.last {
			out = append(out, NewMap())
		}
		v.last = key
		v.hasLast = true
		return out, nil
	}
	if v.n <= 0 {
		return out, nil
	}
	v.count++
	if v.count%int64(v.n) == 0 {
		out = append(out, NewMap())
	}
	return out, nil
}

func (v *gapVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *gapVerb) Close() error                    { return nil }

// ---------- fill-down / fill-empty ----------

type fillDownVerb struct {
	fields       []string
	all          bool
	onlyIfAbsent bool
	last         map[string]Value
}

func newFillDownVerb(p *parsed) *fillDownVerb {
	return &fillDownVerb{fields: fieldList(p.S["-f"]), all: p.B["--all"],
		onlyIfAbsent: p.B["-a"] || p.B["--only-if-absent"], last: map[string]Value{}}
}

func (v *fillDownVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	var fields []string
	if v.all {
		fields = rec.Keys()
	} else {
		fields = v.fields
	}
	for _, f := range fields {
		val, ok := out.Get(f)
		if ok {
			if !v.onlyIfAbsent && val.Kind == KindString && val.S == "" {
				if last, ok2 := v.last[f]; ok2 {
					out.Set(f, last)
				}
				continue
			}
			v.last[f] = val
			continue
		}
		if last, ok2 := v.last[f]; ok2 {
			out.Set(f, last)
		}
	}
	return []*Record{out}, nil
}

func (v *fillDownVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *fillDownVerb) Close() error                    { return nil }

type fillEmptyVerb struct{ fill string }

func newFillEmptyVerb(p *parsed, o *Options) *fillEmptyVerb {
	return &fillEmptyVerb{fill: p.S["-v"]}
}

func (v *fillEmptyVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		if val.Kind == KindString && val.S == "" {
			if v.fill == "" {
				out.Set(k, StringValue("N/A"))
			} else {
				out.Set(k, inferValue(v.fill, ctx.opt))
			}
		}
	}
	return []*Record{out}, nil
}

func (v *fillEmptyVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *fillEmptyVerb) Close() error                    { return nil }

