// ---------- having-fields ----------

type havingFieldsVerb struct {
	atLeast   []string
	atMost    []string
	whichAre  []string
	allMatch  string
	anyMatch  string
	noneMatch string
}

func newHavingFieldsVerb(p *parsed) *havingFieldsVerb {
	return &havingFieldsVerb{
		atLeast:   fieldList(p.S["--at-least"]),
		atMost:    fieldList(p.S["--at-most"]),
		whichAre:  fieldList(p.S["--which-are"]),
		allMatch:  p.S["--all-matching"],
		anyMatch:  p.S["--any-matching"],
		noneMatch: p.S["--none-matching"],
	}
}

func (v *havingFieldsVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	ok := true
	for _, f := range v.atLeast {
		if !rec.Has(f) {
			ok = false
		}
	}
	if len(v.atMost) > 0 {
		for _, k := range rec.Keys() {
			found := false
			for _, f := range v.atMost {
				if k == f {
					found = true
					break
				}
			}
			if !found {
				ok = false
			}
		}
	}
	if len(v.whichAre) > 0 {
		if len(rec.Keys()) != len(v.whichAre) {
			ok = false
		} else {
			for _, k := range rec.Keys() {
				found := false
				for _, f := range v.whichAre {
					if k == f {
						found = true
						break
					}
				}
				if !found {
					ok = false
				}
			}
		}
	}
	if v.allMatch != "" {
		re, err := regexCompileSpec(v.allMatch, false)
		if err == nil {
			for _, k := range rec.Keys() {
				if !re.MatchString(k) {
					ok = false
				}
			}
		}
	}
	if v.anyMatch != "" {
		re, err := regexCompileSpec(v.anyMatch, false)
		if err == nil {
			found := false
			for _, k := range rec.Keys() {
				if re.MatchString(k) {
					found = true
					break
				}
			}
			if !found {
				ok = false
			}
		}
	}
	if v.noneMatch != "" {
		re, err := regexCompileSpec(v.noneMatch, false)
		if err == nil {
			for _, k := range rec.Keys() {
				if re.MatchString(k) {
					ok = false
					break
				}
			}
		}
	}
	if !ok {
		return nil, nil
	}
	return []*Record{rec}, nil
}

func (v *havingFieldsVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *havingFieldsVerb) Close() error                    { return nil }

// ---------- nothing / check / skip-trivial-records ----------

type nothingVerb struct{}

func (v *nothingVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *nothingVerb) End(ctx *Ctx) ([]*Record, error)                  { return nil, nil }
func (v *nothingVerb) Close() error                                     { return nil }

type checkVerb struct{ warnings int }

func (v *checkVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	for _, k := range rec.Keys() {
		if k == "" {
			fmt.Fprintf(os.Stderr, "mlr: mlr check: empty key in record %d\n", ctx.NR)
			v.warnings++
		}
	}
	return nil, nil
}

func (v *checkVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *checkVerb) Close() error                    { return nil }

type skipTrivialVerb struct{}

func (v *skipTrivialVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	if rec.Len() == 0 {
		return nil, nil
	}
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		if val.String() != "" {
			return []*Record{rec}, nil
		}
	}
	return nil, nil
}

func (v *skipTrivialVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *skipTrivialVerb) Close() error                    { return nil }

// ---------- regularize / sort-within-records ----------

type regularizeVerb struct{}

func (v *regularizeVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	keys := append([]string{}, rec.Keys()...)
	sort.Strings(keys)
	out := NewMap()
	for _, k := range keys {
		val, _ := rec.Get(k)
		out.Set(k, val)
	}
	return []*Record{out}, nil
}

func (v *regularizeVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *regularizeVerb) Close() error                    { return nil }

type sortWithinRecordsVerb struct{ recursive bool }

func (v *sortWithinRecordsVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := sortValueKeys(MapValue(rec), v.recursive)
	if out.Kind == KindMap {
		return []*Record{out.M}, nil
	}
	return []*Record{rec}, nil
}

func sortValueKeys(v Value, recursive bool) Value {
	switch v.Kind {
	case KindMap:
		keys := append([]string{}, v.M.Keys()...)
		sort.Strings(keys)
		m := NewMap()
		for _, k := range keys {
			val, _ := v.M.Get(k)
			if recursive {
				val = sortValueKeys(val, true)
			}
			m.Set(k, val)
		}
		return MapValue(m)
	case KindArray:
		a := []Value{}
		for _, e := range v.A {
			if recursive {
				a = append(a, sortValueKeys(e, true))
			} else {
				a = append(a, e)
			}
		}
		return Value{Kind: KindArray, A: a}
	}
	return v
}

func (v *sortWithinRecordsVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *sortWithinRecordsVerb) Close() error                    { return nil }

// ---------- sec2gmt / sec2gmtdate ----------

type sec2gmtVerb struct {
	fields []string
	nd     int
	millis bool
	micros bool
	nanos  bool
}

func newSec2GMTVerb(p *parsed, main string) *sec2gmtVerb {
	fields := fieldList(main)
	nd := 0
	for i := 1; i <= 9; i++ {
		if p.B["-"+strconv.Itoa(i)] {
			nd = i
		}
	}
	return &sec2gmtVerb{fields: fields, nd: nd, millis: p.B["--millis"], micros: p.B["--micros"], nanos: p.B["--nanos"]}
}

func formatGMT(secs float64, nd int) string {
	whole := math.Floor(secs)
	frac := secs - whole
	t := time.Unix(int64(whole), 0).UTC()
	base := t.Format("2006-01-02T15:04:05")
	if nd <= 0 {
		return base + "Z"
	}
	return base + fmt.Sprintf(".%0*d", nd, int(math.Round(frac*math.Pow(10, float64(nd))))) + "Z"
}

func (v *sec2gmtVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	for _, f := range v.fields {
		val, ok := rec.Get(f)
		if !ok || !val.IsNumber() {
			continue
		}
		secs := toFloat(val)
		if v.millis {
			secs /= 1000.0
		} else if v.micros {
			secs /= 1e6
		} else if v.nanos {
			secs /= 1e9
		}
		out.Set(f, StringValue(formatGMT(secs, v.nd)))
	}
	return []*Record{out}, nil
}

func (v *sec2gmtVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *sec2gmtVerb) Close() error                    { return nil }

type sec2gmtdateVerb struct{ fields []string }

func newSec2GMTDateVerb(p *parsed, main string) *sec2gmtdateVerb {
	fields := fieldList(main)
	if len(fields) == 0 {
		fields = fieldList(p.S["-f"])
	}
	return &sec2gmtdateVerb{fields: fields}
}

func (v *sec2gmtdateVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	for _, f := range v.fields {
		val, ok := rec.Get(f)
		if !ok || !val.IsNumber() {
			continue
		}
		t := time.Unix(int64(math.Floor(toFloat(val))), 0).UTC()
		out.Set(f, StringValue(t.Format("2006-01-02")))
	}
	return []*Record{out}, nil
}

func (v *sec2gmtdateVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *sec2gmtdateVerb) Close() error                    { return nil }

// ---------- seqgen ----------

type seqgenVerb struct {
	name  string
	start float64
	step  float64
	stop  float64
	ints  bool
}

func newSeqgenVerb(p *parsed, o *Options) *seqgenVerb {
	name := p.S["-f"]
	if name == "" {
		name = o.GenFieldName
	}
	start := o.GenStart
	step := o.GenStep
	stop := o.GenStop
	if p.S["--start"] != "" {
		start = atof(p.S["--start"], start)
	}
	if p.S["--step"] != "" {
		step = atof(p.S["--step"], step)
	}
	if p.S["--stop"] != "" {
		stop = atof(p.S["--stop"], stop)
	}
	ints := isIntText(p.S["--start"]) && isIntText(p.S["--step"]) && isIntText(p.S["--stop"])
	return &seqgenVerb{name: name, start: start, step: step, stop: stop, ints: ints}
}

func isIntText(s string) bool {
	if s == "" {
		return true
	}
	if _, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64); err == nil {
		return true
	}
	return false
}

func (v *seqgenVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *seqgenVerb) End(ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	if v.step == 0 && v.start != v.stop {
		return out, nil
	}
	if v.ints {
		s := int64(v.start)
		st := int64(v.step)
		e := int64(v.stop)
		if st > 0 {
			for x := s; x <= e; x += st {
				r := NewMap()
				r.Set(v.name, IntValue(x))
				out = append(out, r)
			}
		} else if st < 0 {
			for x := s; x >= e; x += st {
				r := NewMap()
				r.Set(v.name, IntValue(x))
				out = append(out, r)
			}
		} else {
			r := NewMap()
			r.Set(v.name, IntValue(s))
			out = append(out, r)
		}
		return out, nil
	}
	if v.step > 0 {
		for x := v.start; x <= v.stop+1e-9; x += v.step {
			r := NewMap()
			r.Set(v.name, FloatValue(x))
			out = append(out, r)
		}
	} else {
		for x := v.start; x >= v.stop-1e-9; x += v.step {
			r := NewMap()
			r.Set(v.name, FloatValue(x))
			out = append(out, r)
		}
	}
	return out, nil
}

func (v *seqgenVerb) Close() error { return nil }

// ---------- repeat ----------

type repeatVerb struct {
	n    int
	useF string
}

func newRepeatVerb(p *parsed) *repeatVerb {
	return &repeatVerb{n: atoi(p.S["-n"], 1), useF: p.S["-f"]}
}

func (v *repeatVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	count := v.n
	if v.useF != "" {
		val, ok := rec.Get(v.useF)
		if !ok {
			return nil, nil
		}
		count = int(toInt(val))
	}
	if count < 0 {
		count = 0
	}
	out := []*Record{}
	for i := 0; i < count; i++ {
		out = append(out, rec.Clone())
	}
	return out, nil
}

func (v *repeatVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *repeatVerb) Close() error                    { return nil }

// ---------- altkv ----------

type altkvVerb struct{}

func (v *altkvVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	items := []string{}
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		s := val.String()
		if s == "" {
			continue
		}
		items = append(items, strings.Split(s, ctx.opt.IFS)...)
	}
	out := NewMap()
	for i := 0; i+1 < len(items); i += 2 {
		out.Set(items[i], StringValue(items[i+1]))
	}
	if len(items)%2 == 1 {
		out.Set(strconv.Itoa(len(items)), StringValue(items[len(items)-1]))
	}
	return []*Record{out}, nil
}

func (v *altkvVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *altkvVerb) Close() error                    { return nil }

// ---------- case / clean-whitespace / unspace ----------

type caseVerb struct {
	keysOnly bool
	valsOnly bool
	fields   []string
	upper    bool
	lower    bool
	sentence bool
	title    bool
}

func newCaseVerb(p *parsed) *caseVerb {
	return &caseVerb{keysOnly: p.B["-k"], valsOnly: p.B["-v"], fields: fieldList(p.S["-f"]),
		upper: p.B["-u"], lower: p.B["-l"], sentence: p.B["-s"], title: p.B["-t"]}
}

func caseStr(s string, v *caseVerb) string {
	if v.upper {
		return strings.ToUpper(s)
	}
	if v.lower {
		return strings.ToLower(s)
	}
	if v.sentence {
		return upperFirst(strings.ToLower(s))
	}
	if v.title {
		words := strings.Split(s, " ")
		for i, w := range words {
			words[i] = upperFirst(strings.ToLower(w))
		}
		return strings.Join(words, " ")
	}
	return s
}

func upperFirst(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	r[0] = []rune(strings.ToUpper(string(r[0])))[0]
	return string(r)
}

func (v *caseVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		doKey := true
		doVal := true
		if v.keysOnly {
			doVal = false
		}
		if v.valsOnly {
			doKey = false
		}
		if len(v.fields) > 0 {
			found := false
			for _, f := range v.fields {
				if k == f {
					found = true
					break
				}
			}
			if !found {
				doKey = false
				doVal = false
			}
		}
		nk := k
		nv := val
		if doKey {
			nk = caseStr(k, v)
		}
		if doVal {
			nv = StringValue(caseStr(val.String(), v))
		}
		out.Set(nk, nv)
	}
	return []*Record{out}, nil
}

func (v *caseVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *caseVerb) Close() error                    { return nil }

type cleanWhitespaceVerb struct{ keysOnly, valsOnly bool }

func newCleanWhitespaceVerb(p *parsed) *cleanWhitespaceVerb {
	return &cleanWhitespaceVerb{keysOnly: p.B["-k"], valsOnly: p.B["-v"]}
}

func cleanWhitespace(s string) string {
	s = strings.TrimSpace(s)
	fields := strings.Fields(s)
	return strings.Join(fields, " ")
}

func (v *cleanWhitespaceVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		nk := k
		nv := val
		if !v.valsOnly {
			nk = cleanWhitespace(k)
		}
		if !v.keysOnly {
			nv = StringValue(cleanWhitespace(val.String()))
		}
		out.Set(nk, nv)
	}
	return []*Record{out}, nil
}

func (v *cleanWhitespaceVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *cleanWhitespaceVerb) Close() error                    { return nil }

type unspaceVerb struct {
	filler              string
	keysOnly, valsOnly  bool
	fields              []string
}

func newUnspaceVerb(p *parsed) *unspaceVerb {
	f := p.S["-f"]
	if f == "" {
		f = "_"
	}
	return &unspaceVerb{filler: f, keysOnly: p.B["-k"], valsOnly: p.B["-v"], fields: fieldList(p.S["-f"])}
}

func (v *unspaceVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		inField := len(v.fields) == 0
		for _, f := range v.fields {
			if k == f {
				inField = true
			}
		}
		nk := k
		nv := val
		if !v.valsOnly && inField {
			nk = strings.ReplaceAll(k, " ", v.filler)
		}
		if !v.keysOnly && inField {
			nv = StringValue(strings.ReplaceAll(val.String(), " ", v.filler))
		}
		out.Set(nk, nv)
	}
	return []*Record{out}, nil
}

func (v *unspaceVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *unspaceVerb) Close() error                    { return nil }

// ---------- decimate / gap ----------

type decimateVerb struct {
	everyN    bool
	everyLast bool
	groups    []string
	n         int
	counts    map[string]int64
}

func newDecimateVerb(p *parsed) *decimateVerb {
	return &decimateVerb{everyN: p.B["-b"], everyLast: p.B["-e"] || !p.B["-b"],
		groups: fieldList(p.S["-g"]), n: atoi(p.S["-n"], 10), counts: map[string]int64{}}
}

func (v *decimateVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	key := groupKey(rec, v.groups)
	v.counts[key]++
	c := v.counts[key]
	if v.n <= 0 {
		return nil, nil
	}
	if v.everyN {
		if c%int64(v.n) == 1 {
			return []*Record{rec}, nil
		}
		return nil, nil
	}
	if c%int64(v.n) == 0 {
		return []*Record{rec}, nil
	}
	return nil, nil
}

func (v *decimateVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *decimateVerb) Close() error                    { return nil }

type gapVerb struct {
	groups  []string
	n       int
	count   int64
	last    string
	hasLast bool
}

func newGapVerb(p *parsed) *gapVerb {
	return &gapVerb{groups: fieldList(p.S["-g"]), n: atoi(p.S["-n"], 0)}
}

func (v *gapVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := []*Record{}
	if len(v.groups) > 0 {
		key := groupKey(rec, v.groups)
		if v.hasLast && key != v.last {
			out = append(out, NewMap())
		}
		v.last = key
		v.hasLast = true
		return out, nil
	}
	if v.n <= 0 {
		return out, nil
	}
	v.count++
	if v.count%int64(v.n) == 0 {
		out = append(out, NewMap())
	}
	return out, nil
}

func (v *gapVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *gapVerb) Close() error                    { return nil }

// ---------- fill-down / fill-empty ----------

type fillDownVerb struct {
	fields       []string
	all          bool
	onlyIfAbsent bool
	last         map[string]Value
}

func newFillDownVerb(p *parsed) *fillDownVerb {
	return &fillDownVerb{fields: fieldList(p.S["-f"]), all: p.B["--all"],
		onlyIfAbsent: p.B["-a"] || p.B["--only-if-absent"], last: map[string]Value{}}
}

func (v *fillDownVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	var fields []string
	if v.all {
		fields = rec.Keys()
	} else {
		fields = v.fields
	}
	for _, f := range fields {
		val, ok := out.Get(f)
		if ok {
			if !v.onlyIfAbsent && val.Kind == KindString && val.S == "" {
				if last, ok2 := v.last[f]; ok2 {
					out.Set(f, last)
				}
				continue
			}
			v.last[f] = val
			continue
		}
		if last, ok2 := v.last[f]; ok2 {
			out.Set(f, last)
		}
	}
	return []*Record{out}, nil
}

func (v *fillDownVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *fillDownVerb) Close() error                    { return nil }

type fillEmptyVerb struct{ fill string }

func newFillEmptyVerb(p *parsed, o *Options) *fillEmptyVerb {
	return &fillEmptyVerb{fill: p.S["-v"]}
}

func (v *fillEmptyVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	for _, k := range rec.Keys() {
		val, _ := rec.Get(k)
		if val.Kind == KindString && val.S == "" {
			if v.fill == "" {
				out.Set(k, StringValue("N/A"))
			} else {
				out.Set(k, inferValue(v.fill, ctx.opt))
			}
		}
	}
	return []*Record{out}, nil
}

func (v *fillEmptyVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *fillEmptyVerb) Close() error                    { return nil }

// ---------- sparsify ----------

type sparsifyVerb struct {
	filler string
	fields []string
}

func newSparsifyVerb(p *parsed) *sparsifyVerb {
	return &sparsifyVerb{filler: p.S["-s"], fields: fieldList(p.S["-f"])}
}

func (v *sparsifyVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	for _, k := range rec.Keys() {
		if len(v.fields) > 0 {
			found := false
			for _, f := range v.fields {
				if k == f {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}
		val, _ := rec.Get(k)
		if val.Kind == KindString && val.S == v.filler {
			out.Unset(k)
		}
	}
	return []*Record{out}, nil
}

func (v *sparsifyVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *sparsifyVerb) Close() error                    { return nil }

// ---------- template ----------

type templateVerb struct {
	fields   []string
	fillWith string
}

func newTemplateVerb(p *parsed) *templateVerb {
	return &templateVerb{fields: fieldList(p.S["-f"]), fillWith: p.S["--fill-with"]}
}

func (v *templateVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := NewMap()
	for _, f := range v.fields {
		val, ok := rec.Get(f)
		if !ok {
			val = StringValue(v.fillWith)
		}
		out.Set(f, val)
	}
	return []*Record{out}, nil
}

func (v *templateVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *templateVerb) Close() error                    { return nil }

// ---------- rename ----------

type renameVerb struct {
	pairs    []string
	useRegex bool
	global   bool
}

func newRenameVerb(p *parsed, main string) *renameVerb {
	pairs := fieldList(main)
	if len(pairs) == 0 {
		pairs = fieldList(p.S["-f"])
	}
	return &renameVerb{pairs: pairs, useRegex: p.B["-r"], global: p.B["-g"]}
}

func (v *renameVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	out := rec.Clone()
	for i := 0; i+1 < len(v.pairs); i += 2 {
		old := v.pairs[i]
		nw := v.pairs[i+1]
		for _, k := range out.Keys() {
			if v.useRegex {
				re, err := regexCompileSpec(old, false)
				if err != nil {
					continue
				}
				if v.global {
					nk := replaceAllGroups(re, k, nw)
					if nk != k {
						val, _ := out.Get(k)
						out.Unset(k)
						out.Set(nk, val)
					}
				} else {
					if re.MatchString(k) {
						val, _ := out.Get(k)
						nk := replaceFirstGroup(re, k, nw)
						out.Unset(k)
						out.Set(nk, val)
					}
				}
				continue
			}
			if k == old {
				val, _ := out.Get(k)
				out.Unset(k)
				out.Set(nw, val)
			}
		}
	}
	return []*Record{out}, nil
}

func replaceFirstGroup(re *regexp.Regexp, s, tmpl string) string {
	m := re.FindStringSubmatchIndex(s)
	if m == nil {
		return s
	}
	var b strings.Builder
	b.WriteString(s[:m[0]])
	b.WriteString(expandGroups(re, s, m, tmpl))
	b.WriteString(s[m[1]:])
	return b.String()
}

func replaceAllGroups(re *regexp.Regexp, s, tmpl string) string {
	return re.ReplaceAllStringFunc(s, func(match string) string {
		m := re.FindStringSubmatchIndex(match)
		if m == nil {
			return match
		}
		return expandGroups(re, match, m, tmpl)
	})
}

func expandGroups(re *regexp.Regexp, s string, m []int, tmpl string) string {
	var b strings.Builder
	for i := 0; i < len(tmpl); i++ {
		if tmpl[i] == '\\' && i+1 < len(tmpl) && tmpl[i+1] >= '0' && tmpl[i+1] <= '9' {
			n := int(tmpl[i+1] - '0')
			if 2*n+1 < len(m) {
				b.WriteString(s[m[2*n]:m[2*n+1]])
			}
			i++
			continue
		}
		b.WriteByte(tmpl[i])
	}
	return b.String()
}

func (v *renameVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *renameVerb) Close() error                    { return nil }

// ---------- reorder ----------

type reorderVerb struct {
	fields   []string
	useRegex bool
	atEnd    bool
	before   string
	after    string
}

func newReorderVerb(p *parsed) *reorderVerb {
	return &reorderVerb{fields: fieldList(p.S["-f"]), useRegex: p.B["-r"], atEnd: p.B["-e"],
		before: p.S["-b"], after: p.S["-a"]}
}

func (v *reorderVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	moved := []*kv{}
	rest := []*kv{}
	movedKeys := map[string]bool{}
	for _, f := range v.fields {
		for _, k := range rec.Keys() {
			if movedKeys[k] {
				continue
			}
			if fieldNameMatches(k, f, v.useRegex) {
				val, _ := rec.Get(k)
				moved = append(moved, &kv{k: k, v: val})
				movedKeys[k] = true
			}
		}
	}
	for _, k := range rec.Keys() {
		if movedKeys[k] {
			continue
		}
		val, _ := rec.Get(k)
		rest = append(rest, &kv{k: k, v: val})
	}
	out := NewMap()
	if v.before != "" {
		beforeIdx := -1
		for i, p := range rest {
			if p.k == v.before {
				beforeIdx = i
				break
			}
		}
		if beforeIdx >= 0 {
			for i, p := range rest {
				if i == beforeIdx {
					for _, m := range moved {
						out.Set(m.k, m.v)
					}
				}
				out.Set(p.k, p.v)
			}
			return []*Record{out}, nil
		}
	}
	if v.after != "" {
		afterIdx := -1
		for i, p := range rest {
			if p.k == v.after {
				afterIdx = i
				break
			}
		}
		if afterIdx >= 0 {
			for i, p := range rest {
				out.Set(p.k, p.v)
				if i == afterIdx {
					for _, m := range moved {
						out.Set(m.k, m.v)
					}
				}
			}
			return []*Record{out}, nil
		}
	}
	if v.atEnd {
		for _, p := range rest {
			out.Set(p.k, p.v)
		}
		for _, m := range moved {
			out.Set(m.k, m.v)
		}
		return []*Record{out}, nil
	}
	for _, m := range moved {
		out.Set(m.k, m.v)
	}
	for _, p := range rest {
		out.Set(p.k, p.v)
	}
	return []*Record{out}, nil
}

func (v *reorderVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *reorderVerb) Close() error                    { return nil }

// ---------- grep ----------

type grepVerb struct {
	re       *regexp.Regexp
	invert   bool
	valsOnly bool
	pattern  string
}

func newGrepVerb(p *parsed, main string) (*grepVerb, error) {
	if main == "" {
		return nil, fmt.Errorf("mlr: mlr grep: regular expression required")
	}
	re, err := regexCompileSpec(main, p.B["-i"])
	if err != nil {
		return nil, fmt.Errorf("mlr: mlr grep: invalid regex \"%s\"", main)
	}
	return &grepVerb{re: re, invert: p.B["-v"], valsOnly: p.B["-a"], pattern: main}, nil
}

func (v *grepVerb) Process(rec *Record, ctx *Ctx) ([]*Record, error) {
	var b strings.Builder
	if v.valsOnly {
		for i, k := range rec.Keys() {
			val, _ := rec.Get(k)
			if i > 0 {
				b.WriteString(ctx.opt.OFS)
			}
			b.WriteString(val.String())
		}
	} else {
		for i, k := range rec.Keys() {
			val, _ := rec.Get(k)
			if i > 0 {
				b.WriteString(",")
			}
			b.WriteString(k)
			b.WriteString("=")
			b.WriteString(val.String())
		}
	}
	m := v.re.MatchString(b.String())
	if v.invert {
		m = !m
	}
	if !m {
		return nil, nil
	}
	return []*Record{rec}, nil
}

func (v *grepVerb) End(ctx *Ctx) ([]*Record, error) { return nil, nil }
func (v *grepVerb) Close() error                    { return nil }
