new='''func dkvpRecord(opt *Options, fields []string) *Record {
	type pkv struct {
		k string
		v Value
	}
	pairs := []pkv{}
	next := 1
	keyless := 0
	for _, f := range fields {
		var k, v string
		if i := strings.Index(f, opt.IPS); i >= 0 {
			k = f[:i]
			v = f[i+len(opt.IPS):]
		} else {
			v = f
			if opt.IncrKey {
				keyless++
				k = strconv.Itoa(keyless)
			} else {
				k = strconv.Itoa(next)
			}
		}
		next++
		pairs = append(pairs, pkv{k, inferValue(v, opt)})
	}
	rec := NewMap()
	if opt == nil || opt.DedupeNames {
		counts := map[string]int{}
		for _, p := range pairs {
			counts[p.k]++
		}
		seen := map[string]int{}
		for _, p := range pairs {
			nk := p.k
			if counts[p.k] > 1 {
				seen[p.k]++
				if seen[p.k] > 1 {
					nk = p.k + "_" + strconv.Itoa(seen[p.k])
				}
			}
			rec.Set(nk, p.v)
		}
		return rec
	}
	for _, p := range pairs {
		rec.Set(p.k, p.v)
	}
	return rec
}

'''
