		case "$[":
			kind = "fieldidx"
		case "$ [[":
			kind = "fieldnameidx"
		}
		if sigil == "$[[" {
			kind = "fieldnameidx"
		}
		if sigil == "$[[[" {
			kind = "fieldpairidx"
		}
		return &Node{Kind: kind, Left: idx}, nil'''
new='''	case "$[", "$[[", "$[[[":
		nb := strings.Count(sigil, "[")
		idx, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		for i := 0; i < nb; i++ {
			if err := p.expect(tPunct, "]"); err != nil {
				return nil, err
			}
		}
		kind := "fieldidx"
		if sigil == "$[[" {
			kind = "fieldnameidx"
		}
		if sigil == "$[[[" {
			kind = "fieldpairidx"
		}
		return &Node{Kind: kind, Left: idx}, nil'''
assert old in s
s=s.replace(old,new)
