			kind = "oosnameidx"
		}
		if sigil == "@[[[" {
			kind = "oospairidx"
		}
		return &Node{Kind: kind, Left: idx}, nil'''
new2='''	case "@[", "@[[", "@[[[":
		nb2 := strings.Count(sigil, "[")
